    w("schema.json",s)
    for d in [None,"4","6","7","2019","2020"]:
        for out in ["text","flag"]:
            args=["schema.json","--output",out]+(["--draft",d] if d else [])
            show(f"only draft={d} out={out} s={s}", run(args))
# list output schemaLocation identifies meta used in schema-only
w("schema.json",{"type":"string"})
for d in [None,"4","7","2020"]:
    args=["schema.json","--output","list"]+(["--draft",d] if d else [])
    r=run(args); print("list meta draft",d, r.stdout[:300])
# list output WITH instance and draft mismatch $schema7 draft2020: what units?
w("schema.json",{"$schema":"http://json-schema.org/draft-07/schema#","type":"string"}); w("inst.json",'42')
for out in ["flag","list","hierarchical"]:
    show(f"mismatch list {out}", run(["schema.json","-i","inst.json","--draft","2020","--output",out]))
    show(f"mismatch ok draft7 {out}", run(["schema.json","-i","inst.json","--draft","7","--output",out]))
# with instance, meta gate for mismatch: schema invalid under forced? e.g. $schema 2020, exclusiveMinimum true, draft 4 -> with inst should meta-validate as draft4 valid and validate as draft4 bool semantics
w("schema.json",{"$schema":"https://json-schema.org/draft/2020-12/schema","minimum":5,"exclusiveMinimum":True}); w("inst.json",'5')
for d in [None,"4","2020"]:
    args=["schema.json","-i","inst.json"]+(["--draft",d] if d else [])
    show(f"cross exclBool draft={d}", run(args))
# Does assert-format affect meta-validation? bad pattern etc already; format in schema meta: e.g. default meta validates? {"format":123}
w("schema.json",{"format":123}); show("format123 only",run(["schema.json"]))
# assert-format with schema-only flag: meta validator with assertion? schema {"pattern":"[bad"} non-text gave Error not meta payload, maybe meta valid (format annotation) then build fails. If --assert-format, meta check maybe...?
w("schema.json",{"pattern":"[bad"})
for extra in [[],["--assert-format"],["--no-assert-format"]]:
    for out in ["text","flag","list"]:
        show(f"badpattern only {out} {extra}", run(["schema.json","--output",out]+extra))
# format assertion in meta: schema with $schema not uri? eg $id invalid uri-reference format?
w("schema.json",{"$id":":: not uri"})
for extra in [[],["--assert-format"]]:
    show(f"bad id only {extra}", run(["schema.json"]+extra))
    show(f"bad id flag {extra}", run(["schema.json","--output","flag"]+extra))
