use serde_json::Value;
use std::cmp::Ordering;

// Decimal representation: sign * digits * 10^exp  (digits has no leading/trailing zeros unless zero)
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Decimal {
    pub sign: i8, // -1,0,1
    pub digits: String,
    pub exp: i64,
}

pub fn parse_decimal(s: &str) -> Option<Decimal> {
    // s is a JSON number string from serde_json
    let bytes = s.as_bytes();
    let mut i = 0usize;
    let mut neg = false;
    if i < bytes.len() && bytes[i] == b'-' { neg = true; i += 1; }
    let mut int_part = String::new();
    while i < bytes.len() && bytes[i].is_ascii_digit() { int_part.push(bytes[i] as char); i += 1; }
    let mut frac_part = String::new();
    if i < bytes.len() && bytes[i] == b'.' {
        i += 1;
        while i < bytes.len() && bytes[i].is_ascii_digit() { frac_part.push(bytes[i] as char); i += 1; }
    }
    let mut exp: i64 = -(frac_part.len() as i64);
    if i < bytes.len() && (bytes[i] == b'e' || bytes[i] == b'E') {
        i += 1;
        let mut eneg = false;
        if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') { eneg = bytes[i] == b'-'; i += 1; }
        let mut e: i64 = 0;
        let mut any = false;
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            any = true;
            e = e.saturating_mul(10).saturating_add((bytes[i] - b'0') as i64);
            i += 1;
        }
        if !any { return None; }
        if eneg { e = -e; }
        exp = exp.saturating_add(e);
    }
    if int_part.is_empty() && frac_part.is_empty() { return None; }
    let mut digits = format!("{}{}", int_part, frac_part);
    // strip leading zeros
    let stripped = digits.trim_start_matches('0').to_string();
    if stripped.is_empty() {
        return Some(Decimal { sign: 0, digits: "0".to_string(), exp: 0 });
    }
    digits = stripped;
    // strip trailing zeros
    let mut trailing = 0i64;
    while digits.ends_with('0') { digits.pop(); trailing += 1; }
    exp = exp.saturating_add(trailing);
    Some(Decimal { sign: if neg { -1 } else { 1 }, digits, exp })
}

pub fn decimal_of(v: &Value) -> Option<Decimal> {
    v.as_number().and_then(|n| parse_decimal(&n.to_string()))
}

impl Decimal {
    pub fn is_integer(&self) -> bool {
        self.sign == 0 || self.exp >= 0
    }
    fn magnitude_cmp(&self, other: &Decimal) -> Ordering {
        // both non-zero, compare absolute values
        let adj1 = self.exp.saturating_add(self.digits.len() as i64);
        let adj2 = other.exp.saturating_add(other.digits.len() as i64);
        if adj1 != adj2 { return adj1.cmp(&adj2); }
        // compare digit strings padded with zeros
        let maxlen = self.digits.len().max(other.digits.len());
        for i in 0..maxlen {
            let d1 = self.digits.as_bytes().get(i).copied().unwrap_or(b'0');
            let d2 = other.digits.as_bytes().get(i).copied().unwrap_or(b'0');
            if d1 != d2 { return d1.cmp(&d2); }
        }
        Ordering::Equal
    }
    pub fn cmp_dec(&self, other: &Decimal) -> Ordering {
        if self.sign != other.sign { return self.sign.cmp(&other.sign); }
        if self.sign == 0 { return Ordering::Equal; }
        let m = self.magnitude_cmp(other);
        if self.sign < 0 { m.reverse() } else { m }
    }
    pub fn to_f64(&self) -> Option<f64> { None }
}

// Big unsigned integer as Vec<u32> little-endian base 1e9, for multipleOf
fn digits_to_big(digits: &str, exp: i64) -> Option<Vec<u32>> {
