    let mut v = Vec::new();
    let bytes = s.as_bytes();
    let mut end = bytes.len();
    while end > 0 {
        let start = if end >= 9 { end - 9 } else { 0 };
        let chunk: u32 = std::str::from_utf8(&bytes[start..end]).unwrap_or("0").parse().unwrap_or(0);
        v.push(chunk);
        end = start;
    }
    while v.len() > 1 && *v.last().unwrap() == 0 { v.pop(); }
