// Minimal RFC3986 URI-reference handling with fluent-uri-like error messages.

#[derive(Debug, Clone)]
pub struct UriError(pub String); // inner reason e.g. "unexpected character at index 3"
impl std::fmt::Display for UriError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result { write!(f, "{}", self.0) }
}

pub fn invalid_uri_error(original: &str, reason: &str) -> String {
    format!("Invalid URI reference '{}': {}", original, reason)
}

fn is_unreserved(c: u8) -> bool { c.is_ascii_alphanumeric() || matches!(c, b'-' | b'.' | b'_' | b'~') }
fn is_subdelim(c: u8) -> bool { matches!(c, b'!' | b'$' | b'&' | b'\'' | b'(' | b')' | b'*' | b'+' | b',' | b';' | b'=') }
fn is_pchar(c: u8) -> bool { is_unreserved(c) || is_subdelim(c) || matches!(c, b':' | b'@') }
fn is_hex(c: u8) -> bool { c.is_ascii_hexdigit() }

fn check_pct(s: &str) -> Result<(), UriError> {
    let b = s.as_bytes();
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'%' {
            if i + 2 >= b.len() + 1 || i + 2 > b.len() - 1 || !is_hex(b[i+1]) || i + 2 >= b.len() || !is_hex(b.get(i+2).copied().unwrap_or(0)) {
                // simpler:
                if !(i + 2 < b.len() && is_hex(b[i+1]) && is_hex(b[i+2])) {
                    return Err(UriError(format!("invalid percent-encoded octet at index {}", i)));
                }
            }
            i += 3;
        } else { i += 1; }
    }
    Ok(())
}

pub fn validate_uri_reference(s: &str) -> Result<(), UriError> {
    let b = s.as_bytes();
    // percent checks have their own message; but order: fluent parser likely reports
    // percent error when it encounters it in scanning order relative to other invalid chars.
    // We scan left to right interleaving structural checks loosely.
    // First generic scan for disallowed chars and percent, tracking bracket context for authority.
    // Determine positions
    // Scan byte by byte:
    let mut i = 0usize;
    while i < b.len() {
        let c = b[i];
        if c == b'%' {
            if !(i + 2 < b.len() && is_hex(b[i+1]) && is_hex(b[i+2])) {
                return Err(UriError(format!("invalid percent-encoded octet at index {}", i)));
            }
            i += 3;
            continue;
        }
        // allowed general chars: unreserved / reserved (gen+sub) minus [ ] handled later
        let allowed = c.is_ascii_alphanumeric() || matches!(c, b'-' | b'.' | b'_' | b'~' | b':' | b'/' | b'?' | b'#' | b'[' | b']' | b'@' | b'!' | b'$' | b'&' | b'\'' | b'(' | b')' | b'*' | b'+' | b',' | b';' | b'=');
        if !allowed {
            return Err(UriError(format!("unexpected character at index {}", i)));
        }
        i += 1;
    }
    // Structural:
    // split fragment
    let (before_frag, _frag) = match s.find('#') { Some(idx) => (&s[..idx], Some(&s[idx+1..])), None => (s, None) };
    // scheme detection: first occurrence among : / ?
    let first_delim = before_frag.bytes().position(|c| matches!(c, b':' | b'/' | b'?'));
    let mut rest_start = 0usize;
    let mut has_scheme = false;
    if let Some(pos) = first_delim {
