                        // Return error at close bracket as approximation only if clearly invalid like too many groups.
                        return Err(UriError(format!("unexpected character at index {}", hostport_offset + close)));
                    }
                }
                let after = &hostport[close+1..];
                if !after.is_empty() {
                    if !after.starts_with(':') {
                        return Err(UriError(format!("unexpected character at index {}", hostport_offset + close + 1)));
                    }
                    validate_port(&after[1..], hostport_offset + close + 2)?;
