#[derive(Debug, Clone, PartialEq)]
pub struct UriParts {
    pub scheme: Option<String>,
    pub authority: Option<String>,
    pub path: String,
    pub query: Option<String>,
    pub fragment: Option<String>,
}

pub fn parse_uri_reference(s: &str) -> UriParts {
    let (rest, fragment) = match s.find('#') {
        Some(i) => (&s[..i], Some(s[i+1..].to_string())),
        None => (s, None),
    };
    let (rest, query) = match rest.find('?') {
        Some(i) => (&rest[..i], Some(rest[i+1..].to_string())),
        None => (rest, None),
    };
    // scheme
    let mut scheme = None;
    let mut rest2 = rest;
    if let Some(pos) = rest.bytes().position(|c| matches!(c, b':' | b'/' )) {
        if rest.as_bytes()[pos] == b':' {
            let cand = &rest[..pos];
            if !cand.is_empty() && cand.as_bytes()[0].is_ascii_alphabetic() && cand.bytes().all(|c| c.is_ascii_alphanumeric() || matches!(c,b'+'|b'-'|b'.')) {
                scheme = Some(cand.to_string());
                rest2 = &rest[pos+1..];
            }
        }
    }
    let (authority, path) = if let Some(stripped) = rest2.strip_prefix("//") {
        match stripped.find('/') {
            Some(i) => (Some(stripped[..i].to_string()), stripped[i..].to_string()),
            None => (Some(stripped.to_string()), String::new()),
        }
    } else {
        (None, rest2.to_string())
    };
    UriParts { scheme, authority, path, query, fragment }
}

impl UriParts {
    pub fn to_string(&self) -> String {
        let mut out = String::new();
        if let Some(s) = &self.scheme { out.push_str(s); out.push(':'); }
        if let Some(a) = &self.authority { out.push_str("//"); out.push_str(a); }
        out.push_str(&self.path);
        if let Some(q) = &self.query { out.push('?'); out.push_str(q); }
        if let Some(f) = &self.fragment { out.push('#'); out.push_str(f); }
        out
    }
    pub fn without_fragment(&self) -> String {
        let mut p = self.clone(); p.fragment = None; p.to_string()
    }
}

fn remove_dot_segments(path: &str) -> String {
    // RFC 3986 5.2.4
    let mut input: Vec<String> = Vec::new();
    // We'll implement with string algorithm
    let mut output = String::new();
    let mut inp = path.to_string();
    while !inp.is_empty() {
        if inp.starts_with("../") { inp.drain(..3); }
        else if inp.starts_with("./") { inp.drain(..2); }
        else if inp.starts_with("/./") { inp.drain(..2); } // replace with / -> keep one /
        else if inp == "/." { inp = "/".to_string(); }
        else if inp.starts_with("/../") { inp.drain(..3); remove_last_segment(&mut output); }
        else if inp == "/.." { inp = "/".to_string(); remove_last_segment(&mut output); }
        else if inp == "." || inp == ".." { inp.clear(); }
        else {
            // move first path segment to output
            let start = if inp.starts_with('/') { 1 } else { 0 };
            let end = inp[start..].find('/').map(|i| start + i).unwrap_or(inp.len());
            output.push_str(&inp[..end]);
            inp.drain(..end);
        }
    }
    let _ = input;
    output
}
fn remove_last_segment(output: &mut String) {
    match output.rfind('/') {
        Some(i) => output.truncate(i),
        None => output.clear(),
    }
}
fn merge_paths(base: &UriParts, rel_path: &str) -> String {
    if base.authority.is_some() && base.path.is_empty() {
        format!("/{}", rel_path)
    } else {
        match base.path.rfind('/') {
            Some(i) => format!("{}{}", &base.path[..=i], rel_path),
            None => rel_path.to_string(),
        }
    }
}

pub fn resolve(base: &str, reference: &str) -> String {
    let b = parse_uri_reference(base);
    let r = parse_uri_reference(reference);
    let t = resolve_parts(&b, &r);
    t.to_string()
}
pub fn resolve_parts(b: &UriParts, r: &UriParts) -> UriParts {
    if let Some(scheme) = &r.scheme {
        let mut t = r.clone();
        t.scheme = Some(scheme.clone());
        t.path = remove_dot_segments(&r.path);
        t
    } else if let Some(auth) = &r.authority {
        UriParts { scheme: b.scheme.clone(), authority: Some(auth.clone()), path: remove_dot_segments(&r.path), query: r.query.clone(), fragment: r.fragment.clone() }
    } else if r.path.is_empty() {
        UriParts { scheme: b.scheme.clone(), authority: b.authority.clone(), path: b.path.clone(), query: r.query.clone().or_else(|| b.query.clone()), fragment: r.fragment.clone() }
    } else if r.path.starts_with('/') {
        UriParts { scheme: b.scheme.clone(), authority: b.authority.clone(), path: remove_dot_segments(&r.path), query: r.query.clone(), fragment: r.fragment.clone() }
    } else {
        let merged = merge_paths(b, &r.path);
        UriParts { scheme: b.scheme.clone(), authority: b.authority.clone(), path: remove_dot_segments(&merged), query: r.query.clone(), fragment: r.fragment.clone() }
    }
}

pub fn split_fragment(uri: &str) -> (&str, Option<&str>) {
    match uri.find('#') {
        Some(i) => (&uri[..i], Some(&uri[i+1..])),
        None => (uri, None),
    }
}
pub fn scheme_of(uri: &str) -> Option<String> {
    parse_uri_reference(uri).scheme
}

// Percent decode (for pointers & file paths). Invalid sequences left as-is.
pub fn percent_decode(s: &str) -> String {
    let b = s.as_bytes();
    let mut out: Vec<u8> = Vec::new();
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'%' && i + 2 < b.len() && is_hex(b[i+1]) && is_hex(b[i+2]) {
            let h = |c: u8| -> u8 { match c { b'0'..=b'9' => c - b'0', b'a'..=b'f' => c - b'a' + 10, b'A'..=b'F' => c - b'A' + 10, _ => 0 } };
            out.push(h(b[i+1]) * 16 + h(b[i+2]));
            i += 3;
        } else {
            out.push(b[i]);
            i += 1;
        }
    }
    String::from_utf8_lossy(&out).to_string()
}

pub fn percent_encode_path(path: &str) -> String {
    // Encode chars not allowed in a URI path (keep pchar and /)
    let mut out = String::new();
    for &c in path.as_bytes() {
        if is_pchar(c) || c == b'/' {
            out.push(c as char);
        } else {
            out.push_str(&format!("%{:02X}", c));
        }
    }
    out
}

// JSON Pointer helpers
pub fn escape_pointer_token(t: &str) -> String {
    t.replace('~', "~0").replace('/', "~1")
}
pub fn unescape_pointer_token(t: &str) -> String {
    t.replace("~1", "/").replace("~0", "~")
}
pub fn parse_pointer(ptr: &str) -> Vec<String> {
    if ptr.is_empty() { return Vec::new(); }
    ptr.split('/').skip(1).map(|t| unescape_pointer_token(t)).collect()
}
pub fn pointer_from_tokens(tokens: &[String]) -> String {
    let mut s = String::new();
    for t in tokens { s.push('/'); s.push_str(&escape_pointer_token(t)); }
    s
}

// Build file URI from absolute path (string form, may be lossy for non-utf8 handled by caller)
pub fn file_uri_from_path(abs_path: &str) -> String {
    let enc = percent_encode_path(abs_path);
    if enc.starts_with('/') {
        format!("file://{}", enc)
    } else {
        format!("file:///{}", enc)
    }
}

// Convert a file: URI to a filesystem path string. Returns None if not usable.
pub fn file_uri_to_path(uri: &str) -> Option<String> {
    let p = parse_uri_reference(uri);
    if !matches!(p.scheme.as_deref(), Some(s) if s.eq_ignore_ascii_case("file")) { return None; }
    match p.authority.as_deref() {
        None | Some("") | Some("localhost") => Some(percent_decode(&p.path)),
        Some(host) => {
            // network path //host/path
            Some(format!("//{}{}", host, percent_decode(&p.path)))
        }
    }
}
