        match self {
            Draft::D4 => "http://json-schema.org/draft-04/schema#",
            Draft::D6 => "http://json-schema.org/draft-06/schema#",
            Draft::D7 => "http://json-schema.org/draft-07/schema#",
            Draft::D2019 => "https://json-schema.org/draft/2019-09/schema",
            Draft::D2020 => "https://json-schema.org/draft/2020-12/schema",
        }
    }
    pub fn from_cli(s: &str) -> Option<Draft> {
        Some(match s { "4" => Draft::D4, "6" => Draft::D6, "7" => Draft::D7, "2019" => Draft::D2019, "2020" => Draft::D2020, _ => return None })
    }
}

pub fn standard_draft_for_meta_uri(uri: &str) -> Option<Draft> {
    let base = uri.strip_suffix('#').unwrap_or(uri);
    let candidates: &[(&str, Draft)] = &[
        ("http://json-schema.org/draft-04/schema", Draft::D4),
        ("https://json-schema.org/draft-04/schema", Draft::D4),
        ("http://json-schema.org/draft-06/schema", Draft::D6),
        ("https://json-schema.org/draft-06/schema", Draft::D6),
        ("http://json-schema.org/draft-07/schema", Draft::D7),
        ("https://json-schema.org/draft-07/schema", Draft::D7),
        ("http://json-schema.org/draft/2019-09/schema", Draft::D2019),
        ("https://json-schema.org/draft/2019-09/schema", Draft::D2019),
        ("http://json-schema.org/draft/2020-12/schema", Draft::D2020),
        ("https://json-schema.org/draft/2020-12/schema", Draft::D2020),
    ];
    candidates.iter().find(|(u, _)| *u == base).map(|(_, d)| *d)
}

fn parse(s: &str) -> Value { serde_json::from_str(s).expect("embedded meta") }

pub fn embedded_resource(uri_no_frag: &str) -> Option<Value> {
    let map = embedded_map();
    map.get(uri_no_frag).cloned()
}

pub fn embedded_map() -> &'static HashMap<String, Value> {
    static MAP: OnceLock<HashMap<String, Value>> = OnceLock::new();
    MAP.get_or_init(|| {
        let mut m = HashMap::new();
        let mut add = |uri: &str, doc: &str, m: &mut HashMap<String, Value>| { m.insert(uri.to_string(), parse(doc)); };
        add("http://json-schema.org/draft-04/schema", DRAFT4, &mut m);
        add("http://json-schema.org/draft-06/schema", DRAFT6, &mut m);
        add("http://json-schema.org/draft-07/schema", DRAFT7, &mut m);
        add("https://json-schema.org/draft/2019-09/schema", ROOT2019, &mut m);
        add("https://json-schema.org/draft/2019-09/meta/core", CORE2019, &mut m);
        add("https://json-schema.org/draft/2019-09/meta/applicator", APP2019, &mut m);
        add("https://json-schema.org/draft/2019-09/meta/validation", VAL2019, &mut m);
        add("https://json-schema.org/draft/2019-09/meta/meta-data", MD2019, &mut m);
        add("https://json-schema.org/draft/2019-09/meta/format", FMT2019, &mut m);
        add("https://json-schema.org/draft/2019-09/meta/content", CONTENT2019, &mut m);
        add("https://json-schema.org/draft/2020-12/schema", ROOT2020, &mut m);
        add("https://json-schema.org/draft/2020-12/meta/core", CORE2020, &mut m);
        add("https://json-schema.org/draft/2020-12/meta/applicator", APP2020, &mut m);
        add("https://json-schema.org/draft/2020-12/meta/unevaluated", UNEV2020, &mut m);
        add("https://json-schema.org/draft/2020-12/meta/validation", VAL2020, &mut m);
        add("https://json-schema.org/draft/2020-12/meta/meta-data", MD2020, &mut m);
        add("https://json-schema.org/draft/2020-12/meta/format-annotation", FMTANN2020, &mut m);
        add("https://json-schema.org/draft/2020-12/meta/format-assertion", FMTASS2020, &mut m);
        add("https://json-schema.org/draft/2020-12/meta/content", CONTENT2020, &mut m);
        m
    })
}

pub fn meta_doc_for_draft(d: Draft) -> Value {
    let uri = match d {
        Draft::D4 => "http://json-schema.org/draft-04/schema",
        Draft::D6 => "http://json-schema.org/draft-06/schema",
        Draft::D7 => "http://json-schema.org/draft-07/schema",
        Draft::D2019 => "https://json-schema.org/draft/2019-09/schema",
        Draft::D2020 => "https://json-schema.org/draft/2020-12/schema",
    };
    embedded_resource(uri).unwrap()
}

