{"command":"cat > src/formats.rs <<'RS'
use crate::meta::Draft;

pub fn format_is_known(fmt: &str, draft: Draft) -> bool {
    match fmt {
        "date-time"|"date"|"time"|"email"|"idn-email"|"hostname"|"ipv4"|"ipv6"|"uri"|"regex" => true,
        "uri-reference"|"uri-template"|"json-pointer" => draft != Draft::D4,
        "idn-hostname"|"iri"|"iri-reference"|"relative-json-pointer" => !matches!(draft, Draft::D4|Draft::D6),
        "duration"|"uuid" => matches!(draft, Draft::D2019|Draft::D2020),
        _ => false,
    }
}

pub fn check_format(fmt: &str, s: &str) -> bool {
    match fmt {
        "date-time" => check_date_time(s),
        "date" => check_date(s),
        "time" => check_time(s),
        "duration" => check_duration(s),
        "email" | "idn-email" => check_email(s),
        "hostname" => check_hostname(s, false),
        "idn-hostname" => check_hostname(s, true),
        "ipv4" => check_ipv4(s),
        "ipv6" => s.parse::<std::net::Ipv6Addr>().is_ok(),
        "uri" => check_uri(s, true, false),
        "uri-reference" => check_uri(s, false, false),
        "iri" => check_uri(s, true, true),
        "iri-reference" => check_uri(s, false, true),
        "uri-template" => check_uri_template(s),
        "uuid" => check_uuid(s),
        "regex" => crate::regexconv::compile_regex(s).is_ok(),
        "json-pointer" => check_json_pointer(s),
        "relative-json-pointer" => check_relative_json_pointer(s),
        _ => true,
    }
}

fn days_in_month(y: i64, m: u32) -> u32 {
    match m {
        1|3|5|7|8|10|12 => 31,
        4|6|9|11 => 30,
        2 => if (y % 4 == 0 && y % 100 != 0) || y % 400 == 0 { 29 } else { 28 },
        _ => 0,
    }
}
fn parse_fixed(s: &str, start: usize, len: usize) -> Option<i64> {
    let sub = s.get(start..start+len)?;
    if !sub.bytes().all(|c| c.is_ascii_digit()) { return None; }
    sub.parse().ok()
}
fn check_date(s: &str) -> bool {
    // YYYY-MM-DD
    let b = s.as_bytes();
    if b.len() != 10 || b[4] != b'-' || b[7] != b'-' { return false; }
    let y = match parse_fixed(s,0,4) { Some(v)=>v, None=>return false };
    let m = match parse_fixed(s,5,2) { Some(v)=>v as u32, None=>return false };
    let d = match parse_fixed(s,8,2) { Some(v)=>v as u32, None=>return false };
    if m < 1 || m > 12 { return false; }
    d >= 1 && d <= days_in_month(y, m)
}
// returns remaining string after time offset position validation; checks HH:MM:SS(.frac)? offset
fn check_time_part(s: &str) -> bool {
    // HH:MM:SS[.fff](Z|+-HH:MM)
    let b = s.as_bytes();
    if b.len() < 9 { return false; }
    let hh = match parse_fixed(s,0,2) { Some(v)=>v, None=>return false };
    if b[2] != b':' { return false; }
    let mm = match parse_fixed(s,3,2) { Some(v)=>v, None=>return false };
    if b[5] != b':' { return false; }
    let ss = match parse_fixed(s,6,2) { Some(v)=>v, None=>return false };
    if hh > 23 || mm > 59 { return false; }
    // leap second: ss==60 allowed only 23:59:60
    if ss > 60 { return false; }
    if ss == 60 && !(hh == 23 && mm == 59) { return false; }
    let mut idx = 8;
    if idx < b.len() && b[idx] == b'.' {
        idx += 1;
        let start = idx;
        while idx < b.len() && b[idx].is_ascii_digit() { idx += 1; }
        if idx == start { return false; }
    }
    if idx >= b.len() { return false; }
    if b[idx] == b'Z' || b[idx] == b'z' {
        return idx + 1 == b.len();
    }
    if b[idx] == b'+' || b[idx] == b'-' {
        if s.len() != idx + 6 { return false; }
        let oh = match parse_fixed(s, idx+1, 2) { Some(v)=>v, None=>return false };
        if b[idx+3] != b':' { return false; }
        let om = match parse_fixed(s, idx+4, 2) { Some(v)=>v, None=>return false };
        // offset hour: spec allows up to 23? original rejects +24:00. RFC3339 time-numoffset hour 00-23
        return oh <= 23 && om <= 59;
    }
    false
}
fn check_time(s: &str) -> bool { check_time_part(s) }
fn check_date_time(s: &str) -> bool {
    let b = s.as_bytes();
    if b.len() < 20 { return false; }
    if b[10] != b'T' && b[10] != b't' { return false; }
    if !check_date(&s[..10]) { return false; }
    check_time_part(&s[11..])
}
fn check_duration(s: &str) -> bool {
    // ISO8601 duration as accepted by original: PnYnMnDTnHnMnS / PnW, integers only apparently
    // Grammar: P ( (\d+Y)? (\d+M)? (\d+D)? (T (\d+H)? (\d+M)? (\d+S)?)? | \d+W )
    let b = s.as_bytes();
    if b.len() < 2 || b[0] != b'P' { return false; }
    let mut i = 1usize;
    let mut any = false;
    // week form
    let rest = &s[1..];
    if rest.ends_with('W') && rest.len() >= 2 && rest[..rest.len()-1].bytes().all(|c| c.is_ascii_digit()) {
        return true;
    }
    let mut seen_t = false;
    let mut last_order = 0; // Y=1 M=2 D=3 (date), H=4 M=5 S=6
    let mut any_time = false;
    while i < b.len() {
        if b[i] == b'T' {
            if seen_t { return false; }
            seen_t = true; i += 1; continue;
        }
        let start = i;
        while i < b.len() && b[i].is_ascii_digit() { i += 1; }
        if i == start { return false; }
        if i >= b.len() { return false; }
        let desig = b[i] as char;
        let order = if !seen_t {
            match desig { 'Y'=>1, 'M'=>2, 'D'=>3, 'W'=> return false, _=> return false }
        } else {
            match desig { 'H'=>4, 'M'=>5, 'S'=>6, _=> return false }
        };
        if order <= last_order { return false; }
        last_order = order;
        i += 1;
        any = true;
        if seen_t { any_time = true; }
    }
    if seen_t && !any_time { return false; }
    any
}

fn check_email(s: &str) -> bool {
    // Pragmatic RFC5322-ish: local@domain ; local dot-atom (unicode allowed in original), domain dot-atom or [ip]
    let parts: Vec<&str> = s.rsplitn(2, '@').collect();
    if parts.len() != 2 { return false; }
    let (local, domain) = (parts[1], parts[0]);
    // must contain exactly one @? local quoted could contain, original probably uses a parser; approximate: no extra @ in local
    if local.contains('@') { return false; }
    if local.is_empty() || domain.is_empty() { return false; }
    if local.starts_with('.') || local.ends_with('.') || local.contains("..") { return false; }
    if local.bytes().any(|c| c.is_ascii_control() || matches!(c, b' ' | b'"' | b'(' | b')' | b',' | b':' | b';' | b'<' | b'>' | b'[' | b']' | b'\\')) { return false; }
    if domain.starts_with('[') && domain.ends_with(']') {
        let inside = &domain[1..domain.len()-1];
        return check_ipv4(inside) || inside.parse::<std::net::Ipv6Addr>().is_ok() || inside.to_lowercase().starts_with("ipv6:");
    }
    // domain labels alnum/hyphen, unicode letters allowed (idn-email & original email lenient)
    for label in domain.split('.') {
        if label.is_empty() { return false; }
        if label.starts_with('-') || label.ends_with('-') { return false; }
        if !label.chars().all(|c| c.is_alphanumeric() || c == '-') { return false; }
    }
    true
}

fn check_hostname(s: &str, idn: bool) -> bool {
    if s.is_empty() || s.len() > 253 { return false; }
    if s.ends_with('.') { return false; }
    for label in s.split('.') {
        if label.is_empty() || label.len() > 63 { return false; }
        if label.starts_with('-') || label.ends_with('-') { return false; }
        let ok = if idn {
            label.chars().all(|c| c.is_alphanumeric() || c == '-')
            // IDNA rules in original are more permissive (snowman accepted). Use unicode alphanumeric + some symbols? snowman U+2603 is not alphanumeric (So). Original accepted.
            || label.chars().all(|c| !c.is_control() && c != ' ' && c != '-')
        } else {
            label.bytes().all(|c| c.is_ascii_alphanumeric() || c == b'-')
        };
        if !ok { return false; }
        if idn {
            // reject ascii labels that are invalid hostname chars
            if label.bytes().any(|c| matches!(c, b'_' | b' ')) { return false; }
        }
    }
    true
}

fn check_ipv4(s: &str) -> bool {
    let parts: Vec<&str> = s.split('.').collect();
    if parts.len() != 4 { return false; }
    for p in parts {
        if p.is_empty() || p.len() > 3 { return false; }
        if !p.bytes().all(|c| c.is_ascii_digit()) { return false; }
        if p.len() > 1 && p.starts_with('0') { return false; }
        match p.parse::<u32>() { Ok(v) if v <= 255 => {}, _ => return false }
    }
    true
}

fn check_uri(s: &str, absolute: bool, iri: bool) -> bool {
    if !iri {
        if crate::uri::validate_uri_reference(s).is_err() { return false; }
    } else {
        // IRI: allow non-ascii except controls/space and disallowed ascii
        if s.chars().any(|c| c.is_control() || c == ' ' || matches!(c, '"'|'<'|'>'|'\\'|'^'|'`'|'{'|'}'|'|')) { return false; }
        // percent check
        let b = s.as_bytes();
        let mut i=0; while i<b.len() { if b[i]==b'%' { if !(i+2<b.len() && b[i+1].is_ascii_hexdigit() && b[i+2].is_ascii_hexdigit()) { return false; } i+=3; } else { i+=1; } }
        // brackets only authority - skip detailed
    }
    if absolute {
        let p = crate::uri::parse_uri_reference(s);
        p.scheme.is_some()
    } else { true }
}

fn check_uri_template(s: &str) -> bool {
    // Validate balanced {} expressions with valid varspecs; literal chars must be valid (no space/control/# disallowed?)
    let mut chars = s.char_indices().peekable();
    let mut in_expr = false;
    let mut expr = String::new();
    while let Some((_, c)) = chars.next() {
        if in_expr {
            if c == '}' {
                if expr.is_empty() { return false; }
                if !valid_template_expr(&expr) { return false; }
                expr.clear(); in_expr = false;
            } else if c == '{' { return false; } else { expr.push(c); }
        } else {
            if c == '{' { in_expr = true; }
            else if c == '}' { return false; }
            else if c.is_control() || c == ' ' { return false; }
        }
    }
    !in_expr
}
fn valid_template_expr(e: &str) -> bool {
    let mut s = e;
    if let Some(first) = s.chars().next() {
        if matches!(first, '+'|'#'|'.'|'/'|';'|'?'|'&') { s = &s[first.len_utf8()..]; }
    }
    if s.is_empty() { return false; }
    for var in s.split(',') {
        let v = var.strip_suffix('*').unwrap_or(var);
