        "idn-hostname"|"iri"|"iri-reference"|"relative-json-pointer" => !matches!(draft, Draft::D4|Draft::D6),
        "duration"|"uuid" => matches!(draft, Draft::D2019|Draft::D2020),
        _ => false,
    }
}

pub fn check_format(fmt: &str, s: &str) -> bool {
    match fmt {
        "date-time" => check_date_time(s),
        "date" => check_date(s),
        "time" => check_time(s),
        "duration" => check_duration(s),
        "email" | "idn-email" => check_email(s),
        "hostname" => check_hostname(s, false),
        "idn-hostname" => check_hostname(s, true),
        "ipv4" => check_ipv4(s),
        "ipv6" => s.parse::<std::net::Ipv6Addr>().is_ok(),
        "uri" => check_uri(s, true, false),
        "uri-reference" => check_uri(s, false, false),
        "iri" => check_uri(s, true, true),
        "iri-reference" => check_uri(s, false, true),
        "uri-template" => check_uri_template(s),
        "uuid" => check_uuid(s),
        "regex" => crate::regexconv::compile_regex(s).is_ok(),
        "json-pointer" => check_json_pointer(s),
        "relative-json-pointer" => check_relative_json_pointer(s),
        _ => true,
    }
}

fn days_in_month(y: i64, m: u32) -> u32 {
    match m {
        1|3|5|7|8|10|12 => 31,
        4|6|9|11 => 30,
        2 => if (y % 4 == 0 && y % 100 != 0) || y % 400 == 0 { 29 } else { 28 },
        _ => 0,
    }
}
fn parse_fixed(s: &str, start: usize, len: usize) -> Option<i64> {
    let sub = s.get(start..start+len)?;
    if !sub.bytes().all(|c| c.is_ascii_digit()) { return None; }
    sub.parse().ok()
}
fn check_date(s: &str) -> bool {
    // YYYY-MM-DD
    let b = s.as_bytes();
    if b.len() != 10 || b[4] != b'-' || b[7] != b'-' { return false; }
    let y = match parse_fixed(s,0,4) { Some(v)=>v, None=>return false };
    let m = match parse_fixed(s,5,2) { Some(v)=>v as u32, None=>return false };
    let d = match parse_fixed(s,8,2) { Some(v)=>v as u32, None=>return false };
    if m < 1 || m > 12 { return false; }
    d >= 1 && d <= days_in_month(y, m)
}
// returns remaining string after time offset position validation; checks HH:MM:SS(.frac)? offset
fn check_time_part(s: &str) -> bool {
    // HH:MM:SS[.fff](Z|+-HH:MM)
    let b = s.as_bytes();
    if b.len() < 9 { return false; }
    let hh = match parse_fixed(s,0,2) { Some(v)=>v, None=>return false };
    if b[2] != b':' { return false; }
    let mm = match parse_fixed(s,3,2) { Some(v)=>v, None=>return false };
    if b[5] != b':' { return false; }
    let ss = match parse_fixed(s,6,2) { Some(v)=>v, None=>return false };
    if hh > 23 || mm > 59 { return false; }
    // leap second: ss==60 allowed only 23:59:60
    if ss > 60 { return false; }
    if ss == 60 && !(hh == 23 && mm == 59) { return false; }
    let mut idx = 8;
    if idx < b.len() && b[idx] == b'.' {
        idx += 1;
        let start = idx;
        while idx < b.len() && b[idx].is_ascii_digit() { idx += 1; }
        if idx == start { return false; }
    }
    if idx >= b.len() { return false; }
    if b[idx] == b'Z' || b[idx] == b'z' {
        return idx + 1 == b.len();
    }
    if b[idx] == b'+' || b[idx] == b'-' {
        if s.len() != idx + 6 { return false; }
        let oh = match parse_fixed(s, idx+1, 2) { Some(v)=>v, None=>return false };
        if b[idx+3] != b':' { return false; }
        let om = match parse_fixed(s, idx+4, 2) { Some(v)=>v, None=>return false };
        // offset hour: spec allows up to 23? original rejects +24:00. RFC3339 time-numoffset hour 00-23
        return oh <= 23 && om <= 59;
    }
    false
