        let inside = &domain[1..domain.len()-1];
        return check_ipv4(inside) || inside.parse::<std::net::Ipv6Addr>().is_ok() || inside.to_lowercase().starts_with("ipv6:");
    }
    // domain labels alnum/hyphen, unicode letters allowed (idn-email & original email lenient)
    for label in domain.split('.') {
        if label.is_empty() { return false; }
        if label.starts_with('-') || label.ends_with('-') { return false; }
        if !label.chars().all(|c| c.is_alphanumeric() || c == '-') { return false; }
    }
    true
