fn check_hostname(s: &str, idn: bool) -> bool {
    if s.is_empty() || s.len() > 253 { return false; }
    if s.ends_with('.') { return false; }
    for label in s.split('.') {
        if label.is_empty() || label.len() > 63 { return false; }
        if label.starts_with('-') || label.ends_with('-') { return false; }
        let ok = if idn {
            label.chars().all(|c| c.is_alphanumeric() || c == '-')
            // IDNA rules in original are more permissive (snowman accepted). Use unicode alphanumeric + some symbols? snowman U+2603 is not alphanumeric (So). Original accepted.
            || label.chars().all(|c| !c.is_control() && c != ' ' && c != '-')
        } else {
            label.bytes().all(|c| c.is_ascii_alphanumeric() || c == b'-')
        };
        if !ok { return false; }
        if idn {
            // reject ascii labels that are invalid hostname chars
            if label.bytes().any(|c| matches!(c, b'_' | b' ')) { return false; }
        }
    }
    true
}

fn check_ipv4(s: &str) -> bool {
    let parts: Vec<&str> = s.split('.').collect();
    if parts.len() != 4 { return false; }
    for p in parts {
        if p.is_empty() || p.len() > 3 { return false; }
        if !p.bytes().all(|c| c.is_ascii_digit()) { return false; }
        if p.len() > 1 && p.starts_with('0') { return false; }
        match p.parse::<u32>() { Ok(v) if v <= 255 => {}, _ => return false }
    }
    true
}

fn check_uri(s: &str, absolute: bool, iri: bool) -> bool {
    if !iri {
        if crate::uri::validate_uri_reference(s).is_err() { return false; }
    } else {
        // IRI: allow non-ascii except controls/space and disallowed ascii
        if s.chars().any(|c| c.is_control() || c == ' ' || matches!(c, '"'|'<'|'>'|'\\'|'^'|'`'|'{'|'}'|'|')) { return false; }
