fn check_uri_template(s: &str) -> bool {
    // Validate balanced {} expressions with valid varspecs; literal chars must be valid (no space/control/# disallowed?)
    let mut chars = s.char_indices().peekable();
    let mut in_expr = false;
    let mut expr = String::new();
    while let Some((_, c)) = chars.next() {
        if in_expr {
            if c == '}' {
                if expr.is_empty() { return false; }
                if !valid_template_expr(&expr) { return false; }
                expr.clear(); in_expr = false;
            } else if c == '{' { return false; } else { expr.push(c); }
        } else {
            if c == '{' { in_expr = true; }
            else if c == '}' { return false; }
            else if c.is_control() || c == ' ' { return false; }
        }
    }
    !in_expr
