    }
    if s.is_empty() { return false; }
    for var in s.split(',') {
        let v = var.strip_suffix('*').unwrap_or(var);
        let v = match v.split_once(':') {
            Some((name, digits)) => { if digits.is_empty() || !digits.bytes().all(|c| c.is_ascii_digit()) { return false; } name }
            None => v,
        };
        if v.is_empty() { return false; }
        // varname: varchar *( ["."] varchar ) ; varchar = ALPHA / DIGIT / "_" / pct
        let b = v.as_bytes(); let mut i=0;
        while i < b.len() {
            let c=b[i];
            if c==b'%' { if !(i+2<b.len() && b[i+1].is_ascii_hexdigit() && b[i+2].is_ascii_hexdigit()) { return false; } i+=3; continue; }
            if !(c.is_ascii_alphanumeric() || c==b'_' || c==b'.') { return false; }
            i+=1;
        }
        if v.starts_with('.') || v.ends_with('.') || v.contains("..") { return false; }
    }
    true
}

