    let b = s.as_bytes();
    if b.len() != 36 { return false; }
    for (i,&c) in b.iter().enumerate() {
        if matches!(i, 8|13|18|23) { if c != b'-' { return false; } }
        else if !c.is_ascii_hexdigit() { return false; }
    }
    true
}

