    if local.bytes().any(|c| c.is_ascii_control() || matches!(c, b' ' | b'"' | b'(' | b')' | b',' | b':' | b';' | b'<' | b'>' | b'[' | b']' | b'\\')) { return false; }
    if domain.starts_with('[') && domain.ends_with(']') {
        let inside = &domain[1..domain.len()-1];
        return check_ipv4(inside) || inside.parse::<std::net::Ipv6Addr>().is_ok() || inside.to_lowercase().starts_with("ipv6:");
    }
    // domain labels alnum/hyphen, unicode letters allowed (idn-email & original email lenient)
    for label in domain.split('.') {
        if label.is_empty() { return false; }
        if label.starts_with('-') || label.ends_with('-') { return false; }
        if !label.chars().all(|c| c.is_alphanumeric() || c == '-') { return false; }
    }
    true
}

fn check_hostname(s: &str, idn: bool) -> bool {
    if s.is_empty() || s.len() > 253 { return false; }
    if s.ends_with('.') { return false; }
    for label in s.split('.') {
        if label.is_empty() || label.len() > 63 { return false; }
        if label.starts_with('-') || label.ends_with('-') { return false; }
        let ok = if idn {
            label.chars().all(|c| c.is_alphanumeric() || c == '-')
            // IDNA rules in original are more permissive (snowman accepted). Use unicode alphanumeric + some symbols? snowman U+2603 is not alphanumeric (So). Original accepted.
            || label.chars().all(|c| !c.is_control() && c != ' ' && c != '-')
        } else {
            label.bytes().all(|c| c.is_ascii_alphanumeric() || c == b'-')
        };
        if !ok { return false; }
        if idn {
            // reject ascii labels that are invalid hostname chars
            if label.bytes().any(|c| matches!(c, b'_' | b' ')) { return false; }
        }
    }
    true
}

fn check_ipv4(s: &str) -> bool {
    let parts: Vec<&str> = s.split('.').collect();
    if parts.len() != 4 { return false; }
    for p in parts {
        if p.is_empty() || p.len() > 3 { return false; }
        if !p.bytes().all(|c| c.is_ascii_digit()) { return false; }
        if p.len() > 1 && p.starts_with('0') { return false; }
        match p.parse::<u32>() { Ok(v) if v <= 255 => {}, _ => return false }
    }
    true
}

fn check_uri(s: &str, absolute: bool, iri: bool) -> bool {
    if !iri {
        if crate::uri::validate_uri_reference(s).is_err() { return false; }
    } else {
        // IRI: allow non-ascii except controls/space and disallowed ascii
        if s.chars().any(|c| c.is_control() || c == ' ' || matches!(c, '"'|'<'|'>'|'\\'|'^'|'`'|'{'|'}'|'|')) { return false; }
        // percent check
        let b = s.as_bytes();
        let mut i=0; while i<b.len() { if b[i]==b'%' { if !(i+2<b.len() && b[i+1].is_ascii_hexdigit() && b[i+2].is_ascii_hexdigit()) { return false; } i+=3; } else { i+=1; } }
        // brackets only authority - skip detailed
    }
    if absolute {
        let p = crate::uri::parse_uri_reference(s);
        p.scheme.is_some()
    } else { true }
}

fn check_uri_template(s: &str) -> bool {
    // Validate balanced {} expressions with valid varspecs; literal chars must be valid (no space/control/# disallowed?)
    let mut chars = s.char_indices().peekable();
    let mut in_expr = false;
    let mut expr = String::new();
    while let Some((_, c)) = chars.next() {
        if in_expr {
            if c == '}' {
                if expr.is_empty() { return false; }
                if !valid_template_expr(&expr) { return false; }
                expr.clear(); in_expr = false;
            } else if c == '{' { return false; } else { expr.push(c); }
        } else {
            if c == '{' { in_expr = true; }
            else if c == '}' { return false; }
            else if c.is_control() || c == ' ' { return false; }
        }
    }
    !in_expr
}
fn valid_template_expr(e: &str) -> bool {
    let mut s = e;
    if let Some(first) = s.chars().next() {
        if matches!(first, '+'|'#'|'.'|'/'|';'|'?'|'&') { s = &s[first.len_utf8()..]; }
    }
    if s.is_empty() { return false; }
    for var in s.split(',') {
        let v = var.strip_suffix('*').unwrap_or(var);
        let v = match v.split_once(':') {
            Some((name, digits)) => { if digits.is_empty() || !digits.bytes().all(|c| c.is_ascii_digit()) { return false; } name }
            None => v,
        };
        if v.is_empty() { return false; }
        // varname: varchar *( ["."] varchar ) ; varchar = ALPHA / DIGIT / "_" / pct
        let b = v.as_bytes(); let mut i=0;
        while i < b.len() {
            let c=b[i];
            if c==b'%' { if !(i+2<b.len() && b[i+1].is_ascii_hexdigit() && b[i+2].is_ascii_hexdigit()) { return false; } i+=3; continue; }
            if !(c.is_ascii_alphanumeric() || c==b'_' || c==b'.') { return false; }
            i+=1;
        }
        if v.starts_with('.') || v.ends_with('.') || v.contains("..") { return false; }
    }
    true
}

fn check_uuid(s: &str) -> bool {
    let b = s.as_bytes();
    if b.len() != 36 { return false; }
    for (i,&c) in b.iter().enumerate() {
        if matches!(i, 8|13|18|23) { if c != b'-' { return false; } }
        else if !c.is_ascii_hexdigit() { return false; }
    }
    true
}

fn check_json_pointer(s: &str) -> bool {
    if s.is_empty() { return true; }
    if !s.starts_with('/') { return false; }
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '~' {
            match chars.next() { Some('0')|Some('1') => {}, _ => return false }
        }
    }
    true
}
fn check_relative_json_pointer(s: &str) -> bool {
    // (0 or [1-9][0-9]*) ( "#" | json-pointer )
    let mut idx = 0usize;
    let b = s.as_bytes();
    if b.is_empty() || !b[0].is_ascii_digit() { return false; }
    if b[0] == b'0' { idx = 1; } else { while idx < b.len() && b[idx].is_ascii_digit() { idx += 1; } }
    if idx == b.len() { return false; } // relative pointer can be just "0"? Original accepted "0"
    // recompute: if entire is digits only -> true per original
    true && rel_rest_ok(s, idx)
}
fn rel_rest_ok(s: &str, idx: usize) -> bool {
    if idx >= s.len() { return true; }
    let rest = &s[idx..];
    if rest == "#" { return true; }
    check_json_pointer(rest)
}
RS"}

{"command":"cat > src/regexconv.rs <<'RS'
pub struct CompiledRegex {
    pub regex: fancy_regex::Regex,
    pub display: String,
}

const S_CHARS: &str = " \t\n\r\u{b}\u{c}\u{a0}\u{feff}\u{2003}\u{2029}";

pub fn convert_pattern(pat: &str) -> String {
    let mut out = String::new();
    let mut chars = pat.chars().peekable();
    while let Some(c) = chars.next() {
        if c != '\\' {
            out.push(c);
            continue;
        }
        match chars.next() {
            None => { out.push('\\'); }
            Some('\\') => {
                out.push_str("\\\\");
            }
            Some('d') => out.push_str("[0-9]"),
            Some('D') => out.push_str("[^0-9]"),
            Some('w') => out.push_str("[A-Za-z0-9_]"),
            Some('W') => out.push_str("[^A-Za-z0-9_]"),
            Some('s') => { out.push('['); out.push_str(S_CHARS); out.push(']'); }
            Some('S') => { out.push_str("[^"); out.push_str(S_CHARS); out.push(']'); }
            Some('c') => {
                match chars.next() {
                    Some(x) if x.is_ascii_alphabetic() => {
                        let ctrl = ((x as u32) & 0x1f) as u8;
                        out.push(ctrl as char);
                    }
                    Some(x) => { out.push('\\'); out.push('c'); out.push(x); }
                    None => { out.push('\\'); out.push('c'); }
                }
            }
            Some(other) => { out.push('\\'); out.push(other); }
        }
    }
    out
}

pub fn compile_regex(pat: &str) -> Result<CompiledRegex, ()> {
    let display = convert_pattern(pat);
    match fancy_regex::Regex::new(&display) {
        Ok(r) => Ok(CompiledRegex { regex: r, display }),
        Err(_) => Err(()),
    }
}

impl CompiledRegex {
    pub fn is_match(&self, text: &str) -> bool {
        self.regex.is_match(text).unwrap_or(false)
    }
}
RS"}

