use crate::formats;
use crate::meta::{self, Draft};
use crate::num;
use crate::regexconv::{compile_regex, CompiledRegex};
use crate::uri;
use serde_json::{Map, Value};
use std::cell::RefCell;
use std::collections::{BTreeMap, HashMap, HashSet};
use std::path::PathBuf;
use std::rc::Rc;

#[derive(Clone)]
pub struct HttpConfig {
    pub timeout: Option<f64>,
    pub connect_timeout: Option<f64>,
    pub insecure: bool,
    pub cacert: Option<PathBuf>,
}
impl Default for HttpConfig {
    fn default() -> Self { HttpConfig { timeout: None, connect_timeout: None, insecure: false, cacert: None } }
}

#[derive(Clone)]
pub struct BuildOptions {
    pub forced_draft: Option<Draft>,
    pub assert_format: bool,
    pub http: HttpConfig,
}
impl Default for BuildOptions {
    fn default() -> Self { BuildOptions { forced_draft: None, assert_format: false, http: HttpConfig::default() } }
}

#[derive(Debug, Clone)]
pub struct BuildError(pub String);
impl std::fmt::Display for BuildError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result { write!(f, "{}", self.0) }
}
impl std::error::Error for BuildError {}
pub type BResult<T> = Result<T, BuildError>;
fn berr(s: String) -> BuildError { BuildError(s) }

// ---------- Retriever ----------
#[derive(Clone)]
pub struct Retriever {
    pub http: HttpConfig,
}
impl Retriever {
    pub fn new(http: HttpConfig) -> Self { Retriever { http } }
    pub fn default_retriever() -> Self { Retriever { http: HttpConfig::default() } }
    // Ensure cacert file can be read (stage where original reads it). Returns full "Error:"-less message? Caller prints Error: ...
    pub fn ensure_cacert_readable(&self) -> Result<(), String> {
        if let Some(p) = &self.http.cacert {
            match std::fs::read(p) {
                Ok(_) => Ok(()),
                Err(e) => Err(format!("Failed to read certificate file '{}': {}", p.to_string_lossy(), e)),
            }
        } else { Ok(()) }
    }
    pub fn retrieve(&self, uri_no_frag: &str) -> Result<Value, String> {
        if let Some(v) = meta::embedded_resource(uri_no_frag) {
            return Ok(v);
        }
        let scheme = uri::scheme_of(uri_no_frag);
        match scheme.as_deref() {
            None => Err("Unknown scheme json-schema".to_string()),
            Some(s) if s.eq_ignore_ascii_case("file") => {
                let path = uri::file_uri_to_path(uri_no_frag).unwrap_or_default();
                let bytes = std::fs::read(&path).map_err(|e| e.to_string())?;
                serde_json::from_slice::<Value>(&bytes).map_err(|e| e.to_string())
            }
            Some(s) if s.eq_ignore_ascii_case("http") || s.eq_ignore_ascii_case("https") => {
                crate::httpfetch::fetch_json(uri_no_frag, &self.http)
            }
            Some(s) => Err(format!("Unknown scheme {}", s)),
        }
    }
    pub fn retrieve_resource(&self, uri_no_frag: &str) -> BResult<Value> {
        self.retrieve(uri_no_frag).map_err(|inner| berr(format!("Resource '{}' is not present in a registry and retrieving it failed: {}", uri_no_frag, inner)))
    }
}

// ---------- Dialect ----------
#[derive(Clone, Copy, PartialEq, Eq, Debug, Hash)]
pub enum Vocab {
    Core, Applicator, Validation, MetaData, FormatAnnotation, FormatAssertion, Content, Unevaluated,
}
#[derive(Clone, Debug)]
pub enum VocabMode {
    Standard,              // all keywords for draft
    Empty,                 // no vocab keywords (but $ref still works)
    Set(HashSet<Vocab>),   // 2019/2020 custom vocab
    AllButContains,        // custom meta retrieved, no effective $vocabulary
}

#[derive(Clone, Debug)]
pub struct Dialect {
    pub draft: Draft,
    pub vocab: VocabMode,
}
impl Dialect {
    pub fn standard(d: Draft) -> Self { Dialect { draft: d, vocab: VocabMode::Standard } }
    pub fn reset_standard(&self) -> Dialect { Dialect::standard(self.draft) }
}

// keyword vocab for 2019/2020
pub fn keyword_vocab(kw: &str, draft: Draft) -> Option<Vocab> {
    Some(match kw {
        "$id"|"$schema"|"$ref"|"$anchor"|"$dynamicRef"|"$dynamicAnchor"|"$vocabulary"|"$comment"|"$defs"|"$recursiveRef"|"$recursiveAnchor" => Vocab::Core,
        "allOf"|"anyOf"|"oneOf"|"not"|"if"|"then"|"else"|"properties"|"patternProperties"|"additionalProperties"|"propertyNames"|"dependentSchemas"|"items"|"prefixItems"|"contains"|"additionalItems" => Vocab::Applicator,
        "unevaluatedItems"|"unevaluatedProperties" => if draft == Draft::D2020 { Vocab::Unevaluated } else { Vocab::Applicator },
        "type"|"const"|"enum"|"multipleOf"|"maximum"|"exclusiveMaximum"|"minimum"|"exclusiveMinimum"|"maxLength"|"minLength"|"pattern"|"maxItems"|"minItems"|"uniqueItems"|"maxContains"|"minContains"|"maxProperties"|"minProperties"|"required"|"dependentRequired" => Vocab::Validation,
        "title"|"description"|"default"|"deprecated"|"readOnly"|"writeOnly"|"examples" => Vocab::MetaData,
        "format" => Vocab::FormatAnnotation,
        "contentEncoding"|"contentMediaType"|"contentSchema" => Vocab::Content,
        _ => return None,
    })
}

pub fn keyword_in_draft(kw: &str, draft: Draft) -> bool {
    // Whether keyword is recognized at all in the draft (for <=7 and as a base for newer)
    match draft {
        Draft::D4 => matches!(kw,
            "id"|"$schema"|"$ref"|"title"|"description"|"default"|"multipleOf"|"maximum"|"exclusiveMaximum"|"minimum"|"exclusiveMinimum"|"maxLength"|"minLength"|"pattern"|"additionalItems"|"items"|"maxItems"|"minItems"|"uniqueItems"|"maxProperties"|"minProperties"|"required"|"additionalProperties"|"definitions"|"properties"|"patternProperties"|"dependencies"|"enum"|"type"|"allOf"|"anyOf"|"oneOf"|"not"|"format"),
        Draft::D6 => matches!(kw,
            "$id"|"$schema"|"$ref"|"title"|"description"|"default"|"examples"|"multipleOf"|"maximum"|"exclusiveMaximum"|"minimum"|"exclusiveMinimum"|"maxLength"|"minLength"|"pattern"|"additionalItems"|"items"|"maxItems"|"minItems"|"uniqueItems"|"contains"|"maxProperties"|"minProperties"|"required"|"additionalProperties"|"definitions"|"properties"|"patternProperties"|"dependencies"|"propertyNames"|"const"|"enum"|"type"|"allOf"|"anyOf"|"oneOf"|"not"|"format"|"contentEncoding"|"contentMediaType"),
        Draft::D7 => matches!(kw,
            "$id"|"$schema"|"$ref"|"$comment"|"title"|"description"|"default"|"readOnly"|"writeOnly"|"examples"|"multipleOf"|"maximum"|"exclusiveMaximum"|"minimum"|"exclusiveMinimum"|"maxLength"|"minLength"|"pattern"|"additionalItems"|"items"|"maxItems"|"minItems"|"uniqueItems"|"contains"|"maxProperties"|"minProperties"|"required"|"additionalProperties"|"definitions"|"properties"|"patternProperties"|"dependencies"|"propertyNames"|"const"|"enum"|"type"|"allOf"|"anyOf"|"oneOf"|"not"|"format"|"contentEncoding"|"contentMediaType"|"if"|"then"|"else"),
        Draft::D2019 => matches!(kw,
            "$id"|"$schema"|"$anchor"|"$ref"|"$recursiveRef"|"$recursiveAnchor"|"$vocabulary"|"$comment"|"$defs"|"title"|"description"|"default"|"deprecated"|"readOnly"|"writeOnly"|"examples"|"multipleOf"|"maximum"|"exclusiveMaximum"|"minimum"|"exclusiveMinimum"|"maxLength"|"minLength"|"pattern"|"additionalItems"|"items"|"maxItems"|"minItems"|"uniqueItems"|"contains"|"maxContains"|"minContains"|"maxProperties"|"minProperties"|"required"|"additionalProperties"|"definitions"|"properties"|"patternProperties"|"dependencies"|"dependentRequired"|"dependentSchemas"|"propertyNames"|"const"|"enum"|"type"|"allOf"|"anyOf"|"oneOf"|"not"|"format"|"contentEncoding"|"contentMediaType"|"contentSchema"|"if"|"then"|"else"|"unevaluatedItems"|"unevaluatedProperties"),
        Draft::D2020 => matches!(kw,
            "$id"|"$schema"|"$ref"|"$anchor"|"$dynamicRef"|"$dynamicAnchor"|"$vocabulary"|"$comment"|"$defs"|"title"|"description"|"default"|"deprecated"|"readOnly"|"writeOnly"|"examples"|"multipleOf"|"maximum"|"exclusiveMaximum"|"minimum"|"exclusiveMinimum"|"maxLength"|"minLength"|"pattern"|"items"|"prefixItems"|"maxItems"|"minItems"|"uniqueItems"|"contains"|"maxContains"|"minContains"|"maxProperties"|"minProperties"|"required"|"additionalProperties"|"definitions"|"properties"|"patternProperties"|"dependencies"|"dependentRequired"|"dependentSchemas"|"propertyNames"|"const"|"enum"|"type"|"allOf"|"anyOf"|"oneOf"|"not"|"format"|"contentEncoding"|"contentMediaType"|"contentSchema"|"if"|"then"|"else"|"unevaluatedItems"|"unevaluatedProperties"),
    }
}

impl Dialect {
    pub fn recognizes(&self, kw: &str) -> bool {
        if kw == "$ref" { return true; }
        if !keyword_in_draft(kw, self.draft) {
            // special: legacy "dependencies" recognized in all (already included), "additionalItems" in 2020 handled if items array (compiler legacy)
            return false;
        }
        match &self.vocab {
            VocabMode::Standard => true,
            VocabMode::Empty => false,
            VocabMode::AllButContains => kw != "contains",
            VocabMode::Set(set) => {
                if kw == "contains" { return false; } // observed: never under custom vocab set either
                match keyword_vocab(kw, self.draft) {
                    Some(v) => set.contains(&v) || (v == Vocab::FormatAnnotation && set.contains(&Vocab::FormatAssertion)) || v == Vocab::Core,
                    None => false,
                }
            }
        }
    }
}

// ---------- Documents / Registry ----------
pub struct Document {
    pub uri: String,
    pub value: Rc<Value>,
    pub anchors: HashMap<(String, String), Vec<String>>,
    pub dyn_anchors: HashMap<(String, String), Vec<String>>,
    pub resources: HashMap<String, Vec<String>>,
}

pub struct Registry {
    pub docs: HashMap<String, Rc<Document>>,
    // resource uri (no frag) -> (doc uri, pointer tokens of resource root in doc)
    pub by_resource: HashMap<String, (String, Vec<String>)>,
    pub retriever: Retriever,
    pub options: BuildOptions,
}

pub fn id_keyword(draft: Draft) -> &'static str { if draft == Draft::D4 { "id" } else { "$id" } }

impl Registry {
    pub fn new(options: BuildOptions, retriever: Retriever) -> Self {
        Registry { docs: HashMap::new(), by_resource: HashMap::new(), retriever, options }
    }

    pub fn add_document(&mut self, uri_no_frag: &str, value: Value) -> BResult<Rc<Document>> {
        if let Some(d) = self.docs.get(uri_no_frag) { return Ok(d.clone()); }
        let mut doc = Document {
            uri: uri_no_frag.to_string(),
            value: Rc::new(value),
            anchors: HashMap::new(),
            dyn_anchors: HashMap::new(),
            resources: HashMap::new(),
        };
        doc.resources.insert(uri_no_frag.to_string(), Vec::new());
        // Index. Draft for indexing root resource: determine without retrieval recursion for custom metas
        // ( Dialect determination that may retrieve is done by caller for root schema doc; nested resources
        //   here use standard detection only, defaulting to options/default. )
        let root_dialect = self.index_dialect_for(&doc.value);
        let value_rc = doc.value.clone();
        self.index_node(&mut doc, &value_rc, &[], uri_no_frag, &root_dialect, true)?;
        let rc = Rc::new(doc);
        // register resources (clone list first)
        let resources: Vec<(String, Vec<String>)> = rc.resources.iter().map(|(k,v)| (k.clone(), v.clone())).collect();
        for (ruri, ptr) in resources {
            self.by_resource.insert(ruri, (uri_no_frag.to_string(), ptr));
        }
        self.docs.insert(uri_no_frag.to_string(), rc.clone());
        Ok(rc)
    }

    fn index_dialect_for(&self, v: &Value) -> Dialect {
        // Used during indexing only (id keyword, traversal). No retrieval.
        if let Some(f) = self.options.forced_draft { return Dialect::standard(f); }
        if let Some(obj) = v.as_object() {
            if let Some(u) = obj.get("$schema").and_then(|x| x.as_str()) {
                if let Some(d) = meta::standard_draft_for_meta_uri(u) { return Dialect::standard(d); }
                return Dialect::standard(Draft::D2020);
            }
        }
        Dialect::standard(Draft::D2020)
    }

    fn index_node(&self, doc: &mut Document, v: &Value, ptr: &[String], base_uri: &str, dialect: &Dialect, is_resource_root: bool) -> BResult<()> {
        let obj = match v.as_object() { Some(o) => o, None => return Ok(()) };
        let mut cur_base = base_uri.to_string();
        let mut cur_dialect = dialect.clone();
        // $schema validation at resource roots (URI syntax)
        if is_resource_root {
            if let Some(s) = obj.get("$schema").and_then(|x| x.as_str()) {
                uri::validate_uri_reference(s).map_err(|e| berr(uri::invalid_uri_error(s, &e.0)))?;
            }
        }
        // id handling
        let idkw = id_keyword(cur_dialect.draft);
        if let Some(idval) = obj.get(idkw) {
            if let Some(ids) = idval.as_str() {
                uri::validate_uri_reference(ids).map_err(|e| berr(uri::invalid_uri_error(ids, &e.0)))?;
                let resolved = uri::resolve(&format!("{}#", strip_frag(base_uri)), ids);
                let (res_no_frag, frag) = uri::split_fragment(&resolved);
                let res_no_frag = res_no_frag.to_string();
                // old drafts: non-empty fragment is a plain-name anchor
                if let Some(f) = frag {
                    if !f.is_empty() && !f.starts_with('/') {
                        doc.anchors.insert((res_no_frag.clone(), f.to_string()), ptr.to_vec());
                    }
                }
                if !(ptr.is_empty() && res_no_frag == strip_frag(base_uri)) {
                    doc.resources.insert(res_no_frag.clone(), ptr.to_vec());
                }
                cur_base = res_no_frag;
                // nested resource may change dialect via $schema
                if let Some(u) = obj.get("$schema").and_then(|x| x.as_str()) {
                    if self.options.forced_draft.is_none() {
                        if let Some(d) = meta::standard_draft_for_meta_uri(u) { cur_dialect = Dialect::standard(d); }
                    }
                }
            }
        }
        // anchors
        if matches!(cur_dialect.draft, Draft::D2019 | Draft::D2020) {
            if let Some(a) = obj.get("$anchor").and_then(|x| x.as_str()) {
                doc.anchors.insert((cur_base.clone(), a.to_string()), ptr.to_vec());
            }
        }
        if cur_dialect.draft == Draft::D2020 {
            if let Some(a) = obj.get("$dynamicAnchor").and_then(|x| x.as_str()) {
                doc.dyn_anchors.insert((cur_base.clone(), a.to_string()), ptr.to_vec());
                doc.anchors.entry((cur_base.clone(), a.to_string())).or_insert_with(|| ptr.to_vec());
            }
        }
        if cur_dialect.draft == Draft::D2019 {
            if obj.get("$recursiveAnchor").and_then(|x| x.as_bool()) == Some(true) {
                doc.dyn_anchors.insert((cur_base.clone(), "".to_string()), ptr.to_vec());
            }
        }
        // validate ref URI syntax at schema nodes (even if unused)
        for rk in ["$ref", "$dynamicRef", "$recursiveRef"] {
            if let Some(rv) = obj.get(rk).and_then(|x| x.as_str()) {
                // Only if keyword recognized-ish for this draft? $ref always; dynamic/recursive only their drafts.
                let relevant = rk == "$ref" || (rk == "$dynamicRef" && cur_dialect.draft == Draft::D2020) || (rk == "$recursiveRef" && cur_dialect.draft == Draft::D2019);
                if relevant {
                    uri::validate_uri_reference(rv).map_err(|e| berr(uri::invalid_uri_error(rv, &e.0)))?;
                }
            }
        }
        // Traverse subschema locations (union over drafts, restricted sensibly)
        for (k, child) in obj.iter() {
            let mut newptr = ptr.to_vec(); newptr.push(k.clone());
            match k.as_str() {
                "properties"|"patternProperties"|"definitions"|"$defs"|"dependentSchemas" => {
                    if let Some(m) = child.as_object() {
                        for (pk, pv) in m {
                            let mut p2 = newptr.clone(); p2.push(pk.clone());
                            self.index_node(doc, pv, &p2, &cur_base, &cur_dialect, false)?;
                        }
                    }
                }
                "dependencies" => {
                    if let Some(m) = child.as_object() {
                        for (pk, pv) in m {
                            if pv.is_object() || pv.is_boolean() {
                                let mut p2 = newptr.clone(); p2.push(pk.clone());
                                self.index_node(doc, pv, &p2, &cur_base, &cur_dialect, false)?;
                            }
                        }
                    }
                }
                "items"|"additionalItems"|"contains"|"additionalProperties"|"propertyNames"|"not"|"if"|"then"|"else"|"contentSchema"|"unevaluatedItems"|"unevaluatedProperties" => {
                    if child.is_array() {
                        for (idx, it) in child.as_array().unwrap().iter().enumerate() {
                            let mut p2 = newptr.clone(); p2.push(idx.to_string());
                            self.index_node(doc, it, &p2, &cur_base, &cur_dialect, false)?;
                        }
                    } else {
                        self.index_node(doc, child, &newptr, &cur_base, &cur_dialect, false)?;
                    }
                }
                "allOf"|"anyOf"|"oneOf"|"prefixItems" => {
                    if let Some(arr) = child.as_array() {
                        for (idx, it) in arr.iter().enumerate() {
                            let mut p2 = newptr.clone(); p2.push(idx.to_string());
                            self.index_node(doc, it, &p2, &cur_base, &cur_dialect, false)?;
                        }
                    }
                }
                _ => {}
            }
        }
        Ok(())
    }

    pub fn get_or_retrieve(&mut self, uri_no_frag: &str) -> BResult<(Rc<Document>, Vec<String>)> {
        if let Some((docuri, ptr)) = self.by_resource.get(uri_no_frag).cloned() {
            let d = self.docs.get(&docuri).unwrap().clone();
            return Ok((d, ptr));
        }
        if let Some(d) = self.docs.get(uri_no_frag) { return Ok((d.clone(), Vec::new())); }
        let val = self.retriever.retrieve_resource(uri_no_frag)?;
        let doc = self.add_document(uri_no_frag, val)?;
        if let Some((docuri, ptr)) = self.by_resource.get(uri_no_frag).cloned() {
            let d = self.docs.get(&docuri).unwrap().clone();
            return Ok((d, ptr));
        }
        Ok((doc, Vec::new()))
    }
}

pub fn strip_frag(u: &str) -> &str { uri::split_fragment(u).0 }

pub fn value_at<'a>(v: &'a Value, ptr: &[String]) -> Option<&'a Value> {
    let mut cur = v;
    for t in ptr {
        cur = match cur {
            Value::Object(m) => m.get(t)?,
            Value::Array(a) => a.get(t.parse::<usize>().ok()?)?,
            _ => return None,
        };
    }
    Some(cur)
}
RS"}

