pub fn id_keyword(draft: Draft) -> &'static str { if draft == Draft::D4 { "id" } else { "$id" } }

impl Registry {
    pub fn new(options: BuildOptions, retriever: Retriever) -> Self {
        Registry { docs: HashMap::new(), by_resource: HashMap::new(), retriever, options }
    }

    pub fn add_document(&mut self, uri_no_frag: &str, value: Value) -> BResult<Rc<Document>> {
        if let Some(d) = self.docs.get(uri_no_frag) { return Ok(d.clone()); }
        let mut doc = Document {
            uri: uri_no_frag.to_string(),
            value: Rc::new(value),
            anchors: HashMap::new(),
            dyn_anchors: HashMap::new(),
            resources: HashMap::new(),
        };
        doc.resources.insert(uri_no_frag.to_string(), Vec::new());
        // Index. Draft for indexing root resource: determine without retrieval recursion for custom metas
        // ( Dialect determination that may retrieve is done by caller for root schema doc; nested resources
        //   here use standard detection only, defaulting to options/default. )
        let root_dialect = self.index_dialect_for(&doc.value);
        let value_rc = doc.value.clone();
        self.index_node(&mut doc, &value_rc, &[], uri_no_frag, &root_dialect, true)?;
        let rc = Rc::new(doc);
        // register resources (clone list first)
        let resources: Vec<(String, Vec<String>)> = rc.resources.iter().map(|(k,v)| (k.clone(), v.clone())).collect();
        for (ruri, ptr) in resources {
            self.by_resource.insert(ruri, (uri_no_frag.to_string(), ptr));
        }
        self.docs.insert(uri_no_frag.to_string(), rc.clone());
        Ok(rc)
    }

    fn index_dialect_for(&self, v: &Value) -> Dialect {
        // Used during indexing only (id keyword, traversal). No retrieval.
        if let Some(f) = self.options.forced_draft { return Dialect::standard(f); }
        if let Some(obj) = v.as_object() {
            if let Some(u) = obj.get("$schema").and_then(|x| x.as_str()) {
                if let Some(d) = meta::standard_draft_for_meta_uri(u) { return Dialect::standard(d); }
                return Dialect::standard(Draft::D2020);
            }
        }
        Dialect::standard(Draft::D2020)
    }

    fn index_node(&self, doc: &mut Document, v: &Value, ptr: &[String], base_uri: &str, dialect: &Dialect, is_resource_root: bool) -> BResult<()> {
        let obj = match v.as_object() { Some(o) => o, None => return Ok(()) };
        let mut cur_base = base_uri.to_string();
        let mut cur_dialect = dialect.clone();
        // $schema validation at resource roots (URI syntax)
        if is_resource_root {
            if let Some(s) = obj.get("$schema").and_then(|x| x.as_str()) {
                uri::validate_uri_reference(s).map_err(|e| berr(uri::invalid_uri_error(s, &e.0)))?;
            }
        }
        // id handling
        let idkw = id_keyword(cur_dialect.draft);
        if let Some(idval) = obj.get(idkw) {
            if let Some(ids) = idval.as_str() {
                uri::validate_uri_reference(ids).map_err(|e| berr(uri::invalid_uri_error(ids, &e.0)))?;
                let resolved = uri::resolve(&format!("{}#", strip_frag(base_uri)), ids);
                let (res_no_frag, frag) = uri::split_fragment(&resolved);
                let res_no_frag = res_no_frag.to_string();
                // old drafts: non-empty fragment is a plain-name anchor
                if let Some(f) = frag {
                    if !f.is_empty() && !f.starts_with('/') {
                        doc.anchors.insert((res_no_frag.clone(), f.to_string()), ptr.to_vec());
                    }
                }
                if !(ptr.is_empty() && res_no_frag == strip_frag(base_uri)) {
                    doc.resources.insert(res_no_frag.clone(), ptr.to_vec());
                }
                cur_base = res_no_frag;
                // nested resource may change dialect via $schema
                if let Some(u) = obj.get("$schema").and_then(|x| x.as_str()) {
                    if self.options.forced_draft.is_none() {
                        if let Some(d) = meta::standard_draft_for_meta_uri(u) { cur_dialect = Dialect::standard(d); }
                    }
                }
            }
        }
        // anchors
        if matches!(cur_dialect.draft, Draft::D2019 | Draft::D2020) {
            if let Some(a) = obj.get("$anchor").and_then(|x| x.as_str()) {
                doc.anchors.insert((cur_base.clone(), a.to_string()), ptr.to_vec());
            }
        }
        if cur_dialect.draft == Draft::D2020 {
            if let Some(a) = obj.get("$dynamicAnchor").and_then(|x| x.as_str()) {
                doc.dyn_anchors.insert((cur_base.clone(), a.to_string()), ptr.to_vec());
                doc.anchors.entry((cur_base.clone(), a.to_string())).or_insert_with(|| ptr.to_vec());
            }
        }
        if cur_dialect.draft == Draft::D2019 {
            if obj.get("$recursiveAnchor").and_then(|x| x.as_bool()) == Some(true) {
                doc.dyn_anchors.insert((cur_base.clone(), "".to_string()), ptr.to_vec());
            }
        }
        // validate ref URI syntax at schema nodes (even if unused)
        for rk in ["$ref", "$dynamicRef", "$recursiveRef"] {
            if let Some(rv) = obj.get(rk).and_then(|x| x.as_str()) {
                // Only if keyword recognized-ish for this draft? $ref always; dynamic/recursive only their drafts.
                let relevant = rk == "$ref" || (rk == "$dynamicRef" && cur_dialect.draft == Draft::D2020) || (rk == "$recursiveRef" && cur_dialect.draft == Draft::D2019);
                if relevant {
                    uri::validate_uri_reference(rv).map_err(|e| berr(uri::invalid_uri_error(rv, &e.0)))?;
                }
            }
        }
        // Traverse subschema locations (union over drafts, restricted sensibly)
        for (k, child) in obj.iter() {
            let mut newptr = ptr.to_vec(); newptr.push(k.clone());
            match k.as_str() {
                "properties"|"patternProperties"|"definitions"|"$defs"|"dependentSchemas" => {
                    if let Some(m) = child.as_object() {
                        for (pk, pv) in m {
                            let mut p2 = newptr.clone(); p2.push(pk.clone());
                            self.index_node(doc, pv, &p2, &cur_base, &cur_dialect, false)?;
                        }
                    }
                }
                "dependencies" => {
                    if let Some(m) = child.as_object() {
                        for (pk, pv) in m {
                            if pv.is_object() || pv.is_boolean() {
                                let mut p2 = newptr.clone(); p2.push(pk.clone());
                                self.index_node(doc, pv, &p2, &cur_base, &cur_dialect, false)?;
                            }
                        }
                    }
                }
                "items"|"additionalItems"|"contains"|"additionalProperties"|"propertyNames"|"not"|"if"|"then"|"else"|"contentSchema"|"unevaluatedItems"|"unevaluatedProperties" => {
                    if child.is_array() {
                        for (idx, it) in child.as_array().unwrap().iter().enumerate() {
                            let mut p2 = newptr.clone(); p2.push(idx.to_string());
                            self.index_node(doc, it, &p2, &cur_base, &cur_dialect, false)?;
                        }
                    } else {
                        self.index_node(doc, child, &newptr, &cur_base, &cur_dialect, false)?;
                    }
                }
                "allOf"|"anyOf"|"oneOf"|"prefixItems" => {
                    if let Some(arr) = child.as_array() {
                        for (idx, it) in arr.iter().enumerate() {
                            let mut p2 = newptr.clone(); p2.push(idx.to_string());
                            self.index_node(doc, it, &p2, &cur_base, &cur_dialect, false)?;
                        }
                    }
                }
                _ => {}
            }
        }
        Ok(())
    }

    pub fn get_or_retrieve(&mut self, uri_no_frag: &str) -> BResult<(Rc<Document>, Vec<String>)> {
        if let Some((docuri, ptr)) = self.by_resource.get(uri_no_frag).cloned() {
            let d = self.docs.get(&docuri).unwrap().clone();
            return Ok((d, ptr));
        }
        if let Some(d) = self.docs.get(uri_no_frag) { return Ok((d.clone(), Vec::new())); }
        let val = self.retriever.retrieve_resource(uri_no_frag)?;
        let doc = self.add_document(uri_no_frag, val)?;
        if let Some((docuri, ptr)) = self.by_resource.get(uri_no_frag).cloned() {
            let d = self.docs.get(&docuri).unwrap().clone();
            return Ok((d, ptr));
        }
        Ok((doc, Vec::new()))
    }
}

pub fn strip_frag(u: &str) -> &str { uri::split_fragment(u).0 }

pub fn value_at<'a>(v: &'a Value, ptr: &[String]) -> Option<&'a Value> {
    let mut cur = v;
    for t in ptr {
        cur = match cur {
            Value::Object(m) => m.get(t)?,
            Value::Array(a) => a.get(t.parse::<usize>().ok()?)?,
            _ => return None,
        };
    }
    Some(cur)
}
