#[derive(Clone)]
pub struct HttpConfig {
    pub timeout: Option<f64>,
    pub connect_timeout: Option<f64>,
    pub insecure: bool,
    pub cacert: Option<PathBuf>,
}
impl Default for HttpConfig {
    fn default() -> Self { HttpConfig { timeout: None, connect_timeout: None, insecure: false, cacert: None } }
}

#[derive(Clone)]
pub struct BuildOptions {
    pub forced_draft: Option<Draft>,
    pub assert_format: bool,
    pub http: HttpConfig,
}
impl Default for BuildOptions {
    fn default() -> Self { BuildOptions { forced_draft: None, assert_format: false, http: HttpConfig::default() } }
}

#[derive(Debug, Clone)]
pub struct BuildError(pub String);
impl std::fmt::Display for BuildError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result { write!(f, "{}", self.0) }
}
impl std::error::Error for BuildError {}
pub type BResult<T> = Result<T, BuildError>;
fn berr(s: String) -> BuildError { BuildError(s) }

// ---------- Retriever ----------
#[derive(Clone)]
pub struct Retriever {
    pub http: HttpConfig,
}
impl Retriever {
    pub fn new(http: HttpConfig) -> Self { Retriever { http } }
    pub fn default_retriever() -> Self { Retriever { http: HttpConfig::default() } }
    // Ensure cacert file can be read (stage where original reads it). Returns full "Error:"-less message? Caller prints Error: ...
    pub fn ensure_cacert_readable(&self) -> Result<(), String> {
        if let Some(p) = &self.http.cacert {
            match std::fs::read(p) {
                Ok(_) => Ok(()),
                Err(e) => Err(format!("Failed to read certificate file '{}': {}", p.to_string_lossy(), e)),
            }
        } else { Ok(()) }
    }
    pub fn retrieve(&self, uri_no_frag: &str) -> Result<Value, String> {
        if let Some(v) = meta::embedded_resource(uri_no_frag) {
            return Ok(v);
        }
        let scheme = uri::scheme_of(uri_no_frag);
        match scheme.as_deref() {
            None => Err("Unknown scheme json-schema".to_string()),
            Some(s) if s.eq_ignore_ascii_case("file") => {
                let path = uri::file_uri_to_path(uri_no_frag).unwrap_or_default();
                let bytes = std::fs::read(&path).map_err(|e| e.to_string())?;
                serde_json::from_slice::<Value>(&bytes).map_err(|e| e.to_string())
            }
            Some(s) if s.eq_ignore_ascii_case("http") || s.eq_ignore_ascii_case("https") => {
                crate::httpfetch::fetch_json(uri_no_frag, &self.http)
            }
            Some(s) => Err(format!("Unknown scheme {}", s)),
        }
    }
    pub fn retrieve_resource(&self, uri_no_frag: &str) -> BResult<Value> {
        self.retrieve(uri_no_frag).map_err(|inner| berr(format!("Resource '{}' is not present in a registry and retrieving it failed: {}", uri_no_frag, inner)))
    }
}

// ---------- Dialect ----------
#[derive(Clone, Copy, PartialEq, Eq, Debug, Hash)]
pub enum Vocab {
    Core, Applicator, Validation, MetaData, FormatAnnotation, FormatAssertion, Content, Unevaluated,
}
#[derive(Clone, Debug)]
pub enum VocabMode {
    Standard,              // all keywords for draft
    Empty,                 // no vocab keywords (but $ref still works)
    Set(HashSet<Vocab>),   // 2019/2020 custom vocab
    AllButContains,        // custom meta retrieved, no effective $vocabulary
}

#[derive(Clone, Debug)]
pub struct Dialect {
    pub draft: Draft,
    pub vocab: VocabMode,
}
impl Dialect {
    pub fn standard(d: Draft) -> Self { Dialect { draft: d, vocab: VocabMode::Standard } }
    pub fn reset_standard(&self) -> Dialect { Dialect::standard(self.draft) }
}

// keyword vocab for 2019/2020
pub fn keyword_vocab(kw: &str, draft: Draft) -> Option<Vocab> {
    Some(match kw {
        "$id"|"$schema"|"$ref"|"$anchor"|"$dynamicRef"|"$dynamicAnchor"|"$vocabulary"|"$comment"|"$defs"|"$recursiveRef"|"$recursiveAnchor" => Vocab::Core,
        "allOf"|"anyOf"|"oneOf"|"not"|"if"|"then"|"else"|"properties"|"patternProperties"|"additionalProperties"|"propertyNames"|"dependentSchemas"|"items"|"prefixItems"|"contains"|"additionalItems" => Vocab::Applicator,
        "unevaluatedItems"|"unevaluatedProperties" => if draft == Draft::D2020 { Vocab::Unevaluated } else { Vocab::Applicator },
        "type"|"const"|"enum"|"multipleOf"|"maximum"|"exclusiveMaximum"|"minimum"|"exclusiveMinimum"|"maxLength"|"minLength"|"pattern"|"maxItems"|"minItems"|"uniqueItems"|"maxContains"|"minContains"|"maxProperties"|"minProperties"|"required"|"dependentRequired" => Vocab::Validation,
        "title"|"description"|"default"|"deprecated"|"readOnly"|"writeOnly"|"examples" => Vocab::MetaData,
        "format" => Vocab::FormatAnnotation,
        "contentEncoding"|"contentMediaType"|"contentSchema" => Vocab::Content,
        _ => return None,
    })
}

