            "id"|"$schema"|"$ref"|"title"|"description"|"default"|"multipleOf"|"maximum"|"exclusiveMaximum"|"minimum"|"exclusiveMinimum"|"maxLength"|"minLength"|"pattern"|"additionalItems"|"items"|"maxItems"|"minItems"|"uniqueItems"|"maxProperties"|"minProperties"|"required"|"additionalProperties"|"definitions"|"properties"|"patternProperties"|"dependencies"|"enum"|"type"|"allOf"|"anyOf"|"oneOf"|"not"|"format"),
        Draft::D6 => matches!(kw,
            "$id"|"$schema"|"$ref"|"title"|"description"|"default"|"examples"|"multipleOf"|"maximum"|"exclusiveMaximum"|"minimum"|"exclusiveMinimum"|"maxLength"|"minLength"|"pattern"|"additionalItems"|"items"|"maxItems"|"minItems"|"uniqueItems"|"contains"|"maxProperties"|"minProperties"|"required"|"additionalProperties"|"definitions"|"properties"|"patternProperties"|"dependencies"|"propertyNames"|"const"|"enum"|"type"|"allOf"|"anyOf"|"oneOf"|"not"|"format"|"contentEncoding"|"contentMediaType"),
        Draft::D7 => matches!(kw,
            "$id"|"$schema"|"$ref"|"$comment"|"title"|"description"|"default"|"readOnly"|"writeOnly"|"examples"|"multipleOf"|"maximum"|"exclusiveMaximum"|"minimum"|"exclusiveMinimum"|"maxLength"|"minLength"|"pattern"|"additionalItems"|"items"|"maxItems"|"minItems"|"uniqueItems"|"contains"|"maxProperties"|"minProperties"|"required"|"additionalProperties"|"definitions"|"properties"|"patternProperties"|"dependencies"|"propertyNames"|"const"|"enum"|"type"|"allOf"|"anyOf"|"oneOf"|"not"|"format"|"contentEncoding"|"contentMediaType"|"if"|"then"|"else"),
        Draft::D2019 => matches!(kw,
            "$id"|"$schema"|"$anchor"|"$ref"|"$recursiveRef"|"$recursiveAnchor"|"$vocabulary"|"$comment"|"$defs"|"title"|"description"|"default"|"deprecated"|"readOnly"|"writeOnly"|"examples"|"multipleOf"|"maximum"|"exclusiveMaximum"|"minimum"|"exclusiveMinimum"|"maxLength"|"minLength"|"pattern"|"additionalItems"|"items"|"maxItems"|"minItems"|"uniqueItems"|"contains"|"maxContains"|"minContains"|"maxProperties"|"minProperties"|"required"|"additionalProperties"|"definitions"|"properties"|"patternProperties"|"dependencies"|"dependentRequired"|"dependentSchemas"|"propertyNames"|"const"|"enum"|"type"|"allOf"|"anyOf"|"oneOf"|"not"|"format"|"contentEncoding"|"contentMediaType"|"contentSchema"|"if"|"then"|"else"|"unevaluatedItems"|"unevaluatedProperties"),
        Draft::D2020 => matches!(kw,
