    }
}

impl Dialect {
    pub fn recognizes(&self, kw: &str) -> bool {
        if kw == "$ref" { return true; }
        if !keyword_in_draft(kw, self.draft) {
            // special: legacy "dependencies" recognized in all (already included), "additionalItems" in 2020 handled if items array (compiler legacy)
            return false;
