// ---------- Dialect determination ----------
pub fn unknown_meta_error(uri: &str) -> BuildError {
    berr(format!("Unknown meta-schema: '{}'. Custom meta-schemas must be registered in the registry before use", uri))
}

fn vocab_from_uri(u: &str) -> Option<Vocab> {
    let suffix = u.rsplit("/vocab/").next()?;
    Some(match suffix {
        "core" => Vocab::Core,
        "applicator" => Vocab::Applicator,
        "validation" => Vocab::Validation,
        "meta-data" => Vocab::MetaData,
        "format-annotation" => Vocab::FormatAnnotation,
        "format-assertion" => Vocab::FormatAssertion,
        "format" => Vocab::FormatAnnotation,
        "content" => Vocab::Content,
        "unevaluated" => Vocab::Unevaluated,
        _ => return None,
    })
}

pub fn determine_dialect(reg: &mut Registry, value: &Value, options: &BuildOptions) -> BResult<Dialect> {
    determine_dialect_rec(reg, value, options, 0)
}
fn determine_dialect_rec(reg: &mut Registry, value: &Value, options: &BuildOptions, depth: usize) -> BResult<Dialect> {
    let schema_uri = value.as_object().and_then(|o| o.get("$schema")).and_then(|v| v.as_str()).map(|s| s.to_string());
    if let Some(fd) = options.forced_draft {
        if matches!(fd, Draft::D2019 | Draft::D2020) {
            if let Some(u) = &schema_uri {
                if let Some(sd) = meta::standard_draft_for_meta_uri(u) {
                    if matches!(sd, Draft::D4 | Draft::D6 | Draft::D7) {
                        return Ok(Dialect { draft: fd, vocab: VocabMode::Empty });
                    }
                    return Ok(Dialect::standard(fd));
                }
                // custom: attempt retrieval, ignore failures
                if depth < 4 {
                    if let Ok(d) = custom_meta_dialect(reg, u, options, fd, depth) {
                        return Ok(d);
                    }
                }
            }
        }
        return Ok(Dialect::standard(fd));
    }
    match &schema_uri {
        None => Ok(Dialect::standard(Draft::D2020)),
        Some(u) => {
            if let Some(d) = meta::standard_draft_for_meta_uri(u) {
                Ok(Dialect::standard(d))
            } else {
                custom_meta_dialect(reg, u, options, Draft::D2020, depth)
            }
        }
    }
}

fn custom_meta_dialect(reg: &mut Registry, u: &str, options: &BuildOptions, base_draft: Draft, depth: usize) -> BResult<Dialect> {
    // fragment-carrying $schema is not a usable meta URI in the original
    let (_, frag) = uri::split_fragment(u);
    if matches!(frag, Some(f) if !f.is_empty()) {
        return Err(unknown_meta_error(u));
    }
    let no_frag = strip_frag(u).to_string();
    let (doc, _ptr) = reg.get_or_retrieve(&no_frag).map_err(|_| unknown_meta_error(u))?;
    let meta_val = doc.value.as_ref().clone();
    // A custom meta whose own $schema is another unknown custom meta leads to
    // an error mentioning that nested URI in the original.
    if depth < 4 {
        if let Some(mu) = meta_val.as_object().and_then(|o| o.get("$schema")).and_then(|v| v.as_str()) {
            if meta::standard_draft_for_meta_uri(mu).is_none() {
                // try to resolve it; failure propagates with the nested URI
                determine_dialect_rec(reg, &meta_val, &BuildOptions { forced_draft: None, assert_format: false, http: options.http.clone() }, depth + 1)?;
            }
        }
    }
    if let Some(mo) = meta_val.as_object() {
        let id_matches = mo.get("$id").and_then(|v| v.as_str()).map(|id| strip_frag(id) == no_frag).unwrap_or(false);
        if id_matches {
            if let Some(vocab) = mo.get("$vocabulary").and_then(|v| v.as_object()) {
                let mut set = HashSet::new();
                for (k, _) in vocab {
                    if let Some(v) = vocab_from_uri(k) { set.insert(v); }
                }
                return Ok(Dialect { draft: base_draft, vocab: VocabMode::Set(set) });
            }
        }
    }
    Ok(Dialect { draft: base_draft, vocab: VocabMode::AllButContains })
}

pub fn meta_draft_for_build(value: &Value, options: &BuildOptions) -> Draft {
    if let Some(f) = options.forced_draft { return f; }
    if let Some(u) = value.as_object().and_then(|o| o.get("$schema")).and_then(|v| v.as_str()) {
        if let Some(d) = meta::standard_draft_for_meta_uri(u) { return d; }
    }
    Draft::D2020
}

// ---------- Validator construction ----------
impl Validator {
    pub fn build(root_doc_uri: &str, registry: Registry, options: BuildOptions) -> BResult<Validator> {
        // registry already contains root doc (indexed by caller)
        let mut registry = registry;
        let root_value = {
            let doc = registry.docs.get(root_doc_uri).ok_or_else(|| berr("root doc missing".into()))?.clone();
            doc.value.as_ref().clone()
        };
        let root_dialect = determine_dialect(&mut registry, &root_value, &options)?;
        // meta-validation (skipped for boolean root schemas)
        if !root_value.is_boolean() {
            let md = meta_draft_for_build(&root_value, &options);
            let meta_validator = build_embedded_meta_validator(md, &options)?;
            let outcome = meta_validator.validate(&root_value);
            if !outcome.unit.valid {
                if let Some(e) = outcome.text_errors.first() {
                    return Err(berr(e.msg.clone()));
                } else {
                    return Err(berr("Schema is invalid".into()));
                }
            }
        }
        Self::build_no_meta(root_doc_uri, registry, options, root_dialect)
    }

    pub fn build_no_meta(root_doc_uri: &str, registry: Registry, options: BuildOptions, root_dialect: Dialect) -> BResult<Validator> {
        let v = Validator {
            registry: RefCell::new(registry),
            nodes: RefCell::new(Vec::new()),
            node_map: RefCell::new(HashMap::new()),
            root: usize::MAX,
            options,
            root_doc_uri: root_doc_uri.to_string(),
            root_dialect: root_dialect.clone(),
            resource_dialects: RefCell::new(HashMap::new()),
        };
        // check root value kind
        {
            let reg = v.registry.borrow();
            let doc = reg.docs.get(root_doc_uri).ok_or_else(|| berr("root doc missing".into()))?;
            let rv = doc.value.as_ref();
            if !(rv.is_object() || rv.is_boolean()) {
                return Err(berr(format!("{} is not of types \"boolean\", \"object\"", rv)));
            }
        }
        let root = v.compile_node(root_doc_uri, &[], root_dialect)?;
        let mut v = v;
        v.root = root;
        Ok(v)
    }

    fn resource_dialect_for_value(&self, value: &Value, cache_key: &str) -> BResult<Dialect> {
        if let Some(d) = self.resource_dialects.borrow().get(cache_key) { return Ok(d.clone()); }
        // default draft when $schema missing = root dialect draft
        let schema_uri = value.as_object().and_then(|o| o.get("$schema")).and_then(|v| v.as_str()).map(|s| s.to_string());
        let d = match &schema_uri {
            None => Dialect::standard(self.root_dialect.draft),
            Some(u) => {
                let mut reg = self.registry.borrow_mut();
                determine_dialect(&mut reg, value, &self.options)?
            }
        };
        self.resource_dialects.borrow_mut().insert(cache_key.to_string(), d.clone());
        Ok(d)
    }

    fn canonical_context(&self, doc: &Document, ptr: &[String]) -> (String, Vec<String>) {
        // returns (base_uri_no_frag, resource_relative_ptr)
        let mut base = doc.uri.clone();
        let mut res: Vec<String> = Vec::new();
        for depth in 0..ptr.len() {
            let prefix = &ptr[..depth];
            if let Some(obj) = value_at(&doc.value, prefix).and_then(|v| v.as_object()) {
                for idkw in ["$id", "id"] {
                    if let Some(ids) = obj.get(idkw).and_then(|v| v.as_str()) {
                        let resolved = uri::resolve(&base, ids);
                        base = strip_frag(&resolved).to_string();
                        res.clear();
                        break;
                    }
                }
            }
            res.push(ptr[depth].clone());
        }
        if let Some(obj) = value_at(&doc.value, ptr).and_then(|v| v.as_object()) {
            for idkw in ["$id", "id"] {
                if let Some(ids) = obj.get(idkw).and_then(|v| v.as_str()) {
                    let resolved = uri::resolve(&base, ids);
                    base = strip_frag(&resolved).to_string();
                    res.clear();
                    break;
                }
            }
        }
        (base, res)
    }

    pub fn compile_node(&self, doc_uri: &str, ptr: &[String], dialect: Dialect) -> BResult<usize> {
        let key = format!("{}#{}|{}", doc_uri, uri::pointer_from_tokens(ptr), dialect_key(&dialect));
        if let Some(&i) = self.node_map.borrow().get(&key) { return Ok(i); }
        let idx = {
            let mut nodes = self.nodes.borrow_mut();
            nodes.push(None);
            nodes.len() - 1
        };
        self.node_map.borrow_mut().insert(key, idx);
        let node = self.compile_node_inner(doc_uri, ptr, dialect)?;
        self.nodes.borrow_mut()[idx] = Some(Rc::new(node));
        Ok(idx)
    }

    fn compile_node_inner(&self, doc_uri: &str, ptr: &[String], dialect: Dialect) -> BResult<Node> {
        let (doc, value) = {
            let reg = self.registry.borrow();
            let doc = reg.docs.get(doc_uri).ok_or_else(|| berr(format!("Resource '{}' is not present in a registry and retrieving it failed: No such file or directory (os error 2)", doc_uri)))?.clone();
            let v = value_at(&doc.value, ptr).ok_or_else(|| berr(format!("Pointer '{}' does not exist", uri::pointer_from_tokens(ptr))))?.clone();
            (doc, v)
        };
        let (base_uri, res_ptr) = self.canonical_context(&doc, ptr);
        let abs_loc = if res_ptr.is_empty() { format!("{}#", base_uri) } else { format!("{}#{}", base_uri, uri::pointer_from_tokens(&res_ptr)) };
        // effective dialect: if this node declares an id (new resource) and it's not the doc root, determine its own dialect
        let mut eff_dialect = dialect.clone();
        if let Some(obj) = value.as_object() {
            let declares_id = obj.contains_key("$id") || obj.contains_key("id");
            if declares_id && !ptr.is_empty() {
                let ck = format!("{}#{}", doc_uri, uri::pointer_from_tokens(ptr));
                if let Ok(d) = self.resource_dialect_for_value(&value, &ck) { eff_dialect = d; }
            }
        }
        if let Some(b) = value.as_bool() {
            return Ok(Node { is_bool: Some(b), keywords: Vec::new(), annotations: None, abs_loc, base_uri, doc_uri: doc_uri.to_string(), ptr: ptr.to_vec(), dialect: eff_dialect });
        }
        let obj = match value.as_object() {
            Some(o) => o.clone(),
            None => return Err(berr(format!("{} is not of types \"boolean\", \"object\"", value))),
        };
        self.compile_object(doc_uri, ptr, &obj, eff_dialect, abs_loc, base_uri)
    }
}
