{"command":"cat >> src/validator.rs <<'RS'

impl Validator {
    fn child_ptr(&self, ptr: &[String], toks: &[&str]) -> Vec<String> {
        let mut p = ptr.to_vec();
        for t in toks { p.push(t.to_string()); }
        p
    }
    fn compile_child(&self, doc_uri: &str, ptr: &[String], toks: &[&str], dialect: Dialect) -> BResult<usize> {
        let p = self.child_ptr(ptr, toks);
        self.compile_node(doc_uri, &p, dialect)
    }

    fn compile_object(&self, doc_uri: &str, ptr: &[String], obj: &Map<String, Value>, dialect: Dialect, abs_loc: String, base_uri: String) -> BResult<Node> {
        let recognises = |k: &str| dialect.recognizes(k);
        // $ref siblings ignored in drafts <= 7
        let ref_ignores_siblings = matches!(dialect.draft, Draft::D4 | Draft::D6 | Draft::D7)
            && obj.get("$ref").map(|v| v.is_string()).unwrap_or(false) && recognises("$ref");
        let mut keywords: Vec<Keyword> = Vec::new();
        let mut compiled_names: HashSet<String> = HashSet::new();
        let get = |k: &str| -> Option<&Value> { if recognises(k) { obj.get(k) } else { None } };

        if !ref_ignores_siblings {
            // type
            if let Some(v) = get("type") {
                let mut types = Vec::new();
                match v {
                    Value::String(s) => types.push(s.clone()),
                    Value::Array(a) => { for it in a { if let Some(s) = it.as_str() { types.push(s.to_string()); } } }
                    _ => {}
                }
                types.sort(); types.dedup();
                keywords.push(Keyword { name: "type".into(), kind: KwKind::Type(types) });
                compiled_names.insert("type".into());
            }
            if get("const").is_some() { keywords.push(Keyword { name: "const".into(), kind: KwKind::Const }); compiled_names.insert("const".into()); }
            if get("enum").is_some() { keywords.push(Keyword { name: "enum".into(), kind: KwKind::Enum }); compiled_names.insert("enum".into()); }
            // numeric (draft4 exclusive bool handled in eval via dialect; here store raw values)
            if dialect.draft == Draft::D4 {
                if let Some(v) = get("minimum").cloned() {
                    let ex = get("exclusiveMinimum").and_then(|x| x.as_bool()).unwrap_or(false);
                    if ex { keywords.push(Keyword { name: "exclusiveMinimum".into(), kind: KwKind::ExclusiveMinimum(v) }); }
                    else { keywords.push(Keyword { name: "minimum".into(), kind: KwKind::Minimum(v) }); }
                    compiled_names.insert("minimum".into());
                }
                if get("exclusiveMinimum").is_some() { compiled_names.insert("exclusiveMinimum".into()); }
                if let Some(v) = get("maximum").cloned() {
                    let ex = get("exclusiveMaximum").and_then(|x| x.as_bool()).unwrap_or(false);
                    if ex { keywords.push(Keyword { name: "exclusiveMaximum".into(), kind: KwKind::ExclusiveMaximum(v) }); }
                    else { keywords.push(Keyword { name: "maximum".into(), kind: KwKind::Maximum(v) }); }
                    compiled_names.insert("maximum".into());
                }
                if get("exclusiveMaximum").is_some() { compiled_names.insert("exclusiveMaximum".into()); }
            } else {
                if let Some(v) = get("minimum").cloned() { keywords.push(Keyword { name: "minimum".into(), kind: KwKind::Minimum(v) }); compiled_names.insert("minimum".into()); }
                if let Some(v) = get("maximum").cloned() { keywords.push(Keyword { name: "maximum".into(), kind: KwKind::Maximum(v) }); compiled_names.insert("maximum".into()); }
                if let Some(v) = get("exclusiveMinimum").cloned() { keywords.push(Keyword { name: "exclusiveMinimum".into(), kind: KwKind::ExclusiveMinimum(v) }); compiled_names.insert("exclusiveMinimum".into()); }
                if let Some(v) = get("exclusiveMaximum").cloned() { keywords.push(Keyword { name: "exclusiveMaximum".into(), kind: KwKind::ExclusiveMaximum(v) }); compiled_names.insert("exclusiveMaximum".into()); }
            }
            if let Some(v) = get("multipleOf").cloned() { keywords.push(Keyword { name: "multipleOf".into(), kind: KwKind::MultipleOf(v) }); compiled_names.insert("multipleOf".into()); }
            if let Some(v) = get("minLength") { if let Some(n) = num::as_usize(v) { keywords.push(Keyword { name: "minLength".into(), kind: KwKind::MinLength(n) }); } compiled_names.insert("minLength".into()); }
            if let Some(v) = get("maxLength") { if let Some(n) = num::as_usize(v) { keywords.push(Keyword { name: "maxLength".into(), kind: KwKind::MaxLength(n) }); } compiled_names.insert("maxLength".into()); }
            if let Some(v) = get("minItems") { if let Some(n) = num::as_usize(v) { keywords.push(Keyword { name: "minItems".into(), kind: KwKind::MinItems(n) }); } compiled_names.insert("minItems".into()); }
            if let Some(v) = get("maxItems") { if let Some(n) = num::as_usize(v) { keywords.push(Keyword { name: "maxItems".into(), kind: KwKind::MaxItems(n) }); } compiled_names.insert("maxItems".into()); }
            if let Some(v) = get("uniqueItems") { if v.as_bool() == Some(true) { keywords.push(Keyword { name: "uniqueItems".into(), kind: KwKind::UniqueItems }); } compiled_names.insert("uniqueItems".into()); }
            if let Some(v) = get("minProperties") { if let Some(n) = num::as_usize(v) { keywords.push(Keyword { name: "minProperties".into(), kind: KwKind::MinProperties(n) }); } compiled_names.insert("minProperties".into()); }
            if let Some(v) = get("maxProperties") { if let Some(n) = num::as_usize(v) { keywords.push(Keyword { name: "maxProperties".into(), kind: KwKind::MaxProperties(n) }); } compiled_names.insert("maxProperties".into()); }
            if let Some(v) = get("required") {
                let req: Vec<String> = v.as_array().map(|a| a.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect()).unwrap_or_default();
                keywords.push(Keyword { name: "required".into(), kind: KwKind::Required(req) });
                compiled_names.insert("required".into());
            }
            if let Some(v) = get("dependentRequired") {
                let mut entries = Vec::new();
                if let Some(m) = v.as_object() {
                    for (k, arr) in m {
                        let req: Vec<String> = arr.as_array().map(|a| a.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect()).unwrap_or_default();
                        entries.push((k.clone(), req));
                    }
                }
                keywords.push(Keyword { name: "dependentRequired".into(), kind: KwKind::DependentRequired(entries) });
                compiled_names.insert("dependentRequired".into());
            }
            if let Some(v) = get("dependencies").cloned() {
                let mut entries = Vec::new();
                if let Some(m) = v.as_object() {
                    for (k, dv) in m {
                        if let Some(arr) = dv.as_array() {
                            let req: Vec<String> = arr.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect();
                            entries.push((k.clone(), DepVal::Required(req)));
                        } else {
                            let child = self.compile_child(doc_uri, ptr, &["dependencies", k], dialect.clone())?;
                            entries.push((k.clone(), DepVal::Schema(child)));
                        }
                    }
                }
                keywords.push(Keyword { name: "dependencies".into(), kind: KwKind::Dependencies(entries) });
                compiled_names.insert("dependencies".into());
            }
            // Object properties group
            let has_props = get("properties").is_some();
            let has_pattern = get("patternProperties").is_some();
            let has_add = get("additionalProperties").is_some();
            if has_props || has_pattern || has_add {
                let mut properties = Vec::new();
                if let Some(m) = get("properties").and_then(|v| v.as_object()).cloned() {
                    for (pk, _) in &m {
                        let child = self.compile_child(doc_uri, ptr, &["properties", pk], dialect.clone())?;
                        properties.push((pk.clone(), child));
                    }
                }
                let mut pattern_properties = Vec::new();
                if let Some(m) = get("patternProperties").and_then(|v| v.as_object()).cloned() {
                    for (pk, pv) in &m {
                        let re = compile_regex(pk).map_err(|_| berr(format!("{} is not a \"regex\"", pv)))?;
                        let child = self.compile_child(doc_uri, ptr, &["patternProperties", pk], dialect.clone())?;
                        pattern_properties.push((Rc::new(re), pk.clone(), child));
                    }
                }
                let additional = if let Some(av) = get("additionalProperties").cloned() {
                    match &av {
                        Value::Bool(false) => Some(Additional::BoolFalse),
                        Value::Bool(true) => Some(Additional::BoolTrue),
                        _ => Some(Additional::Schema(self.compile_child(doc_uri, ptr, &["additionalProperties"], dialect.clone())?)),
                    }
                } else { None };
                keywords.push(Keyword { name: "properties".into(), kind: KwKind::ObjectProps(Rc::new(ObjectProps { properties, pattern_properties, additional, has_properties_kw: has_props, has_pattern_kw: has_pattern })) });
                if has_props { compiled_names.insert("properties".into()); }
                if has_pattern { compiled_names.insert("patternProperties".into()); }
                if has_add { compiled_names.insert("additionalProperties".into()); }
            }
            if get("propertyNames").is_some() {
                let child = self.compile_child(doc_uri, ptr, &["propertyNames"], dialect.clone())?;
                keywords.push(Keyword { name: "propertyNames".into(), kind: KwKind::PropertyNames(child) });
                compiled_names.insert("propertyNames".into());
            }
            if let Some(v) = get("dependentSchemas").cloned() {
                let mut entries = Vec::new();
                if let Some(m) = v.as_object() {
                    for (k, _) in m {
                        let child = self.compile_child(doc_uri, ptr, &["dependentSchemas", k], dialect.clone())?;
                        entries.push((k.clone(), child));
                    }
                }
                keywords.push(Keyword { name: "dependentSchemas".into(), kind: KwKind::DependentSchemas(entries) });
                compiled_names.insert("dependentSchemas".into());
            }
            if let Some(v) = get("pattern").cloned() {
                if let Some(p) = v.as_str() {
                    let re = compile_regex(p).map_err(|_| berr(format!("{} is not a \"regex\"", Value::String(p.to_string()))))?;
                    keywords.push(Keyword { name: "pattern".into(), kind: KwKind::Pattern(Rc::new(re)) });
                }
                compiled_names.insert("pattern".into());
            }
            if let Some(v) = get("format").cloned() {
                // format node exists only when assertion on and format known; otherwise excluded from annotations but no unit
                if let Some(f) = v.as_str() {
                    if self.options.assert_format && formats::format_is_known(f, dialect.draft) {
                        keywords.push(Keyword { name: "format".into(), kind: KwKind::Format(f.to_string()) });
                    }
                }
                compiled_names.insert("format".into());
            }
            // content in draft6/7 as assertion node
            if matches!(dialect.draft, Draft::D6 | Draft::D7) && (get("contentMediaType").is_some() || get("contentEncoding").is_some()) {
                let media = get("contentMediaType").and_then(|v| v.as_str()).map(|s| s.to_string());
                let enc = get("contentEncoding").and_then(|v| v.as_str()).map(|s| s.to_string());
                keywords.push(Keyword { name: "contentMediaType".into(), kind: KwKind::ContentD67 { media, encoding: enc } });
                compiled_names.insert("contentMediaType".into());
                compiled_names.insert("contentEncoding".into());
                if get("contentSchema").is_some() { compiled_names.insert("contentSchema".into()); }
            }
            // Array items
            let items_val = get("items").cloned();
            let prefix_val = get("prefixItems").cloned();
            let prefix_len = prefix_val.as_ref().and_then(|v| v.as_array()).map(|a| a.len()).unwrap_or(0);
            if let Some(iv) = &items_val {
                match iv {
                    Value::Array(arr) => {
                        // tuple form (pre-2020, and accepted by compiler generally for unvalidated docs)
                        let mut children = Vec::new();
                        for idx in 0..arr.len() {
                            let child = self.compile_child(doc_uri, ptr, &["items", &idx.to_string()], dialect.clone())?;
                            children.push(child);
                        }
                        keywords.push(Keyword { name: "items".into(), kind: KwKind::PrefixItems(children) });
                        // additionalItems
                        if let Some(av) = get("additionalItems").cloned() {
                            compiled_names.insert("additionalItems".into());
                            match &av {
                                Value::Bool(true) => {}
                                _ => {
                                    let child = self.compile_child(doc_uri, ptr, &["additionalItems"], dialect.clone())?;
                                    keywords.push(Keyword { name: "additionalItems".into(), kind: KwKind::AdditionalItems(child, arr.len()) });
                                }
                            }
                        }
                    }
                    _ => {
                        let has_prefix_kw = prefix_val.is_some();
                        let child_dialect = dialect.reset_standard();
                        let child = self.compile_child(doc_uri, ptr, &["items"], child_dialect)?;
                        keywords.push(Keyword { name: "items".into(), kind: KwKind::ItemsSingle { child, has_prefix: has_prefix_kw, prefix_len, legacy_tuple: false } });
                        if get("additionalItems").is_some() { compiled_names.insert("additionalItems".into()); }
                    }
                }
                compiled_names.insert("items".into());
            }
            if let Some(pv) = &prefix_val {
                if let Some(arr) = pv.as_array() {
                    let mut children = Vec::new();
                    for idx in 0..arr.len() {
                        let child = self.compile_child(doc_uri, ptr, &["prefixItems", &idx.to_string()], dialect.clone())?;
                        children.push(child);
                    }
                    keywords.push(Keyword { name: "prefixItems".into(), kind: KwKind::PrefixItems(children) });
                }
                compiled_names.insert("prefixItems".into());
            }
            if get("contains").is_some() {
                let child = self.compile_child(doc_uri, ptr, &["contains"], dialect.clone())?;
                let min = if matches!(dialect.draft, Draft::D2019|Draft::D2020) { get("minContains").and_then(|v| num::as_usize(v)).or(Some(1)) } else { Some(1) };
                let max = if matches!(dialect.draft, Draft::D2019|Draft::D2020) { get("maxContains").and_then(|v| num::as_usize(v)) } else { None };
                keywords.push(Keyword { name: "contains".into(), kind: KwKind::Contains { child, min, max } });
                compiled_names.insert("contains".into());
                if get("minContains").is_some() { compiled_names.insert("minContains".into()); }
                if get("maxContains").is_some() { compiled_names.insert("maxContains".into()); }
            } else {
                if get("minContains").is_some() { compiled_names.insert("minContains".into()); }
                if get("maxContains").is_some() { compiled_names.insert("maxContains".into()); }
            }
            if get("unevaluatedItems").is_some() {
                let child = self.compile_child(doc_uri, ptr, &["unevaluatedItems"], dialect.clone())?;
                keywords.push(Keyword { name: "unevaluatedItems".into(), kind: KwKind::UnevaluatedItems(child) });
                compiled_names.insert("unevaluatedItems".into());
            }
            if get("unevaluatedProperties").is_some() {
                let child = self.compile_child(doc_uri, ptr, &["unevaluatedProperties"], dialect.clone())?;
                keywords.push(Keyword { name: "unevaluatedProperties".into(), kind: KwKind::UnevaluatedProperties(child) });
                compiled_names.insert("unevaluatedProperties".into());
            }
            for comb in ["allOf", "anyOf", "oneOf"] {
                if let Some(arr) = get(comb).and_then(|v| v.as_array()).cloned() {
                    let mut children = Vec::new();
                    for idx in 0..arr.len() {
                        let child = self.compile_child(doc_uri, ptr, &[comb, &idx.to_string()], dialect.clone())?;
                        children.push(child);
                    }
                    let kind = match comb { "allOf" => KwKind::AllOf(children), "anyOf" => KwKind::AnyOf(children), _ => KwKind::OneOf(children) };
                    keywords.push(Keyword { name: comb.into(), kind });
                    compiled_names.insert(comb.into());
                }
            }
            if let Some(nv) = get("not").cloned() {
                let child = self.compile_child(doc_uri, ptr, &["not"], dialect.clone())?;
                keywords.push(Keyword { name: "not".into(), kind: KwKind::Not(child, nv) });
                compiled_names.insert("not".into());
            }
            if get("if").is_some() {
                let if_ = self.compile_child(doc_uri, ptr, &["if"], dialect.clone())?;
                let then_ = if obj.get("then").is_some() && recognises("then") { Some(self.compile_child(doc_uri, ptr, &["then"], dialect.clone())?) } else { None };
                let else_ = if obj.get("else").is_some() && recognises("else") { Some(self.compile_child(doc_uri, ptr, &["else"], dialect.clone())?) } else { None };
                keywords.push(Keyword { name: "if".into(), kind: KwKind::IfThenElse { if_, then_, else_ } });
                compiled_names.insert("if".into());
                if then_.is_some() { compiled_names.insert("then".into()); }
                if else_.is_some() { compiled_names.insert("else".into()); }
            }
        } // end !ref_ignores_siblings

        // refs (in rank order $dynamicRef, $ref, $recursiveRef handled by sort below)
        if dialect.draft == Draft::D2020 {
            if let Some(rv) = obj.get("$dynamicRef").and_then(|v| v.as_str()).map(|s| s.to_string()) {
                if dialect.recognizes("$dynamicRef") {
                    let target = self.resolve_ref(&base_uri, &rv, &dialect, RefKind::Dynamic)?;
                    keywords.push(Keyword { name: "$dynamicRef".into(), kind: KwKind::DynamicRef(target) });
                    compiled_names.insert("$dynamicRef".into());
                }
            }
        }
        if let Some(rv) = obj.get("$ref").and_then(|v| v.as_str()).map(|s| s.to_string()) {
            let target = self.resolve_ref(&base_uri, &rv, &dialect, RefKind::Static)?;
            keywords.push(Keyword { name: "$ref".into(), kind: KwKind::Ref(target) });
            compiled_names.insert("$ref".into());
        }
        if dialect.draft == Draft::D2019 {
            if let Some(rv) = obj.get("$recursiveRef").and_then(|v| v.as_str()).map(|s| s.to_string()) {
                if dialect.recognizes("$recursiveRef") {
                    let target = self.resolve_ref(&base_uri, &rv, &dialect, RefKind::Recursive)?;
                    keywords.push(Keyword { name: "$recursiveRef".into(), kind: KwKind::RecursiveRef(target) });
                    compiled_names.insert("$recursiveRef".into());
                }
            }
        }

        // Sort by rank (stable)
        keywords.sort_by_key(|k| kw_rank(&k.name));

        // annotations: entries not compiled, minus core excluded
        let annotations = {
            let mut m = Map::new();
            let core_excluded: HashSet<&str> = ["$id", "id", "$schema", "$anchor", "$dynamicAnchor", "$defs", "$recursiveAnchor"].into_iter().collect();
            if ref_ignores_siblings {
                for (k, v) in obj.iter() {
                    if k == "$ref" { continue; }
                    m.insert(k.clone(), v.clone());
                }
            } else {
                for (k, v) in obj.iter() {
                    if compiled_names.contains(k) { continue; }
                    if core_excluded.contains(k.as_str()) { continue; }
                    m.insert(k.clone(), v.clone());
                }
            }
            if m.is_empty() { None } else { Some(Value::Object(m)) }
        };

        Ok(Node { is_bool: None, keywords, annotations, abs_loc, base_uri, doc_uri: doc_uri.to_string(), ptr: ptr.to_vec(), dialect })
    }

    fn resolve_ref(&self, from_base: &str, raw: &str, from_dialect: &Dialect, kind: RefKind) -> BResult<RefTarget> {
        uri::validate_uri_reference(raw).map_err(|e| berr(uri::invalid_uri_error(raw, &e.0)))?;
        let resolved = uri::resolve(from_base, raw);
        let (res_no_frag, frag) = uri::split_fragment(&resolved);
        let res_no_frag = res_no_frag.to_string();
        let frag_owned = frag.map(|s| s.to_string());
        let (doc, resource_ptr) = {
            let mut reg = self.registry.borrow_mut();
            reg.get_or_retrieve(&res_no_frag)?
        };
        let mut is_dynamic = false;
        let target_ptr: Vec<String> = match &frag_owned {
            None => resource_ptr.clone(),
            Some(f) if f.is_empty() => resource_ptr.clone(),
            Some(f) if f.starts_with('/') => {
                let decoded = uri::percent_decode(f);
                let toks = uri::parse_pointer(&decoded);
                let mut full = resource_ptr.clone();
                full.extend(toks);
                if value_at(&doc.value, &full).is_none() {
                    return Err(berr(format!("Pointer '{}' does not exist", f)));
                }
                full
            }
            Some(f) => {
                let anchor = uri::percent_decode(f);
                let key = (res_no_frag.clone(), anchor.clone());
                if let Some(p) = doc.dyn_anchors.get(&key) {
                    is_dynamic = true;
                    p.clone()
                } else if let Some(p) = doc.anchors.get(&key) {
                    p.clone()
                } else {
                    // For $recursiveRef "#" frag is empty handled above. Anchor lookup also in doc with different resource uri? fallback search any
                    return Err(berr(format!("Anchor '{}' does not exist", anchor)));
                }
            }
        };
        let target_val = value_at(&doc.value, &target_ptr).cloned().unwrap_or(Value::Null);
        if !(target_val.is_object() || target_val.is_boolean()) {
            return Err(berr(format!("{} is not of types \"boolean\", \"object\"", target_val)));
        }
        // dialect for target
        let target_dialect = if res_no_frag == from_base {
            from_dialect.reset_standard()
        } else {
            // dialect of the resource containing the target
            let res_val = value_at(&doc.value, &resource_ptr).cloned().unwrap_or(Value::Null);
            let ck = format!("{}#{}", doc.uri, uri::pointer_from_tokens(&resource_ptr));
            self.resource_dialect_for_value(&res_val, &ck)?
        };
        let node = self.compile_node(&doc.uri.clone(), &target_ptr, target_dialect)?;
        let _ = kind;
        Ok(RefTarget { node, raw_ref: raw.to_string(), resolved_uri: resolved, resource_uri: res_no_frag, fragment: frag_owned, is_dynamic_anchor: is_dynamic })
    }
}

#[derive(Clone, Copy, PartialEq)]
pub enum RefKind { Static, Dynamic, Recursive }

pub fn build_embedded_meta_validator(d: Draft, _opts: &BuildOptions) -> BResult<Validator> {
    let doc = meta::meta_doc_for_draft(d);
    let uri = strip_frag(d.meta_uri()).to_string();
    let options = BuildOptions { forced_draft: None, assert_format: false, http: HttpConfig::default() };
    let mut registry = Registry::new(options.clone(), Retriever::default_retriever());
    registry.add_document(&uri, doc)?;
    Validator::build_no_meta(&uri, registry, options, Dialect::standard(d))
}
RS"}

actions.command:
cat >> src/validator.rs <<'RS'

impl Validator {
    fn child_ptr(&self, ptr: &[String], toks: &[&str]) -> Vec<String> {
        let mut p = ptr.to_vec();
        for t in toks { p.push(t.to_string()); }
        p
    }
    fn compile_child(&self, doc_uri: &str, ptr: &[String], toks: &[&str], dialect: Dialect) -> BResult<usize> {
        let p = self.child_ptr(ptr, toks);
        self.compile_node(doc_uri, &p, dialect)
    }

    fn compile_object(&self, doc_uri: &str, ptr: &[String], obj: &Map<String, Value>, dialect: Dialect, abs_loc: String, base_uri: String) -> BResult<Node> {
        let recognises = |k: &str| dialect.recognizes(k);
        // $ref siblings ignored in drafts <= 7
        let ref_ignores_siblings = matches!(dialect.draft, Draft::D4 | Draft::D6 | Draft::D7)
            && obj.get("$ref").map(|v| v.is_string()).unwrap_or(false) && recognises("$ref");
        let mut keywords: Vec<Keyword> = Vec::new();
        let mut compiled_names: HashSet<String> = HashSet::new();
        let get = |k: &str| -> Option<&Value> { if recognises(k) { obj.get(k) } else { None } };

        if !ref_ignores_siblings {
            // type
            if let Some(v) = get("type") {
                let mut types = Vec::new();
                match v {
                    Value::String(s) => types.push(s.clone()),
                    Value::Array(a) => { for it in a { if let Some(s) = it.as_str() { types.push(s.to_string()); } } }
                    _ => {}
                }
                types.sort(); types.dedup();
                keywords.push(Keyword { name: "type".into(), kind: KwKind::Type(types) });
                compiled_names.insert("type".into());
            }
            if get("const").is_some() { keywords.push(Keyword { name: "const".into(), kind: KwKind::Const }); compiled_names.insert("const".into()); }
            if get("enum").is_some() { keywords.push(Keyword { name: "enum".into(), kind: KwKind::Enum }); compiled_names.insert("enum".into()); }
            // numeric (draft4 exclusive bool handled in eval via dialect; here store raw values)
            if dialect.draft == Draft::D4 {
                if let Some(v) = get("minimum").cloned() {
                    let ex = get("exclusiveMinimum").and_then(|x| x.as_bool()).unwrap_or(false);
                    if ex { keywords.push(Keyword { name: "exclusiveMinimum".into(), kind: KwKind::ExclusiveMinimum(v) }); }
                    else { keywords.push(Keyword { name: "minimum".into(), kind: KwKind::Minimum(v) }); }
                    compiled_names.insert("minimum".into());
                }
                if get("exclusiveMinimum").is_some() { compiled_names.insert("exclusiveMinimum".into()); }
                if let Some(v) = get("maximum").cloned() {
                    let ex = get("exclusiveMaximum").and_then(|x| x.as_bool()).unwrap_or(false);
                    if ex { keywords.push(Keyword { name: "exclusiveMaximum".into(), kind: KwKind::ExclusiveMaximum(v) }); }
                    else { keywords.push(Keyword { name: "maximum".into(), kind: KwKind::Maximum(v) }); }
                    compiled_names.insert("maximum".into());
                }
                if get("exclusiveMaximum").is_some() { compiled_names.insert("exclusiveMaximum".into()); }
            } else {
                if let Some(v) = get("minimum").cloned() { keywords.push(Keyword { name: "minimum".into(), kind: KwKind::Minimum(v) }); compiled_names.insert("minimum".into()); }
                if let Some(v) = get("maximum").cloned() { keywords.push(Keyword { name: "maximum".into(), kind: KwKind::Maximum(v) }); compiled_names.insert("maximum".into()); }
                if let Some(v) = get("exclusiveMinimum").cloned() { keywords.push(Keyword { name: "exclusiveMinimum".into(), kind: KwKind::ExclusiveMinimum(v) }); compiled_names.insert("exclusiveMinimum".into()); }
                if let Some(v) = get("exclusiveMaximum").cloned() { keywords.push(Keyword { name: "exclusiveMaximum".into(), kind: KwKind::ExclusiveMaximum(v) }); compiled_names.insert("exclusiveMaximum".into()); }
            }
            if let Some(v) = get("multipleOf").cloned() { keywords.push(Keyword { name: "multipleOf".into(), kind: KwKind::MultipleOf(v) }); compiled_names.insert("multipleOf".into()); }
            if let Some(v) = get("minLength") { if let Some(n) = num::as_usize(v) { keywords.push(Keyword { name: "minLength".into(), kind: KwKind::MinLength(n) }); } compiled_names.insert("minLength".into()); }
            if let Some(v) = get("maxLength") { if let Some(n) = num::as_usize(v) { keywords.push(Keyword { name: "maxLength".into(), kind: KwKind::MaxLength(n) }); } compiled_names.insert("maxLength".into()); }
            if let Some(v) = get("minItems") { if let Some(n) = num::as_usize(v) { keywords.push(Keyword { name: "minItems".into(), kind: KwKind::MinItems(n) }); } compiled_names.insert("minItems".into()); }
            if let Some(v) = get("maxItems") { if let Some(n) = num::as_usize(v) { keywords.push(Keyword { name: "maxItems".into(), kind: KwKind::MaxItems(n) }); } compiled_names.insert("maxItems".into()); }
            if let Some(v) = get("uniqueItems") { if v.as_bool() == Some(true) { keywords.push(Keyword { name: "uniqueItems".into(), kind: KwKind::UniqueItems }); } compiled_names.insert("uniqueItems".into()); }
            if let Some(v) = get("minProperties") { if let Some(n) = num::as_usize(v) { keywords.push(Keyword { name: "minProperties".into(), kind: KwKind::MinProperties(n) }); } compiled_names.insert("minProperties".into()); }
            if let Some(v) = get("maxProperties") { if let Some(n) = num::as_usize(v) { keywords.push(Keyword { name: "maxProperties".into(), kind: KwKind::MaxProperties(n) }); } compiled_names.insert("maxProperties".into()); }
            if let Some(v) = get("required") {
                let req: Vec<String> = v.as_array().map(|a| a.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect()).unwrap_or_default();
                keywords.push(Keyword { name: "required".into(), kind: KwKind::Required(req) });
                compiled_names.insert("required".into());
            }
            if let Some(v) = get("dependentRequired") {
                let mut entries = Vec::new();
                if let Some(m) = v.as_object() {
                    for (k, arr) in m {
                        let req: Vec<String> = arr.as_array().map(|a| a.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect()).unwrap_or_default();
                        entries.push((k.clone(), req));
                    }
                }
                keywords.push(Keyword { name: "dependentRequired".into(), kind: KwKind::DependentRequired(entries) });
                compiled_names.insert("dependentRequired".into());
            }
            if let Some(v) = get("dependencies").cloned() {
                let mut entries = Vec::new();
                if let Some(m) = v.as_object() {
                    for (k, dv) in m {
                        if let Some(arr) = dv.as_array() {
                            let req: Vec<String> = arr.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect();
                            entries.push((k.clone(), DepVal::Required(req)));
                        } else {
                            let child = self.compile_child(doc_uri, ptr, &["dependencies", k], dialect.clone())?;
                            entries.push((k.clone(), DepVal::Schema(child)));
                        }
                    }
                }
                keywords.push(Keyword { name: "dependencies".into(), kind: KwKind::Dependencies(entries) });
                compiled_names.insert("dependencies".into());
            }
            // Object properties group
            let has_props = get("properties").is_some();
            let has_pattern = get("patternProperties").is_some();
            let has_add = get("additionalProperties").is_some();
            if has_props || has_pattern || has_add {
                let mut properties = Vec::new();
                if let Some(m) = get("properties").and_then(|v| v.as_object()).cloned() {
                    for (pk, _) in &m {
                        let child = self.compile_child(doc_uri, ptr, &["properties", pk], dialect.clone())?;
                        properties.push((pk.clone(), child));
                    }
                }
                let mut pattern_properties = Vec::new();
                if let Some(m) = get("patternProperties").and_then(|v| v.as_object()).cloned() {
                    for (pk, pv) in &m {
                        let re = compile_regex(pk).map_err(|_| berr(format!("{} is not a \"regex\"", pv)))?;
                        let child = self.compile_child(doc_uri, ptr, &["patternProperties", pk], dialect.clone())?;
                        pattern_properties.push((Rc::new(re), pk.clone(), child));
                    }
                }
                let additional = if let Some(av) = get("additionalProperties").cloned() {
                    match &av {
                        Value::Bool(false) => Some(Additional::BoolFalse),
                        Value::Bool(true) => Some(Additional::BoolTrue),
                        _ => Some(Additional::Schema(self.compile_child(doc_uri, ptr, &["additionalProperties"], dialect.clone())?)),
                    }
                } else { None };
                keywords.push(Keyword { name: "properties".into(), kind: KwKind::ObjectProps(Rc::new(ObjectProps { properties, pattern_properties, additional, has_properties_kw: has_props, has_pattern_kw: has_pattern })) });
                if has_props { compiled_names.insert("properties".into()); }
                if has_pattern { compiled_names.insert("patternProperties".into()); }
                if has_add { compiled_names.insert("additionalProperties".into()); }
            }
            if get("propertyNames").is_some() {
                let child = self.compile_child(doc_uri, ptr, &["propertyNames"], dialect.clone())?;
                keywords.push(Keyword { name: "propertyNames".into(), kind: KwKind::PropertyNames(child) });
                compiled_names.insert("propertyNames".into());
            }
            if let Some(v) = get("dependentSchemas").cloned() {
                let mut entries = Vec::new();
                if let Some(m) = v.as_object() {
                    for (k, _) in m {
                        let child = self.compile_child(doc_uri, ptr, &["dependentSchemas", k], dialect.clone())?;
                        entries.push((k.clone(), child));
                    }
                }
                keywords.push(Keyword { name: "dependentSchemas".into(), kind: KwKind::DependentSchemas(entries) });
                compiled_names.insert("dependentSchemas".into());
            }
            if let Some(v) = get("pattern").cloned() {
                if let Some(p) = v.as_str() {
                    let re = compile_regex(p).map_err(|_| berr(format!("{} is not a \"regex\"", Value::String(p.to_string()))))?;
                    keywords.push(Keyword { name: "pattern".into(), kind: KwKind::Pattern(Rc::new(re)) });
                }
                compiled_names.insert("pattern".into());
            }
            if let Some(v) = get("format").cloned() {
                // format node exists only when assertion on and format known; otherwise excluded from annotations but no unit
                if let Some(f) = v.as_str() {
                    if self.options.assert_format && formats::format_is_known(f, dialect.draft) {
                        keywords.push(Keyword { name: "format".into(), kind: KwKind::Format(f.to_string()) });
                    }
                }
                compiled_names.insert("format".into());
            }
            // content in draft6/7 as assertion node
            if matches!(dialect.draft, Draft::D6 | Draft::D7) && (get("contentMediaType").is_some() || get("contentEncoding").is_some()) {
                let media = get("contentMediaType").and_then(|v| v.as_str()).map(|s| s.to_string());
                let enc = get("contentEncoding").and_then(|v| v.as_str()).map(|s| s.to_string());
                keywords.push(Keyword { name: "contentMediaType".into(), kind: KwKind::ContentD67 { media, encoding: enc } });
                compiled_names.insert("contentMediaType".into());
                compiled_names.insert("contentEncoding".into());
                if get("contentSchema").is_some() { compiled_names.insert("contentSchema".into()); }
            }
            // Array items
            let items_val = get("items").cloned();
            let prefix_val = get("prefixItems").cloned();
            let prefix_len = prefix_val.as_ref().and_then(|v| v.as_array()).map(|a| a.len()).unwrap_or(0);
            if let Some(iv) = &items_val {
                match iv {
                    Value::Array(arr) => {
                        // tuple form (pre-2020, and accepted by compiler generally for unvalidated docs)
                        let mut children = Vec::new();
                        for idx in 0..arr.len() {
                            let child = self.compile_child(doc_uri, ptr, &["items", &idx.to_string()], dialect.clone())?;
                            children.push(child);
                        }
                        keywords.push(Keyword { name: "items".into(), kind: KwKind::PrefixItems(children) });
                        // additionalItems
                        if let Some(av) = get("additionalItems").cloned() {
                            compiled_names.insert("additionalItems".into());
                            match &av {
                                Value::Bool(true) => {}
                                _ => {
                                    let child = self.compile_child(doc_uri, ptr, &["additionalItems"], dialect.clone())?;
                                    keywords.push(Keyword { name: "additionalItems".into(), kind: KwKind::AdditionalItems(child, arr.len()) });
                                }
                            }
                        }
                    }
                    _ => {
                        let has_prefix_kw = prefix_val.is_some();
                        let child_dialect = dialect.reset_standard();
                        let child = self.compile_child(doc_uri, ptr, &["items"], child_dialect)?;
                        keywords.push(Keyword { name: "items".into(), kind: KwKind::ItemsSingle { child, has_prefix: has_prefix_kw, prefix_len, legacy_tuple: false } });
                        if get("additionalItems").is_some() { compiled_names.insert("additionalItems".into()); }
                    }
                }
                compiled_names.insert("items".into());
            }
            if let Some(pv) = &prefix_val {
                if let Some(arr) = pv.as_array() {
                    let mut children = Vec::new();
                    for idx in 0..arr.len() {
                        let child = self.compile_child(doc_uri, ptr, &["prefixItems", &idx.to_string()], dialect.clone())?;
                        children.push(child);
                    }
                    keywords.push(Keyword { name: "prefixItems".into(), kind: KwKind::PrefixItems(children) });
                }
                compiled_names.insert("prefixItems".into());
            }
            if get("contains").is_some() {
                let child = self.compile_child(doc_uri, ptr, &["contains"], dialect.clone())?;
                let min = if matches!(dialect.draft, Draft::D2019|Draft::D2020) { get("minContains").and_then(|v| num::as_usize(v)).or(Some(1)) } else { Some(1) };
                let max = if matches!(dialect.draft, Draft::D2019|Draft::D2020) { get("maxContains").and_then(|v| num::as_usize(v)) } else { None };
                keywords.push(Keyword { name: "contains".into(), kind: KwKind::Contains { child, min, max } });
                compiled_names.insert("contains".into());
                if get("minContains").is_some() { compiled_names.insert("minContains".into()); }
                if get("maxContains").is_some() { compiled_names.insert("maxContains".into()); }
            } else {
                if get("minContains").is_some() { compiled_names.insert("minContains".into()); }
                if get("maxContains").is_some() { compiled_names.insert("maxContains".into()); }
            }
            if get("unevaluatedItems").is_some() {
                let child = self.compile_child(doc_uri, ptr, &["unevaluatedItems"], dialect.clone())?;
                keywords.push(Keyword { name: "unevaluatedItems".into(), kind: KwKind::UnevaluatedItems(child) });
                compiled_names.insert("unevaluatedItems".into());
            }
            if get("unevaluatedProperties").is_some() {
                let child = self.compile_child(doc_uri, ptr, &["unevaluatedProperties"], dialect.clone())?;
                keywords.push(Keyword { name: "unevaluatedProperties".into(), kind: KwKind::UnevaluatedProperties(child) });
                compiled_names.insert("unevaluatedProperties".into());
            }
            for comb in ["allOf", "anyOf", "oneOf"] {
                if let Some(arr) = get(comb).and_then(|v| v.as_array()).cloned() {
                    let mut children = Vec::new();
                    for idx in 0..arr.len() {
                        let child = self.compile_child(doc_uri, ptr, &[comb, &idx.to_string()], dialect.clone())?;
                        children.push(child);
                    }
                    let kind = match comb { "allOf" => KwKind::AllOf(children), "anyOf" => KwKind::AnyOf(children), _ => KwKind::OneOf(children) };
                    keywords.push(Keyword { name: comb.into(), kind });
