        };

        Ok(Node { is_bool: None, keywords, annotations, abs_loc, base_uri, doc_uri: doc_uri.to_string(), ptr: ptr.to_vec(), dialect })
    }

    fn resolve_ref(&self, from_base: &str, raw: &str, from_dialect: &Dialect, kind: RefKind) -> BResult<RefTarget> {
        uri::validate_uri_reference(raw).map_err(|e| berr(uri::invalid_uri_error(raw, &e.0)))?;
        let resolved = uri::resolve(from_base, raw);
        let (res_no_frag, frag) = uri::split_fragment(&resolved);
        let res_no_frag = res_no_frag.to_string();
        let frag_owned = frag.map(|s| s.to_string());
        let (doc, resource_ptr) = {
            let mut reg = self.registry.borrow_mut();
            reg.get_or_retrieve(&res_no_frag)?
        };
        let mut is_dynamic = false;
        let target_ptr: Vec<String> = match &frag_owned {
            None => resource_ptr.clone(),
            Some(f) if f.is_empty() => resource_ptr.clone(),
            Some(f) if f.starts_with('/') => {
                let decoded = uri::percent_decode(f);
                let toks = uri::parse_pointer(&decoded);
                let mut full = resource_ptr.clone();
                full.extend(toks);
                if value_at(&doc.value, &full).is_none() {
                    return Err(berr(format!("Pointer '{}' does not exist", f)));
                }
                full
            }
            Some(f) => {
                let anchor = uri::percent_decode(f);
                let key = (res_no_frag.clone(), anchor.clone());
                if let Some(p) = doc.dyn_anchors.get(&key) {
                    is_dynamic = true;
                    p.clone()
                } else if let Some(p) = doc.anchors.get(&key) {
                    p.clone()
                } else {
                    // For $recursiveRef "#" frag is empty handled above. Anchor lookup also in doc with different resource uri? fallback search any
                    return Err(berr(format!("Anchor '{}' does not exist", anchor)));
                }
            }
        };
        let target_val = value_at(&doc.value, &target_ptr).cloned().unwrap_or(Value::Null);
        if !(target_val.is_object() || target_val.is_boolean()) {
            return Err(berr(format!("{} is not of types \"boolean\", \"object\"", target_val)));
        }
        // dialect for target
        let target_dialect = if res_no_frag == from_base {
            from_dialect.reset_standard()
        } else {
            // dialect of the resource containing the target
            let res_val = value_at(&doc.value, &resource_ptr).cloned().unwrap_or(Value::Null);
            let ck = format!("{}#{}", doc.uri, uri::pointer_from_tokens(&resource_ptr));
            self.resource_dialect_for_value(&res_val, &ck)?
        };
        let node = self.compile_node(&doc.uri.clone(), &target_ptr, target_dialect)?;
        let _ = kind;
        Ok(RefTarget { node, raw_ref: raw.to_string(), resolved_uri: resolved, resource_uri: res_no_frag, fragment: frag_owned, is_dynamic_anchor: is_dynamic })
    }
}

#[derive(Clone, Copy, PartialEq)]
pub enum RefKind { Static, Dynamic, Recursive }

pub fn build_embedded_meta_validator(d: Draft, _opts: &BuildOptions) -> BResult<Validator> {
    let doc = meta::meta_doc_for_draft(d);
    let uri = strip_frag(d.meta_uri()).to_string();
    let options = BuildOptions { forced_draft: None, assert_format: false, http: HttpConfig::default() };
    let mut registry = Registry::new(options.clone(), Retriever::default_retriever());
    registry.add_document(&uri, doc)?;
    Validator::build_no_meta(&uri, registry, options, Dialect::standard(d))
}
