            if let Some(rv) = obj.get("$recursiveRef").and_then(|v| v.as_str()).map(|s| s.to_string()) {
                if dialect.recognizes("$recursiveRef") {
                    let target = self.resolve_ref(&base_uri, &rv, &dialect, RefKind::Recursive)?;
                    keywords.push(Keyword { name: "$recursiveRef".into(), kind: KwKind::RecursiveRef(target) });
                    compiled_names.insert("$recursiveRef".into());
                }
            }
        }

        // Sort by rank (stable)
        keywords.sort_by_key(|k| kw_rank(&k.name));

        // annotations: entries not compiled, minus core excluded
        let annotations = {
            let mut m = Map::new();
            let core_excluded: HashSet<&str> = ["$id", "id", "$schema", "$anchor", "$dynamicAnchor", "$defs", "$recursiveAnchor"].into_iter().collect();
            if ref_ignores_siblings {
                for (k, v) in obj.iter() {
                    if k == "$ref" { continue; }
                    m.insert(k.clone(), v.clone());
                }
            } else {
                for (k, v) in obj.iter() {
                    if compiled_names.contains(k) { continue; }
                    if core_excluded.contains(k.as_str()) { continue; }
                    m.insert(k.clone(), v.clone());
                }
            }
            if m.is_empty() { None } else { Some(Value::Object(m)) }
        };

        Ok(Node { is_bool: None, keywords, annotations, abs_loc, base_uri, doc_uri: doc_uri.to_string(), ptr: ptr.to_vec(), dialect })
    }

    fn resolve_ref(&self, from_base: &str, raw: &str, from_dialect: &Dialect, kind: RefKind) -> BResult<RefTarget> {
        uri::validate_uri_reference(raw).map_err(|e| berr(uri::invalid_uri_error(raw, &e.0)))?;
        let resolved = uri::resolve(from_base, raw);
        let (res_no_frag, frag) = uri::split_fragment(&resolved);
        let res_no_frag = res_no_frag.to_string();
        let frag_owned = frag.map(|s| s.to_string());
        let (doc, resource_ptr) = {
            let mut reg = self.registry.borrow_mut();
            reg.get_or_retrieve(&res_no_frag)?
        };
        let mut is_dynamic = false;
        let target_ptr: Vec<String> = match &frag_owned {
            None => resource_ptr.clone(),
            Some(f) if f.is_empty() => resource_ptr.clone(),
            Some(f) if f.starts_with('/') => {
                let decoded = uri::percent_decode(f);
                let toks = uri::parse_pointer(&decoded);
                let mut full = resource_ptr.clone();
                full.extend(toks);
                if value_at(&doc.value, &full).is_none() {
                    return Err(berr(format!("Pointer '{}' does not exist", f)));
                }
                full
            }
            Some(f) => {
                let anchor = uri::percent_decode(f);
                let key = (res_no_frag.clone(), anchor.clone());
                if let Some(p) = doc.dyn_anchors.get(&key) {
                    is_dynamic = true;
                    p.clone()
                } else if let Some(p) = doc.anchors.get(&key) {
                    p.clone()
                } else {
                    // For $recursiveRef "#" frag is empty handled above. Anchor lookup also in doc with different resource uri? fallback search any
                    return Err(berr(format!("Anchor '{}' does not exist", anchor)));
                }
            }
        };
        let target_val = value_at(&doc.value, &target_ptr).cloned().unwrap_or(Value::Null);
        if !(target_val.is_object() || target_val.is_boolean()) {
            return Err(berr(format!("{} is not of types \"boolean\", \"object\"", target_val)));
        }
        // dialect for target
        let target_dialect = if res_no_frag == from_base {
            from_dialect.reset_standard()
        } else {
            // dialect of the resource containing the target
            let res_val = value_at(&doc.value, &resource_ptr).cloned().unwrap_or(Value::Null);
            let ck = format!("{}#{}", doc.uri, uri::pointer_from_tokens(&resource_ptr));
            self.resource_dialect_for_value(&res_val, &ck)?
        };
        let node = self.compile_node(&doc.uri.clone(), &target_ptr, target_dialect)?;
        let _ = kind;
        Ok(RefTarget { node, raw_ref: raw.to_string(), resolved_uri: resolved, resource_uri: res_no_frag, fragment: frag_owned, is_dynamic_anchor: is_dynamic })
    }
}

#[derive(Clone, Copy, PartialEq)]
pub enum RefKind { Static, Dynamic, Recursive }

pub fn build_embedded_meta_validator(d: Draft, _opts: &BuildOptions) -> BResult<Validator> {
    let doc = meta::meta_doc_for_draft(d);
    let uri = strip_frag(d.meta_uri()).to_string();
    let options = BuildOptions { forced_draft: None, assert_format: false, http: HttpConfig::default() };
    let mut registry = Registry::new(options.clone(), Retriever::default_retriever());
    registry.add_document(&uri, doc)?;
    Validator::build_no_meta(&uri, registry, options, Dialect::standard(d))
}
RS"}

{"command":"cat >> src/validator.rs <<'RS'

// ---------- Evaluation ----------
pub struct Outcome {
    pub unit: Unit,
    pub text_errors: Vec<VError>,
    pub ev_props: HashSet<String>,
    pub ev_items: HashSet<usize>,
    pub ev_items_all: bool,
}
impl Outcome {
    fn valid_leaf(unit: Unit) -> Self { Outcome { unit, text_errors: Vec::new(), ev_props: HashSet::new(), ev_items: HashSet::new(), ev_items_all: false } }
}

struct KwOutcome {
    valid: bool,
    units: Vec<Unit>,
    text_errors: Vec<VError>,
    ev_props: HashSet<String>,
    ev_items: HashSet<usize>,
    ev_items_all: bool,
}
impl KwOutcome {
    fn from_unit(u: Unit) -> Self { let v = u.valid; KwOutcome { valid: v, units: vec![u], text_errors: Vec::new(), ev_props: HashSet::new(), ev_items: HashSet::new(), ev_items_all: false } }
}

pub struct Ctx {
    active: Vec<(usize, usize)>, // (node idx, instance ptr addr)
    dyn_scope: Vec<String>,      // stack of resource uris (no frag) outermost..innermost
}
impl Ctx {
    fn new() -> Self { Ctx { active: Vec::new(), dyn_scope: Vec::new() } }
}

fn inst_id(v: &Value) -> usize { v as *const Value as usize }
fn render(v: &Value) -> String { v.to_string() }
fn join_path(base: &str, seg: &str) -> String { format!("{}/{}", base, uri::escape_pointer_token(seg)) }
fn join_path_raw(base: &str, seg_raw: &str) -> String { format!("{}/{}", base, seg_raw) }
fn schema_join(abs_loc: &str, seg: &str) -> String {
    // abs_loc like scheme://...# or ...#/a/b ; append /seg after fragment
    format!("{}/{}", abs_loc, uri::escape_pointer_token(seg))
}

impl Validator {
    pub fn validate(&self, instance: &Value) -> Outcome {
        let root_node = self.nodes.borrow()[self.root].clone().unwrap();
        let mut ctx = Ctx::new();
        ctx.dyn_scope.push(root_node.base_uri.clone());
        self.eval_node(self.root, instance, "", "", &root_node.abs_loc.clone(), &mut ctx)
    }
    pub fn is_valid(&self, instance: &Value) -> bool { self.validate(instance).unit.valid }

    fn node_rc(&self, idx: usize) -> Rc<Node> { self.nodes.borrow()[idx].clone().unwrap() }

    fn eval_node(&self, idx: usize, instance: &Value, eval_path: &str, inst_loc: &str, schema_loc: &str, ctx: &mut Ctx) -> Outcome {
        let node = self.node_rc(idx);
        // cycle guard: 4th concurrent evaluation of same node+instance -> leaf valid
        let id = inst_id(instance);
        let count = ctx.active.iter().filter(|&&(n, i)| n == idx && i == id).count();
        if count >= 3 {
            return Outcome::valid_leaf(Unit::new(true, eval_path.to_string(), inst_loc.to_string(), schema_loc.to_string()));
        }
        ctx.active.push((idx, id));
        let out = self.eval_node_inner(&node, idx, instance, eval_path, inst_loc, schema_loc, ctx);
        ctx.active.pop();
        out
    }

    fn eval_node_inner(&self, node: &Node, idx: usize, instance: &Value, eval_path: &str, inst_loc: &str, schema_loc: &str, ctx: &mut Ctx) -> Outcome {
        if let Some(b) = node.is_bool {
            let mut u = Unit::new(b, eval_path.to_string(), inst_loc.to_string(), schema_loc.to_string());
            if !b {
                let e = VError::new("falseSchema", format!("False schema does not allow {}", render(instance)));
                u.errors.push(e.clone());
                let mut o = Outcome::valid_leaf(u);
                o.text_errors = vec![e];
                return o;
            }
            return Outcome::valid_leaf(u);
        }
        // Evaluate non-unevaluated keywords first (in order), then unevaluated, assemble in original order
        let n = node.keywords.len();
        let mut results: Vec<Option<KwOutcome>> = (0..n).map(|_| None).collect();
        let mut ev_props_all: HashSet<String> = HashSet::new();
        let mut ev_items_all_kw: HashSet<usize> = HashSet::new();
        let mut ev_all_items = false;
        for (i, kw) in node.keywords.iter().enumerate() {
            if matches!(kw.kind, KwKind::UnevaluatedItems(_) | KwKind::UnevaluatedProperties(_)) { continue; }
            let r = self.eval_keyword(node, idx, kw, instance, eval_path, inst_loc, schema_loc, ctx);
            if r.valid {
                ev_props_all.extend(r.ev_props.iter().cloned());
                ev_items_all_kw.extend(r.ev_items.iter().cloned());
                if r.ev_items_all { ev_all_items = true; }
            }
            results[i] = Some(r);
        }
        // unevaluated
        for (i, kw) in node.keywords.iter().enumerate() {
            let r = match &kw.kind {
                KwKind::UnevaluatedItems(child) => Some(self.eval_unevaluated_items(node, *child, instance, eval_path, inst_loc, schema_loc, ctx, &ev_items_all_kw, ev_all_items)),
                KwKind::UnevaluatedProperties(child) => Some(self.eval_unevaluated_props(node, *child, instance, eval_path, inst_loc, schema_loc, ctx, &ev_props_all)),
                _ => None,
            };
            if let Some(r) = r {
                if r.valid {
                    ev_props_all.extend(r.ev_props.iter().cloned());
                    ev_items_all_kw.extend(r.ev_items.iter().cloned());
                    if r.ev_items_all { ev_all_items = true; }
                }
                results[i] = Some(r);
            }
        }
        let mut valid = true;
        let mut children: Vec<Unit> = Vec::new();
        let mut text_errors: Vec<VError> = Vec::new();
        for r in results.into_iter() {
            let r = r.unwrap();
            if !r.valid { valid = false; }
            children.extend(r.units);
            text_errors.extend(r.text_errors);
        }
        let mut unit = Unit::new(valid, eval_path.to_string(), inst_loc.to_string(), schema_loc.to_string());
        if let Some(a) = &node.annotations {
            if valid { unit.annotations = Some(a.clone()); } else { unit.dropped = Some(a.clone()); }
        }
        unit.children = children;
        Outcome { unit, text_errors, ev_props: ev_props_all, ev_items: ev_items_all_kw, ev_items_all: ev_all_items }
    }
}
RS"}

