fn base64_decode(s: &str) -> Option<Vec<u8>> {
    // strict-ish RFC4648 with padding, no whitespace (original likely rejects invalid chars; check length & alphabet)
    let b = s.as_bytes();
    if b.is_empty() { return Some(vec![]); }
    if b.len() % 4 != 0 { return None; }
    let val = |c: u8| -> Option<u32> { match c { b'A'..=b'Z' => Some((c - b'A') as u32), b'a'..=b'z' => Some((c - b'a' + 26) as u32), b'0'..=b'9' => Some((c - b'0' + 52) as u32), b'+' => Some(62), b'/' => Some(63), _ => None } };
    let mut out = Vec::new();
    let mut i = 0;
    while i < b.len() {
        let chunk = &b[i..i+4];
        let pad = chunk.iter().filter(|&&c| c == b'=').count();
        if pad > 0 && i + 4 != b.len() { return None; }
        if pad > 2 { return None; }
        let mut vals = [0u32; 4];
        for j in 0..4 {
            if chunk[j] == b'=' {
                if j < 2 { return None; }
                vals[j] = 0;
            } else { vals[j] = val(chunk[j])?; }
        }
        let n = (vals[0] << 18) | (vals[1] << 12) | (vals[2] << 6) | vals[3];
        out.push((n >> 16) as u8);
        if pad < 2 { out.push((n >> 8) as u8); }
        if pad < 1 { out.push(n as u8); }
        i += 4;
    }
    Some(out)
}

