fn type_name(v: &Value) -> &'static str {
    match v {
        Value::Null => "null",
        Value::Bool(_) => "boolean",
        Value::Number(_) => if num::num_is_integer(v) { "integer" } else { "number" },
        Value::String(_) => "string",
