fn matches_type(v: &Value, t: &str) -> bool {
    match t {
        "null" => v.is_null(),
        "boolean" => v.is_boolean(),
        "number" => v.is_number(),
        "integer" => v.is_number() && num::num_is_integer(v),
        "string" => v.is_string(),
        "array" => v.is_array(),
        "object" => v.is_object(),
