fn enum_message(instance: &Value, options: &Value) -> String {
    let arr = options.as_array().cloned().unwrap_or_default();
    if arr.is_empty() {
        return format!("{} is not one of ", render(instance));
    }
    if arr.len() == 1 {
        return format!("{} is not one of {}", render(instance), render(&arr[0]));
    }
    if arr.len() == 2 {
        return format!("{} is not one of {} or {}", render(instance), render(&arr[0]), render(&arr[1]));
