                self.simple_kw(eval_path, "minLength", inst_loc, loc_base, ok, err)
            }
            KwKind::MaxLength(n) => {
                let (ok, err) = if let Some(s) = instance.as_str() {
                    let len = s.chars().count();
                    if len > *n { (false, Some(VError::new("maxLength", format!("{} is longer than {} character{}", render(instance), n, if *n == 1 { "" } else { "s" })))) } else { (true, None) }
                } else { (true, None) };
                self.simple_kw(eval_path, "maxLength", inst_loc, loc_base, ok, err)
            }
            KwKind::Pattern(re) => {
                let (ok, err) = if let Some(s) = instance.as_str() {
                    if re.is_match(s) { (true, None) } else { (false, Some(VError::new("pattern", format!("{} does not match \"{}\"", render(instance), re.display)))) }
                } else { (true, None) };
                self.simple_kw(eval_path, "pattern", inst_loc, loc_base, ok, err)
            }
            KwKind::Format(fmt) => {
                let (ok, err) = if let Some(s) = instance.as_str() {
                    if formats::check_format(fmt, s) { (true, None) } else { (false, Some(VError::new("format", format!("{} is not a \"{}\"", render(instance), fmt)))) }
                } else { (true, None) };
                self.simple_kw(eval_path, "format", inst_loc, loc_base, ok, err)
            }
            KwKind::ContentD67 { media, encoding } => {
                self.eval_content_d67(media, encoding, instance, eval_path, inst_loc, loc_base)
            }
            KwKind::MinItems(n) => {
                let (ok, err) = if let Some(a) = instance.as_array() {
                    if a.len() < *n { (false, Some(VError::new("minItems", format!("{} has less than {} item{}", render(instance), n, if *n == 1 { "" } else { "s" })))) } else { (true, None) }
