                self.simple_kw(eval_path, "minItems", inst_loc, loc_base, ok, err)
            }
            KwKind::MaxItems(n) => {
                let (ok, err) = if let Some(a) = instance.as_array() {
                    if a.len() > *n { (false, Some(VError::new("maxItems", format!("{} has more than {} item{}", render(instance), n, if *n == 1 { "" } else { "s" })))) } else { (true, None) }
                } else { (true, None) };
                self.simple_kw(eval_path, "maxItems", inst_loc, loc_base, ok, err)
            }
            KwKind::UniqueItems => {
