                    let mut uniq = true;
                    'outer: for i in 0..a.len() { for j in (i+1)..a.len() { if num::values_equal(&a[i], &a[j]) { uniq = false; break 'outer; } } }
                    if uniq { (true, None) } else { (false, Some(VError::new("uniqueItems", format!("{} has non-unique elements", render(instance))))) }
                } else { (true, None) };
                self.simple_kw(eval_path, "uniqueItems", inst_loc, loc_base, ok, err)
            }
            KwKind::MinProperties(n) => {
                let (ok, err) = if let Some(o) = instance.as_object() {
                    if o.len() < *n { (false, Some(VError::new("minProperties", format!("{} has less than {} {}", render(instance), n, if *n == 1 { "property" } else { "properties" })))) } else { (true, None) }
                } else { (true, None) };
                self.simple_kw(eval_path, "minProperties", inst_loc, loc_base, ok, err)
            }
            KwKind::MaxProperties(n) => {
                let (ok, err) = if let Some(o) = instance.as_object() {
                    if o.len() > *n { (false, Some(VError::new("maxProperties", format!("{} has more than {} {}", render(instance), n, if *n == 1 { "property" } else { "properties" })))) } else { (true, None) }
                } else { (true, None) };
                self.simple_kw(eval_path, "maxProperties", inst_loc, loc_base, ok, err)
            }
            KwKind::Required(req) => {
                let mut u = self.kw_unit(true, eval_path, "required", inst_loc, loc_base);
