                out.valid = errs.is_empty();
                out.units = vec![u];
                out.text_errors = errs;
                out
            }
            KwKind::DependentRequired(entries) => {
                self.eval_dependent_required(entries, "dependentRequired", instance, eval_path, inst_loc, loc_base)
            }
            KwKind::Dependencies(entries) => {
                self.eval_dependencies(node, entries, instance, eval_path, inst_loc, loc_base, ctx)
            }
            KwKind::ObjectProps(op) => {
                self.eval_object_props(node, op, instance, eval_path, inst_loc, loc_base, ctx)
            }
            KwKind::PropertyNames(child) => {
                self.eval_property_names(*child, instance, eval_path, inst_loc, loc_base, ctx)
            }
            KwKind::DependentSchemas(entries) => {
                self.eval_dependent_schemas(entries, instance, eval_path, inst_loc, loc_base, ctx)
            }
            KwKind::ItemsSingle { child, has_prefix, prefix_len, legacy_tuple } => {
                let _ = legacy_tuple;
                self.eval_items_single(*child, *has_prefix, *prefix_len, instance, eval_path, inst_loc, loc_base, ctx)
            }
            KwKind::ItemsBoolFalse { .. } => unreachable!(),
