            }
            KwKind::Contains { child, min, max } => {
                self.eval_contains(*child, *min, *max, instance, eval_path, inst_loc, loc_base, ctx)
            }
            KwKind::AllOf(children) => self.eval_all_of(children, instance, eval_path, inst_loc, loc_base, ctx),
            KwKind::AnyOf(children) => self.eval_any_one_of(children, instance, eval_path, inst_loc, loc_base, ctx, false),
            KwKind::OneOf(children) => self.eval_any_one_of(children, instance, eval_path, inst_loc, loc_base, ctx, true),
            KwKind::Not(child, raw) => {
                let cnode = self.node_rc(*child);
                let outc = self.eval_node(*child, instance, &join_path_raw(eval_path, "not"), inst_loc, &cnode.abs_loc.clone(), &cnode.abs_loc.clone(), ctx);
                let ok = !outc.unit.valid;
                let mut u = self.kw_unit(ok, eval_path, "not", inst_loc, loc_base);
                let mut out = KwOutcome::from_unit_placeholder();
                out.valid = ok;
                if !ok {
                    let e = VError::new("not", format!("{} is not allowed for {}", render(raw), render(instance)));
                    u.errors.push(e.clone());
                    out.text_errors = vec![e];
                }
                out.units = vec![u];
                out
            }
            KwKind::IfThenElse { if_, then_, else_ } => {
                self.eval_if(*if_, *then_, *else_, instance, eval_path, inst_loc, loc_base, ctx)
            }
            KwKind::Ref(t) => self.eval_ref(node, node_idx, t, RefKind::Static, instance, eval_path, inst_loc, loc_base, ctx),
            KwKind::DynamicRef(t) => self.eval_ref(node, node_idx, t, RefKind::Dynamic, instance, eval_path, inst_loc, loc_base, ctx),
            KwKind::RecursiveRef(t) => self.eval_ref(node, node_idx, t, RefKind::Recursive, instance, eval_path, inst_loc, loc_base, ctx),
            KwKind::UnevaluatedItems(_) | KwKind::UnevaluatedProperties(_) => unreachable!(),
        }
    }

    fn schema_keyword_value(&self, node: &Node, kw: &str) -> Option<Value> {
        let reg = self.registry.borrow();
        let doc = reg.docs.get(&node.doc_uri)?;
        let v = value_at(&doc.value, &node.ptr)?;
        v.as_object()?.get(kw).cloned()
    }

    fn eval_content_d67(&self, media: &Option<String>, encoding: &Option<String>, instance: &Value, eval_path: &str, inst_loc: &str, loc_base: &str) -> KwOutcome {
        let mut u = self.kw_unit(true, eval_path, "contentMediaType", inst_loc, loc_base);
        let mut out = KwOutcome::from_unit_placeholder();
        out.valid = true;
        if let Some(s) = instance.as_str() {
            let mut decoded: Option<Vec<u8>> = None;
            if let Some(enc) = encoding {
                if enc == "base64" {
                    match base64_decode(s) {
                        Some(b) => decoded = Some(b),
                        None => {
                            let e = VError::new("contentEncoding", format!("{} is not compliant with \"base64\" content encoding", render(instance)));
                            u.valid = false; u.errors.push(e.clone()); out.valid = false; out.text_errors = vec![e]; out.units = vec![u]; return out;
                        }
                    }
                } else if enc == "quoted-printable" || enc == "binary" {
                    // approximate: accept
                    decoded = Some(s.as_bytes().to_vec());
                } else {
                    decoded = Some(s.as_bytes().to_vec());
                }
            }
            if let Some(m) = media {
                if m == "application/json" {
                    let text: String = match &decoded {
                        Some(b) => String::from_utf8_lossy(b).to_string(),
                        None => s.to_string(),
                    };
                    if serde_json::from_str::<Value>(&text).is_err() {
                        let e = VError::new("contentMediaType", format!("{} is not compliant with \"application/json\" media type", render(instance)));
                        u.valid = false; u.errors.push(e.clone()); out.valid = false; out.text_errors = vec![e]; out.units = vec![u]; return out;
                    }
                }
            }
        }
        out.units = vec![u];
        out
    }
}

fn base64_decode(s: &str) -> Option<Vec<u8>> {
    // strict-ish RFC4648 with padding, no whitespace (original likely rejects invalid chars; check length & alphabet)
    let b = s.as_bytes();
    if b.is_empty() { return Some(vec![]); }
    if b.len() % 4 != 0 { return None; }
    let val = |c: u8| -> Option<u32> { match c { b'A'..=b'Z' => Some((c - b'A') as u32), b'a'..=b'z' => Some((c - b'a' + 26) as u32), b'0'..=b'9' => Some((c - b'0' + 52) as u32), b'+' => Some(62), b'/' => Some(63), _ => None } };
    let mut out = Vec::new();
    let mut i = 0;
    while i < b.len() {
        let chunk = &b[i..i+4];
        let pad = chunk.iter().filter(|&&c| c == b'=').count();
        if pad > 0 && i + 4 != b.len() { return None; }
        if pad > 2 { return None; }
        let mut vals = [0u32; 4];
        for j in 0..4 {
            if chunk[j] == b'=' {
                if j < 2 { return None; }
                vals[j] = 0;
            } else { vals[j] = val(chunk[j])?; }
        }
        let n = (vals[0] << 18) | (vals[1] << 12) | (vals[2] << 6) | vals[3];
        out.push((n >> 16) as u8);
        if pad < 2 { out.push((n >> 8) as u8); }
        if pad < 1 { out.push(n as u8); }
        i += 4;
    }
    Some(out)
}

impl KwOutcome {
    fn from_unit_placeholder() -> Self { KwOutcome { valid: true, units: Vec::new(), text_errors: Vec::new(), ev_props: HashSet::new(), ev_items: HashSet::new(), ev_items_all: false } }
}
