{"command":"cat >> src/validator.rs <<'RS'

impl Validator {
    fn eval_child_node(&self, child: usize, instance: &Value, eval_path: String, inst_loc: String, ctx: &mut Ctx) -> Outcome {
        let cnode = self.node_rc(child);
        self.eval_node(child, instance, &eval_path, &inst_loc, &cnode.abs_loc.clone(), &cnode.abs_loc.clone(), ctx)
    }

    fn eval_object_props(&self, _node: &Node, op: &ObjectProps, instance: &Value, eval_path: &str, inst_loc: &str, loc_base: &str, ctx: &mut Ctx) -> KwOutcome {
        let mut out = KwOutcome::from_unit_placeholder();
        let obj = match instance.as_object() {
            None => {
                // units still produced
                match &op.additional {
                    Some(Additional::BoolTrue) | None => {
                        if op.has_properties_kw {
                            let mut u = self.kw_unit(true, eval_path, "properties", inst_loc, loc_base);
                            u.annotations = Some(Value::Array(vec![]));
                            out.units.push(u);
                        }
                        if op.has_pattern_kw {
                            let mut u = self.kw_unit(true, eval_path, "patternProperties", inst_loc, loc_base);
                            u.annotations = Some(Value::Array(vec![]));
                            out.units.push(u);
                        }
                        if !op.has_properties_kw && !op.has_pattern_kw {
                            if let Some(Additional::BoolTrue) = &op.additional {
                                // additionalProperties:true alone on non-object: in the original it still appears? approximate no unit? It produced /properties path earlier for items+properties on 42 schema had properties.
                                // produce additional unit
                                out.units.push(self.kw_unit(true, eval_path, "additionalProperties", inst_loc, loc_base));
                            }
                        }
                    }
                    Some(_) => {
                        out.units.push(self.kw_unit(true, eval_path, "additionalProperties", inst_loc, loc_base));
                    }
                }
                out.valid = true;
                return out;
            }
            Some(o) => o,
        };
        // Evaluate per-key children
        struct KeyRes {
            key: String,
            prop: Option<Outcome>,
            patterns: Vec<(String, Outcome)>, // pattern string, outcome
            additional: Option<Outcome>,
            is_additional: bool,
        }
        let mut results: Vec<KeyRes> = Vec::new();
        let mut prop_matched: Vec<String> = Vec::new();
        let mut pattern_matched: Vec<String> = Vec::new();
        let mut additional_keys: Vec<String> = Vec::new();
        for (key, val) in obj.iter() {
            let iloc = join_path(inst_loc, key);
            let mut kr = KeyRes { key: key.clone(), prop: None, patterns: Vec::new(), additional: None, is_additional: false };
            if let Some((_, child)) = op.properties.iter().find(|(pk, _)| pk == key) {
                let o = self.eval_child_node(*child, val, format!("{}/properties/{}", eval_path, uri::escape_pointer_token(key)), iloc.clone(), ctx);
                kr.prop = Some(o);
                prop_matched.push(key.clone());
            }
            let mut any_pattern = false;
            for (re, pat, child) in &op.pattern_properties {
                if re.is_match(key) {
                    any_pattern = true;
                    let o = self.eval_child_node(*child, val, format!("{}/patternProperties/{}", eval_path, uri::escape_pointer_token(pat)), iloc.clone(), ctx);
                    kr.patterns.push((pat.clone(), o));
                }
            }
            if any_pattern { pattern_matched.push(key.clone()); }
            kr.is_additional = kr.prop.is_none() && !any_pattern;
            if kr.is_additional {
                additional_keys.push(key.clone());
                if let Some(Additional::Schema(child)) = &op.additional {
                    let o = self.eval_child_node(*child, val, join_path_raw(eval_path, "additionalProperties"), iloc.clone(), ctx);
                    kr.additional = Some(o);
                }
            }
            results.push(kr);
        }
        let prop_valid = results.iter().all(|kr| kr.prop.as_ref().map(|o| o.unit.valid).unwrap_or(true));
        let pattern_valid = results.iter().all(|kr| kr.patterns.iter().all(|(_, o)| o.unit.valid));
        let add_valid = results.iter().all(|kr| kr.additional.as_ref().map(|o| o.unit.valid).unwrap_or(true));

        match &op.additional {
            None | Some(Additional::BoolTrue) => {
                let mut valid = true;
                if op.has_properties_kw {
                    let mut u = self.kw_unit(prop_valid, eval_path, "properties", inst_loc, loc_base);
                    let ann = Value::Array(prop_matched.iter().map(|s| Value::String(s.clone())).collect());
                    if prop_valid { u.annotations = Some(ann); } else { u.dropped = Some(ann); }
                    for kr in &results { if let Some(o) = &kr.prop { u.children.push(clone_unit(&o.unit)); out.text_errors.extend(o.text_errors.clone()); } }
                    if !prop_valid { valid = false; }
                    out.units.push(u);
                    if prop_valid { for k in &prop_matched { out.ev_props.insert(k.clone()); } }
                } else {
                    for kr in &results { if let Some(o) = &kr.prop { out.text_errors.extend(o.text_errors.clone()); if !o.unit.valid { valid = false; } } }
                }
                if op.has_pattern_kw {
                    let mut u = self.kw_unit(pattern_valid, eval_path, "patternProperties", inst_loc, loc_base);
                    let ann = Value::Array(pattern_matched.iter().map(|s| Value::String(s.clone())).collect());
                    if pattern_valid { u.annotations = Some(ann); } else { u.dropped = Some(ann); }
                    for kr in &results { for (_, o) in &kr.patterns { u.children.push(clone_unit(&o.unit)); } }
                    for kr in &results { for (_, o) in &kr.patterns { out.text_errors.extend(o.text_errors.clone()); } }
                    if !pattern_valid { valid = false; }
                    out.units.push(u);
                    if pattern_valid { for k in &pattern_matched { out.ev_props.insert(k.clone()); } }
                }
                if let Some(Additional::BoolTrue) = &op.additional {
                    for k in &additional_keys { out.ev_props.insert(k.clone()); }
                }
                out.valid = valid;
                out
            }
            Some(Additional::BoolFalse) | Some(Additional::Schema(_)) => {
                let is_false = matches!(&op.additional, Some(Additional::BoolFalse));
                // Special case: additionalProperties:false with neither properties nor patternProperties
                if is_false && !op.has_properties_kw && !op.has_pattern_kw {
                    let mut u = self.kw_unit(true, eval_path, "additionalProperties", inst_loc, loc_base);
                    if let Some(first_key) = additional_keys.first() {
                        let first_val = &obj[first_key];
                        let e = VError::new("falseSchema", format!("False schema does not allow {}", render(first_val)));
                        u.valid = false;
                        u.errors.push(e.clone());
                        out.valid = false;
                        out.text_errors = vec![e];
                    } else {
                        out.valid = true;
                    }
                    out.units = vec![u];
                    return out;
                }
                // Combined unit
                let mut children: Vec<Unit> = Vec::new();
                let mut child_text: Vec<VError> = Vec::new();
                for kr in &results {
                    if let Some(o) = &kr.prop { children.push(clone_unit(&o.unit)); child_text.extend(o.text_errors.clone()); }
                    for (_, o) in &kr.patterns { children.push(clone_unit(&o.unit)); child_text.extend(o.text_errors.clone()); }
                    if let Some(o) = &kr.additional { children.push(clone_unit(&o.unit)); child_text.extend(o.text_errors.clone()); }
                }
                // trailing patternProperties pseudo-unit when pattern present but properties absent
                if op.has_pattern_kw && !op.has_properties_kw {
                    let mut pu = self.kw_unit(pattern_valid, eval_path, "patternProperties", inst_loc, loc_base);
                    let ann = Value::Array(pattern_matched.iter().map(|s| Value::String(s.clone())).collect());
                    if pattern_valid { pu.annotations = Some(ann); } else { pu.dropped = Some(ann); }
                    children.push(pu);
                }
                let add_false_err = is_false && !additional_keys.is_empty();
                let merged_missing = op.merged_required.as_ref().map(|r| !obj.contains_key(r)).unwrap_or(false);
                let valid = prop_valid && pattern_valid && add_valid && !add_false_err && !merged_missing;
                let mut u = self.kw_unit(valid, eval_path, "additionalProperties", inst_loc, loc_base);
                u.children = children;
                let mut parent_text: Vec<VError> = Vec::new();
                if add_false_err {
                    let e = VError::new("additionalProperties", format!("Additional properties are not allowed {}", unexpected_list(&additional_keys, true)));
                    u.errors.push(e.clone()); parent_text.push(e);
                }
                if merged_missing {
                    let r = op.merged_required.as_ref().unwrap();
                    let e = VError::new("required", format!("\"{}\" is a required property", r));
                    u.errors.push(e.clone()); parent_text.push(e);
                }
                if !is_false {
                    let ann = Value::Array(additional_keys.iter().map(|s| Value::String(s.clone())).collect());
                    if valid { u.annotations = Some(ann); } else { u.dropped = Some(ann); }
                }
                out.valid = valid;
                out.units = vec![u];
                // text order: child errors then parent errors (additional, required)
                out.text_errors = child_text;
                out.text_errors.extend(parent_text);
                if prop_valid { for k in &prop_matched { out.ev_props.insert(k.clone()); } }
                if pattern_valid { for k in &pattern_matched { out.ev_props.insert(k.clone()); } }
                if !is_false && add_valid { for k in &additional_keys { out.ev_props.insert(k.clone()); } }
                if is_false && additional_keys.is_empty() {
                    // all keys are either prop/pattern matched (already) - nothing else
                }
                out
            }
        }
    }

    fn eval_dependent_required(&self, entries: &[(String, Vec<String>)], kwname: &str, instance: &Value, eval_path: &str, inst_loc: &str, loc_base: &str) -> KwOutcome {
        // Structure observed: parent unit /dependentRequired (valid overall), then for each triggered entry:
        // a child unit also /dependentRequired (no errors), then /dependentRequired/0 with required errors.
        let mut parent = self.kw_unit(true, eval_path, kwname, inst_loc, loc_base);
        let mut out = KwOutcome::from_unit_placeholder();
        let mut valid = true;
        if let Some(obj) = instance.as_object() {
            for (key, reqs) in entries {
                if obj.contains_key(key) {
                    let mut errs = Vec::new();
                    for r in reqs { if !obj.contains_key(r) { errs.push(VError::new("required", format!("\"{}\" is a required property", r))); } }
                    let entry_valid = errs.is_empty();
                    if !entry_valid { valid = false; }
                    let wrapper = self.kw_unit(entry_valid, eval_path, kwname, inst_loc, loc_base);
                    let mut leaf = Unit::new(entry_valid, format!("{}/{}/0", eval_path, kwname), inst_loc.to_string(), format!("{}/{}/0", loc_base, kwname));
                    leaf.errors = errs.clone();
                    // hierarchical nesting guess: leaf is child of wrapper? In list flatten they appear consecutively. For hierarchical, original likely parent>wrapper>leaf or parent children [wrapper-with-leaf]. We'll make wrapper contain leaf.
                    let mut wrapper = wrapper;
                    wrapper.children = vec![leaf];
                    parent.children.push(wrapper);
                    out.text_errors.extend(errs);
                }
            }
        }
        parent.valid = valid;
        out.valid = valid;
        out.units = vec![parent];
        out
    }

    fn eval_dependencies(&self, _node: &Node, entries: &[(String, DepVal)], instance: &Value, eval_path: &str, inst_loc: &str, loc_base: &str, ctx: &mut Ctx) -> KwOutcome {
        // Similar structure to dependentRequired for array form; schema form evaluates subschema with eval path /dependencies/{key}
        let mut parent = self.kw_unit(true, eval_path, "dependencies", inst_loc, loc_base);
        let mut out = KwOutcome::from_unit_placeholder();
        let mut valid = true;
        if let Some(obj) = instance.as_object() {
            for (key, dv) in entries {
                if obj.contains_key(key) {
                    match dv {
                        DepVal::Required(reqs) => {
                            let mut errs = Vec::new();
                            for r in reqs { if !obj.contains_key(r) { errs.push(VError::new("required", format!("\"{}\" is a required property", r))); } }
                            let ev = errs.is_empty();
                            if !ev { valid = false; }
                            let mut wrapper = self.kw_unit(ev, eval_path, "dependencies", inst_loc, loc_base);
                            let mut leaf = Unit::new(ev, format!("{}/dependencies/0", eval_path), inst_loc.to_string(), format!("{}/dependencies/0", loc_base));
                            leaf.errors = errs.clone();
                            wrapper.children = vec![leaf];
                            parent.children.push(wrapper);
                            out.text_errors.extend(errs);
                        }
                        DepVal::Schema(child) => {
                            let o = self.eval_child_node(*child, instance, format!("{}/dependencies/{}", eval_path, uri::escape_pointer_token(key)), inst_loc.to_string(), ctx);
                            if !o.unit.valid { valid = false; }
                            if o.unit.valid { out.ev_props.extend(o.ev_props.iter().cloned()); out.ev_items.extend(o.ev_items.iter().cloned()); if o.ev_items_all { out.ev_items_all = true; } }
                            out.text_errors.extend(o.text_errors.clone());
                            parent.children.push(o.unit);
                        }
                    }
                }
            }
        }
        parent.valid = valid;
        out.valid = valid;
        out.units = vec![parent];
        out
    }

    fn eval_property_names(&self, child: usize, instance: &Value, eval_path: &str, inst_loc: &str, loc_base: &str, ctx: &mut Ctx) -> KwOutcome {
        let mut parent = self.kw_unit(true, eval_path, "propertyNames", inst_loc, loc_base);
        let mut out = KwOutcome::from_unit_placeholder();
        let mut valid = true;
        if let Some(obj) = instance.as_object() {
            let cnode = self.node_rc(child);
            for key in obj.keys() {
                // propertyNames False special: error instance is whole object, and text only one error?
                // General eval against key string; false node message uses the string? Original: False schema does not allow {"a":1}
                // Handle bool false child specially below.
                if cnode.is_bool == Some(false) {
                    valid = false;
                    // create a child unit mimicking eval of false against ... original list for propertyNames:false?
                    let mut cu = Unit::new(false, join_path_raw(eval_path, "propertyNames"), inst_loc.to_string(), cnode.abs_loc.clone());
                    let e = VError::new("falseSchema", format!("False schema does not allow {}", render(instance)));
                    cu.errors.push(e.clone());
                    parent.children.push(cu);
                    out.text_errors.push(e);
                    break;
                }
                let name_val = Value::String(key.clone());
                let o = self.eval_child_node(child, &name_val, join_path_raw(eval_path, "propertyNames"), inst_loc.to_string(), ctx);
                if !o.unit.valid { valid = false; }
                out.text_errors.extend(o.text_errors.clone());
                parent.children.push(o.unit);
            }
        }
        parent.valid = valid;
        out.valid = valid;
        out.units = vec![parent];
        out
    }

    fn eval_dependent_schemas(&self, entries: &[(String, usize)], instance: &Value, eval_path: &str, inst_loc: &str, loc_base: &str, ctx: &mut Ctx) -> KwOutcome {
        let mut parent = self.kw_unit(true, eval_path, "dependentSchemas", inst_loc, loc_base);
        let mut out = KwOutcome::from_unit_placeholder();
        let mut valid = true;
        if let Some(obj) = instance.as_object() {
            for (key, child) in entries {
                if obj.contains_key(key) {
                    let o = self.eval_child_node(*child, instance, format!("{}/dependentSchemas/{}", eval_path, uri::escape_pointer_token(key)), inst_loc.to_string(), ctx);
                    if !o.unit.valid { valid = false; }
                    if o.unit.valid { out.ev_props.extend(o.ev_props.iter().cloned()); out.ev_items.extend(o.ev_items.iter().cloned()); if o.ev_items_all { out.ev_items_all = true; } }
                    out.text_errors.extend(o.text_errors.clone());
                    parent.children.push(o.unit);
                }
            }
        }
        parent.valid = valid;
        out.valid = valid;
        out.units = vec![parent];
        out
    }
}

pub fn clone_unit(u: &Unit) -> Unit { u.clone() }
RS"}

