    fn eval_dependent_required(&self, entries: &[(String, Vec<String>)], kwname: &str, instance: &Value, eval_path: &str, inst_loc: &str, loc_base: &str) -> KwOutcome {
        // Structure observed: parent unit /dependentRequired (valid overall), then for each triggered entry:
        // a child unit also /dependentRequired (no errors), then /dependentRequired/0 with required errors.
        let mut parent = self.kw_unit(true, eval_path, kwname, inst_loc, loc_base);
        let mut out = KwOutcome::from_unit_placeholder();
        let mut valid = true;
        if let Some(obj) = instance.as_object() {
            for (key, reqs) in entries {
                if obj.contains_key(key) {
                    let mut errs = Vec::new();
                    for r in reqs { if !obj.contains_key(r) { errs.push(VError::new("required", format!("\"{}\" is a required property", r))); } }
                    let entry_valid = errs.is_empty();
                    if !entry_valid { valid = false; }
                    let wrapper = self.kw_unit(entry_valid, eval_path, kwname, inst_loc, loc_base);
                    let mut leaf = Unit::new(entry_valid, format!("{}/{}/0", eval_path, kwname), inst_loc.to_string(), format!("{}/{}/0", loc_base, kwname));
                    leaf.errors = errs.clone();
                    // hierarchical nesting guess: leaf is child of wrapper? In list flatten they appear consecutively. For hierarchical, original likely parent>wrapper>leaf or parent children [wrapper-with-leaf]. We'll make wrapper contain leaf.
                    let mut wrapper = wrapper;
                    wrapper.children = vec![leaf];
                    parent.children.push(wrapper);
                    out.text_errors.extend(errs);
                }
            }
        }
        parent.valid = valid;
        out.valid = valid;
        out.units = vec![parent];
        out
    }

    fn eval_dependencies(&self, _node: &Node, entries: &[(String, DepVal)], instance: &Value, eval_path: &str, inst_loc: &str, loc_base: &str, ctx: &mut Ctx) -> KwOutcome {
        // Similar structure to dependentRequired for array form; schema form evaluates subschema with eval path /dependencies/{key}
        let mut parent = self.kw_unit(true, eval_path, "dependencies", inst_loc, loc_base);
        let mut out = KwOutcome::from_unit_placeholder();
        let mut valid = true;
        if let Some(obj) = instance.as_object() {
            for (key, dv) in entries {
                if obj.contains_key(key) {
                    match dv {
                        DepVal::Required(reqs) => {
                            let mut errs = Vec::new();
                            for r in reqs { if !obj.contains_key(r) { errs.push(VError::new("required", format!("\"{}\" is a required property", r))); } }
                            let ev = errs.is_empty();
                            if !ev { valid = false; }
                            let mut wrapper = self.kw_unit(ev, eval_path, "dependencies", inst_loc, loc_base);
                            let mut leaf = Unit::new(ev, format!("{}/dependencies/0", eval_path), inst_loc.to_string(), format!("{}/dependencies/0", loc_base));
                            leaf.errors = errs.clone();
                            wrapper.children = vec![leaf];
                            parent.children.push(wrapper);
                            out.text_errors.extend(errs);
                        }
                        DepVal::Schema(child) => {
                            let o = self.eval_child_node(*child, instance, format!("{}/dependencies/{}", eval_path, uri::escape_pointer_token(key)), inst_loc.to_string(), ctx);
                            if !o.unit.valid { valid = false; }
                            if o.unit.valid { out.ev_props.extend(o.ev_props.iter().cloned()); out.ev_items.extend(o.ev_items.iter().cloned()); if o.ev_items_all { out.ev_items_all = true; } }
                            out.text_errors.extend(o.text_errors.clone());
                            parent.children.push(o.unit);
                        }
                    }
                }
            }
        }
        parent.valid = valid;
        out.valid = valid;
        out.units = vec![parent];
        out
    }

    fn eval_property_names(&self, child: usize, instance: &Value, eval_path: &str, inst_loc: &str, loc_base: &str, ctx: &mut Ctx) -> KwOutcome {
        let mut parent = self.kw_unit(true, eval_path, "propertyNames", inst_loc, loc_base);
        let mut out = KwOutcome::from_unit_placeholder();
        let mut valid = true;
        if let Some(obj) = instance.as_object() {
            let cnode = self.node_rc(child);
            for key in obj.keys() {
