    fn eval_ref(&self, node: &Node, _node_idx: usize, target: &RefTarget, kind: RefKind, instance: &Value, eval_path: &str, inst_loc: &str, _loc_base: &str, ctx: &mut Ctx) -> KwOutcome {
        let mut out = KwOutcome::from_unit_placeholder();
        out.valid = true;
        let kwname = match kind { RefKind::Static => "$ref", RefKind::Dynamic => "$dynamicRef", RefKind::Recursive => "$recursiveRef" };
        let tnode = self.node_rc(target.node);
        // direct self static ref: skip entirely
        if kind == RefKind::Static && tnode.doc_uri == node.doc_uri && tnode.ptr == node.ptr {
            return out;
        }
        // Resolve dynamic/recursive target if applicable
        let (eff_node, eff_unit_loc, eff_child_base) = self.effective_ref_target(node, target, kind, ctx);
        let evalp = join_path_raw(eval_path, kwname);
        // push dynamic scope: target resource
        let enode = self.node_rc(eff_node);
        ctx.dyn_scope.push(enode.base_uri.clone());
        let o = self.eval_node(eff_node, instance, &evalp, inst_loc, &eff_unit_loc, &eff_child_base, ctx);
        ctx.dyn_scope.pop();
        out.valid = o.unit.valid;
        out.text_errors = o.text_errors.clone();
        if o.unit.valid {
            out.ev_props = o.ev_props.clone();
            out.ev_items = o.ev_items.clone();
            out.ev_items_all = o.ev_items_all;
        }
        out.units = vec![o.unit];
        out
    }

    fn effective_ref_target(&self, node: &Node, target: &RefTarget, kind: RefKind, ctx: &Ctx) -> (usize, String, String) {
        let tnode = self.node_rc(target.node);
        // unit loc: referrer base + # + pointer fragment (if pointer)
        let unit_loc = match &target.fragment {
            Some(f) if f.starts_with('/') => format!("{}#{}", node.base_uri, f),
            _ => format!("{}#", node.base_uri),
        };
        // child base: anchor -> resource uri + # ; else target canonical abs_loc
        let child_base = match &target.fragment {
            Some(f) if !f.is_empty() && !f.starts_with('/') => format!("{}#", target.resource_uri),
            _ => tnode.abs_loc.clone(),
        };
        if kind == RefKind::Static {
            return (target.node, unit_loc, child_base);
        }
        // Dynamic/recursive: only special if statically resolved target is a dynamic/recursive anchor
        let anchor_name = match kind {
            RefKind::Dynamic => target.fragment.clone().unwrap_or_default(),
            RefKind::Recursive => "".to_string(),
            _ => "".to_string(),
        };
        if !target.is_dynamic_anchor {
            return (target.node, unit_loc, child_base);
        }
        // Scan dynamic scope from outermost to innermost for a resource with same dynamic anchor.
        // We need registry lookup of each resource in scope.
        let reg = self.registry.borrow();
        for res_uri in ctx.dyn_scope.iter() {
            if let Some((docuri, _)) = reg.by_resource.get(res_uri) {
                if let Some(doc) = reg.docs.get(docuri) {
                    let key = (res_uri.clone(), anchor_name.clone());
                    if let Some(ptr) = doc.dyn_anchors.get(&key) {
                        // Compile (or fetch) node for this ptr with reset dialect - already compiled likely as a node? Search node_map by constructing key likely misses dialect; use compile_node
                        // Need drop reg borrow before compile - handle by returning marker
                        let docuri_c = doc.uri.clone();
                        let ptr_c = ptr.clone();
                        drop(reg);
                        let dialect = Dialect::standard(self.root_dialect.draft);
                        if let Ok(nidx) = self.compile_node(&docuri_c, &ptr_c, dialect) {
                            let nn = self.node_rc(nidx);
                            return (nidx, unit_loc, nn.abs_loc.clone());
                        }
                        return (target.node, unit_loc, child_base);
                    }
                }
            }
        }
        (target.node, unit_loc, child_base)
    }

    fn eval_unevaluated_items(&self, _node: &Node, child: usize, instance: &Value, eval_path: &str, inst_loc: &str, loc_base: &str, ctx: &mut Ctx, ev_items: &HashSet<usize>, ev_all: bool) -> KwOutcome {
        let mut out = KwOutcome::from_unit_placeholder();
        let arr = match instance.as_array() {
            None => { out.valid = true; out.units = vec![self.kw_unit(true, eval_path, "unevaluatedItems", inst_loc, loc_base)]; return out; }
            Some(a) => a,
        };
        let cnode = self.node_rc(child);
        let unev: Vec<usize> = if ev_all { Vec::new() } else { (0..arr.len()).filter(|i| !ev_items.contains(i)).collect() };
        if cnode.is_bool == Some(false) {
            if unev.is_empty() {
                out.valid = true;
                out.units = vec![self.kw_unit(true, eval_path, "unevaluatedItems", inst_loc, loc_base)];
                out.ev_items_all = true;
                return out;
            }
            let vals: Vec<String> = unev.iter().map(|&i| render(&arr[i])).collect();
            let e = VError::new("unevaluatedItems", format!("Unevaluated items are not allowed {}", unexpected_list(&vals, true)));
            let mut u = self.kw_unit(false, eval_path, "unevaluatedItems", inst_loc, loc_base);
            u.errors.push(e.clone());
            // children: false node units per unevaluated item
            for &i in &unev {
                let o = self.eval_child_node(child, &arr[i], join_path_raw(eval_path, "unevaluatedItems"), join_path(inst_loc, &i.to_string()), ctx);
                u.children.push(o.unit);
            }
            out.valid = false;
            out.text_errors = vec![e];
            out.units = vec![u];
            return out;
        }
        // schema form
        let mut parent = self.kw_unit(true, eval_path, "unevaluatedItems", inst_loc, loc_base);
        let mut valid = true;
        for &i in &unev {
            let o = self.eval_child_node(child, &arr[i], join_path_raw(eval_path, "unevaluatedItems"), join_path(inst_loc, &i.to_string()), ctx);
            if !o.unit.valid { valid = false; }
            out.text_errors.extend(o.text_errors.clone());
            parent.children.push(o.unit);
            out.ev_items.insert(i);
        }
        parent.valid = valid;
        if valid { out.ev_items_all = true; } else { out.ev_items.clear(); }
        out.valid = valid;
        out.units = vec![parent];
        out
    }

    fn eval_unevaluated_props(&self, _node: &Node, child: usize, instance: &Value, eval_path: &str, inst_loc: &str, loc_base: &str, ctx: &mut Ctx, ev_props: &HashSet<String>) -> KwOutcome {
        let mut out = KwOutcome::from_unit_placeholder();
        let obj = match instance.as_object() {
            None => { out.valid = true; out.units = vec![self.kw_unit(true, eval_path, "unevaluatedProperties", inst_loc, loc_base)]; return out; }
            Some(o) => o,
        };
        let cnode = self.node_rc(child);
        let unev: Vec<String> = obj.keys().filter(|k| !ev_props.contains(*k)).cloned().collect();
        if cnode.is_bool == Some(false) {
            if unev.is_empty() {
                out.valid = true;
                out.units = vec![self.kw_unit(true, eval_path, "unevaluatedProperties", inst_loc, loc_base)];
                for k in obj.keys() { out.ev_props.insert(k.clone()); }
                return out;
            }
            let e = VError::new("unevaluatedProperties", format!("Unevaluated properties are not allowed {}", unexpected_list(&unev, true)));
            let mut u = self.kw_unit(false, eval_path, "unevaluatedProperties", inst_loc, loc_base);
            u.errors.push(e.clone());
            for k in &unev {
                let o = self.eval_child_node(child, &obj[k], join_path_raw(eval_path, "unevaluatedProperties"), join_path(inst_loc, k), ctx);
                u.children.push(o.unit);
            }
            out.valid = false;
            out.text_errors = vec![e];
            out.units = vec![u];
            return out;
        }
        let mut parent = self.kw_unit(true, eval_path, "unevaluatedProperties", inst_loc, loc_base);
        let mut valid = true;
        for k in &unev {
            let o = self.eval_child_node(child, &obj[k], join_path_raw(eval_path, "unevaluatedProperties"), join_path(inst_loc, k), ctx);
            if !o.unit.valid { valid = false; }
            out.text_errors.extend(o.text_errors.clone());
            parent.children.push(o.unit);
            out.ev_props.insert(k.clone());
        }
        parent.valid = valid;
        if !valid { out.ev_props.clear(); }
        out.valid = valid;
        out.units = vec![parent];
        out
    }
}

fn transform_index_message(e: &VError, item: &Value, index: usize) -> String {
    // If message starts with rendered item followed by a space, insert " at index {i}" after it.
    let r = render(item);
    if let Some(rest) = e.output_msg.strip_prefix(&r) {
        if rest.starts_with(' ') {
            return format!("{} at index {}{}", r, index, rest);
        }
    }
    e.output_msg.clone()
}
