fn normalize_port(port_colon: &str, scheme: &str) -> String {
    // port_colon like :8080
    if port_colon.len() <= 1 { return port_colon.to_string(); }
    if let Ok(p) = port_colon[1..].parse::<u32>() {
        if (scheme == "http" && p == 80) || (scheme == "https" && p == 443) { return String::new(); }
        return format!(":{}", p);
    }
    port_colon.to_string()
}

fn host_of(url: &str) -> String {
    let p = crate::uri::parse_uri_reference(url);
    let auth = p.authority.unwrap_or_default();
    let hp = match auth.rfind('@') { Some(i) => &auth[i+1..], None => &auth };
    if hp.starts_with('[') {
        if let Some(c) = hp.find(']') { return hp[1..c].to_string(); }
    }
    hp.split(':').next().unwrap_or("").to_string()
}

fn proxy_for(url: &str) -> Option<String> {
    let scheme = crate::uri::scheme_of(url).unwrap_or_default().to_lowercase();
    let host = host_of(url).to_lowercase();
    // NO_PROXY
    let no_proxy = std::env::var("NO_PROXY").ok().or_else(|| std::env::var("no_proxy").ok()).unwrap_or_default();
    for part in no_proxy.split(',') {
        let part = part.trim().to_lowercase();
        if part.is_empty() { continue; }
        if part == "*" { return None; }
        let part = part.strip_prefix('.').unwrap_or(&part);
        if host == part || host.ends_with(&format!(".{}", part)) { return None; }
    }
    let get = |names: &[&str]| -> Option<String> {
        for n in names { if let Ok(v) = std::env::var(n) { if !v.is_empty() { return Some(v); } } }
        None
    };
    if scheme == "http" {
        get(&["HTTP_PROXY", "http_proxy", "ALL_PROXY", "all_proxy"])
    } else {
        get(&["HTTPS_PROXY", "https_proxy", "ALL_PROXY", "all_proxy"])
    }
}

pub fn fetch_json(url: &str, cfg: &HttpConfig) -> Result<Value, String> {
    // Uses curl as the HTTP transport (TLS, redirects, proxies).
    let normalized = normalize_url_for_error(url);
    // Invalid port etc: reqwest gives "builder error" for URLs it cannot build a request for (e.g. port 99999)
    if let Some(auth) = crate::uri::parse_uri_reference(url).authority {
        let hp = match auth.rfind('@') { Some(i) => &auth[i+1..], None => &auth };
        if !hp.starts_with('[') {
            if let Some(ci) = hp.rfind(':') {
                if let Ok(p) = hp[ci+1..].parse::<u32>() {
                    if p > 65535 { return Err("builder error".to_string()); }
                }
            }
        }
    }
    let mut cmd = Command::new("curl");
    cmd.arg("-s").arg("-L").arg("--max-redirs").arg("10").arg("--compressed");
    cmd.arg("-H").arg("Accept: */*");
    cmd.arg("-H").arg("User-Agent:");
    if cfg.insecure { cmd.arg("-k"); }
    if let Some(ca) = &cfg.cacert {
        // Only pass to curl if it looks like a PEM bundle; original reads the file and adds certs, ignoring non-PEM garbage.
        if let Ok(bytes) = std::fs::read(ca) {
            if bytes.windows(b"-----BEGIN CERTIFICATE-----".len()).any(|w| w == b"-----BEGIN CERTIFICATE-----") {
                cmd.arg("--cacert").arg(ca);
            }
        }
    }
    if let Some(t) = cfg.timeout { cmd.arg("--max-time").arg(fmt_secs(t)); }
    if let Some(t) = cfg.connect_timeout { cmd.arg("--connect-timeout").arg(fmt_secs(t)); }
    // proxy: control explicitly, clearing curl's env behaviour
    cmd.env_remove("http_proxy").env_remove("https_proxy").env_remove("HTTP_PROXY").env_remove("HTTPS_PROXY").env_remove("all_proxy").env_remove("ALL_PROXY");
    if let Some(px) = proxy_for(url) {
        cmd.arg("--proxy").arg(px);
    } else {
        cmd.arg("--noproxy").arg("*");
    }
    cmd.arg(url);
    cmd.stdout(Stdio::piped()).stderr(Stdio::piped());
    let output = match cmd.output() {
        Ok(o) => o,
        Err(_) => {
            // Fallback: very small HTTP/1.0 client for http only
            return fetch_http_fallback(url, &normalized);
        }
    };
    if !output.status.success() {
        return Err(format!("error sending request for url ({})", normalized));
    }
    match serde_json::from_slice::<Value>(&output.stdout) {
        Ok(v) => Ok(v),
        Err(_) => Err(format!("error decoding response body for url ({})", normalized)),
    }
}
fn fmt_secs(t: f64) -> String {
    if t == t.trunc() && t.abs() < 1e15 { format!("{}", t as i64) } else { format!("{}", t) }
}

fn fetch_http_fallback(url: &str, normalized: &str) -> Result<Value, String> {
    // Only plain http; used if curl is unavailable.
    use std::io::{Read, Write};
    let p = crate::uri::parse_uri_reference(url);
    if !matches!(p.scheme.as_deref(), Some("http")) {
        return Err(format!("error sending request for url ({})", normalized));
    }
    let auth = p.authority.clone().unwrap_or_default();
    let hostport = if auth.contains(':') { auth.clone() } else { format!("{}:80", auth) };
    let mut stream = std::net::TcpStream::connect(&hostport).map_err(|_| format!("error sending request for url ({})", normalized))?;
    let path = if p.path.is_empty() { "/".to_string() } else { p.path.clone() } + &p.query.as_ref().map(|q| format!("?{}", q)).unwrap_or_default();
    let req = format!("GET {} HTTP/1.0\r\nHost: {}\r\nAccept: */*\r\n\r\n", path, auth);
    stream.write_all(req.as_bytes()).map_err(|_| format!("error sending request for url ({})", normalized))?;
    let mut buf = Vec::new();
    stream.read_to_end(&mut buf).map_err(|_| format!("error sending request for url ({})", normalized))?;
    // split headers
    let pos = buf.windows(4).position(|w| w == b"\r\n\r\n").map(|i| i + 4).unwrap_or(0);
    match serde_json::from_slice::<Value>(&buf[pos..]) {
        Ok(v) => Ok(v),
        Err(_) => Err(format!("error decoding response body for url ({})", normalized)),
    }
}
