#[derive(Clone, Copy, PartialEq)]
enum OutputStyle { Text, Flag, List, Hierarchical }
impl OutputStyle {
    fn name(&self) -> &'static str { match self { OutputStyle::Text => "text", OutputStyle::Flag => "flag", OutputStyle::List => "list", OutputStyle::Hierarchical => "hierarchical" } }
