struct Cli {
    schema: PathBuf,
    instances: Vec<PathBuf>,
    draft: Option<Draft>,
    assert_format: bool,
    output: OutputStyle,
    errors_only: bool,
    http: HttpConfig,
}

fn build_cli() -> Command {
    Command::new("jsonschema-cli")
        .disable_version_flag(true)
        .arg(Arg::new("SCHEMA")
            .help("The JSON Schema to validate with (i.e. schema.json)")
            .required_unless_present("version")
