}

fn flatten(unit: &Unit, out: &mut Vec<Value>) {
    let mut shallow = unit.clone();
    shallow.children = Vec::new();
    out.push(shallow.to_value());
    for c in &unit.children { flatten(c, out); }
}

fn payload_for(style: OutputStyle, outcome: &Outcome) -> Value {
    match style {
        OutputStyle::Flag => {
            let mut m = Map::new();
            m.insert("valid".into(), Value::Bool(outcome.unit.valid));
            Value::Object(m)
        }
        OutputStyle::List => {
            let mut details = Vec::new();
            flatten(&outcome.unit, &mut details);
            let mut m = Map::new();
            m.insert("details".into(), Value::Array(details));
            m.insert("valid".into(), Value::Bool(outcome.unit.valid));
            Value::Object(m)
        }
        OutputStyle::Hierarchical => outcome.unit.to_value(),
        OutputStyle::Text => unreachable!(),
    }
}

fn print_envelope(style: OutputStyle, outcome: &Outcome, schema_disp: &str, instance_disp: Option<&str>) {
    let mut m = Map::new();
    if let Some(i) = instance_disp { m.insert("instance".into(), Value::String(i.to_string())); }
    m.insert("output".into(), Value::String(style.name().to_string()));
    m.insert("payload".into(), payload_for(style, outcome));
    m.insert("schema".into(), Value::String(schema_disp.to_string()));
    println!("{}", Value::Object(m));
}

fn first_text_error(outcome: &Outcome) -> String {
    if let Some(e) = outcome.text_errors.first() { return e.msg.clone(); }
    // fallback: first error in tree
    fn find(u: &Unit) -> Option<String> {
        if let Some(e) = u.errors.first() { return Some(e.msg.clone()); }
        for c in &u.children { if let Some(s) = find(c) { return Some(s); } }
        None
    }
    find(&outcome.unit).unwrap_or_default()
}

enum MetaSel { FromSchema, Forced(Draft) }

fn explicit_meta_apply(schema: &Value, sel: MetaSel, retriever: Retriever) -> Result<Outcome, String> {
    let (doc_uri, meta_value, meta_draft_std): (String, Value, Option<Draft>) = match &sel {
        MetaSel::Forced(d) => (validator::strip_frag(d.meta_uri()).to_string(), meta::meta_doc_for_draft(*d), Some(*d)),
        MetaSel::FromSchema => {
            let suri = schema.as_object().and_then(|o| o.get("$schema")).and_then(|v| v.as_str()).map(|s| s.to_string());
            match suri {
                Some(u) => {
                    uri::validate_uri_reference(&u).map_err(|e| uri::invalid_uri_error(&u, &e.0))?;
                    if let Some(d) = meta::standard_draft_for_meta_uri(&u) {
                        (validator::strip_frag(d.meta_uri()).to_string(), meta::meta_doc_for_draft(d), Some(d))
                    } else {
                        // retrieve as-is; resource displayed is u as given
                        let no_frag = validator::strip_frag(&u).to_string();
                        let val = retriever.retrieve(&no_frag).map_err(|inner| format!("Resource '{}' is not present in a registry and retrieving it failed: {}", u, inner))?;
                        // fragment handling: pointer into retrieved doc
                        let (_, frag) = uri::split_fragment(&u);
                        let val = match frag {
                            Some(f) if f.starts_with('/') => {
                                let toks = uri::parse_pointer(&uri::percent_decode(f));
                                validator::value_at(&val, &toks).cloned().unwrap_or(val)
                            }
                            _ => val,
                        };
                        (no_frag, val, None)
                    }
                }
                None => (validator::strip_frag(Draft::D2020.meta_uri()).to_string(), meta::meta_doc_for_draft(Draft::D2020), Some(Draft::D2020)),
            }
        }
    };
    let options = BuildOptions { forced_draft: None, assert_format: false, http: retriever.http.clone() };
    let mut registry = Registry::new(options.clone(), retriever);
    registry.add_document(&doc_uri, meta_value.clone()).map_err(|e| e.0)?;
    let dialect = match meta_draft_std {
        Some(d) => validator::Dialect::standard(d),
        None => validator::determine_dialect(&mut registry, &meta_value, &options).map_err(|e| e.0)?,
    };
    let v = Validator::build_no_meta(&doc_uri, registry, options, dialect).map_err(|e| e.0)?;
    Ok(v.validate(schema))
}

fn schema_only(cli: &Cli, schema_value: Value, base_uri: &str) -> i32 {
    let schema_disp = cli.schema.to_string_lossy();
    let meta_outcome = match explicit_meta_apply(&schema_value, MetaSel::FromSchema, Retriever::default_retriever()) {
        Err(e) => {
            if cli.output == OutputStyle::Text {
                println!("Schema is invalid. Error: {}", e);
            } else {
                println!("Error: {}", e);
            }
            return 1;
        }
        Ok(o) => o,
    };
    if !meta_outcome.unit.valid {
        match cli.output {
            OutputStyle::Text => println!("Schema is invalid. Error: {}", first_text_error(&meta_outcome)),
            style => print_envelope(style, &meta_outcome, &schema_disp, None),
        }
        return 1;
    }
    // Meta valid: ensure schema compiles (with HTTP options). Draft/format flags are ignored in this branch of the original.
    let retriever = Retriever::new(cli.http.clone());
    if let Err(e) = retriever.ensure_cacert_readable() {
        println!("Error: {}", e);
        return 1;
    }
    let options = BuildOptions { forced_draft: None, assert_format: false, http: cli.http.clone() };
    let mut registry = Registry::new(options.clone(), retriever);
    let build_res = (|| -> Result<Validator, validator::BuildError> {
        registry.add_document(base_uri, schema_value.clone())?;
        let dialect = validator::determine_dialect(&mut registry, &schema_value, &options)?;
        Validator::build_no_meta(base_uri, registry, options, dialect)
    })();
    match build_res {
        Err(e) => {
            if cli.output == OutputStyle::Text {
                println!("Schema is invalid. Error: {}", e.0);
            } else {
                println!("Error: {}", e.0);
            }
            1
        }
        Ok(_) => {
            if cli.errors_only { return 0; }
            match cli.output {
                OutputStyle::Text => println!("Schema is valid"),
                style => print_envelope(style, &meta_outcome, &schema_disp, None),
            }
            0
        }
    }
}

fn with_instances(cli: &Cli, schema_value: Value, base_uri: &str) -> i32 {
    let schema_disp = cli.schema.to_string_lossy();
    let retriever = Retriever::new(cli.http.clone());
    if let Err(e) = retriever.ensure_cacert_readable() {
        println!("Error: {}", e);
        return 1;
    }
    let options = BuildOptions { forced_draft: cli.draft, assert_format: cli.assert_format, http: cli.http.clone() };
    let mut registry = Registry::new(options.clone(), retriever.clone());
    let build_res = (|| -> Result<Validator, validator::BuildError> {
        registry.add_document(base_uri, schema_value.clone())?;
        Validator::build(base_uri, registry, options.clone())
    })();
    let validator = match build_res {
        Ok(v) => v,
        Err(e) => {
            if cli.output == OutputStyle::Text {
                println!("Schema is invalid. Error: {}", e.0);
                return 1;
            }
            // non-text: try explicit meta validation output
            let sel = match cli.draft { Some(d) => MetaSel::Forced(d), None => MetaSel::FromSchema };
            match explicit_meta_apply(&schema_value, sel, retriever.clone()) {
                Err(e2) => { println!("Error: {}", e2); return 1; }
                Ok(outcome) => {
                    if !outcome.unit.valid {
                        print_envelope(cli.output, &outcome, &schema_disp, None);
                        return 1;
                    }
                    println!("Error: {}", e.0);
                    return 1;
                }
            }
        }
    };
    let mut all_valid = true;
    for inst_path in &cli.instances {
        let inst_disp = inst_path.to_string_lossy();
        let inst_value = match read_json_file(inst_path) {
            Ok(v) => v,
            Err(msg) => { println!("Error: {}", msg); return 1; }
        };
        let outcome = validator.validate(&inst_value);
        let valid = outcome.unit.valid;
        if !valid { all_valid = false; }
        if cli.errors_only && valid { continue; }
        match cli.output {
            OutputStyle::Text => {
                if valid {
                    println!("{} - VALID", inst_disp);
                } else {
                    println!("{} - INVALID. Errors:", inst_disp);
                    let errs = if outcome.text_errors.is_empty() {
                        vec![validator::VError::new("", first_text_error(&outcome))]
                    } else { outcome.text_errors.clone() };
                    for (i, e) in errs.iter().enumerate() {
                        println!("{}. {}", i + 1, e.msg);
                    }
                }
            }
            style => print_envelope(style, &outcome, &schema_disp, Some(&inst_disp)),
        }
    }
    if all_valid { 0 } else { 1 }
}

fn main() -> ExitCode {
    let matches = build_cli().get_matches();
    if matches.get_flag("version") {
        println!("Version: 0.41.0");
        return ExitCode::SUCCESS;
    }
    // Convert timeouts eagerly (mirrors original: huge values panic in Duration::from_secs_f64)
    let connect_timeout = matches.get_one::<f64>("connect_timeout").copied();
    let timeout = matches.get_one::<f64>("timeout").copied();
    if let Some(t) = connect_timeout { let _ = std::time::Duration::from_secs_f64(t); }
    if let Some(t) = timeout { let _ = std::time::Duration::from_secs_f64(t); }

    let schema: PathBuf = matches.get_one::<PathBuf>("SCHEMA").cloned().unwrap_or_default();
    let instances: Vec<PathBuf> = matches.get_many::<PathBuf>("instance").map(|v| v.cloned().collect()).unwrap_or_default();
    let draft = matches.get_one::<String>("draft").and_then(|s| Draft::from_cli(s));
    let output = match matches.get_one::<String>("output").map(|s| s.as_str()) {
        Some("flag") => OutputStyle::Flag,
        Some("list") => OutputStyle::List,
        Some("hierarchical") => OutputStyle::Hierarchical,
        _ => OutputStyle::Text,
    };
    // assert-format last-wins
    let assert_format = {
        let a = matches.get_flag("assert_format");
        let n = matches.get_flag("no_assert_format");
        if a && n {
            let ai = matches.indices_of("assert_format").and_then(|mut i| i.max()).unwrap_or(0);
            let ni = matches.indices_of("no_assert_format").and_then(|mut i| i.max()).unwrap_or(0);
            ai > ni
        } else { a }
    };
    let cli = Cli {
        schema: schema.clone(),
        instances,
        draft,
        assert_format,
        output,
        errors_only: matches.get_flag("errors_only"),
        http: HttpConfig {
            timeout,
            connect_timeout,
            insecure: matches.get_flag("insecure"),
            cacert: matches.get_one::<PathBuf>("cacert").cloned(),
        },
    };
    let schema_value = match read_json_file(&schema) {
        Ok(v) => v,
        Err(msg) => {
            println!("Error: {}", msg);
            return ExitCode::from(1);
        }
    };
    let base_uri = schema_base_uri(&schema);
    let code = if cli.instances.is_empty() {
        schema_only(&cli, schema_value, &base_uri)
    } else {
        with_instances(&cli, schema_value, &base_uri)
    };
    ExitCode::from(code as u8)
}
RS

