new='''pub fn validate_uri_reference(s: &str) -> Result<(), UriError> {
    // Scheme grammar errors take precedence over later generic character errors.
    {
        let seg_end = s.find(|c: char| c == '/' || c == '?' || c == '#').unwrap_or(s.len());
        if let Some(colon) = s[..seg_end].find(':') {
            let scheme = &s[..colon];
            if scheme.is_empty() {
                return Err(UriError("unexpected character at index 0".to_string(), 0));
            }
            let sb = scheme.as_bytes();
            if sb[0] != b'%' {
                if !sb[0].is_ascii_alphabetic() {
                    return Err(UriError("unexpected character at index 0".to_string(), 0));
                }
                for j in 1..sb.len() {
                    let c = sb[j];
                    if c != b'%' && !(c.is_ascii_alphanumeric() || matches!(c, b'+' | b'-' | b'.')) {
                        return Err(UriError(format!("unexpected character at index {}", j), j));
                    }
                }
            }
        }
    }
    let b = s.as_bytes();'''
