{"command":"python3 - << 'PY'
p='src/validator.rs'; s=open(p).read()
# add helper functions before impl Validator compile section (after kw_rank fn)
anchor="impl Validator {\n    pub fn build("
helpers=r'''
pub fn err_not_type(v: &Value, t: &str) -> BuildError { berr(format!("{} is not of type \"{}\"", v, t)) }
pub fn err_not_types(v: &Value, ts: &[&str]) -> BuildError {
    let quoted: Vec<String> = ts.iter().map(|t| format!("\"{}\"", t)).collect();
    berr(format!("{} is not of types {}", v, quoted.join(", ")))
}
pub fn check_number(v: &Value) -> BResult<()> { if v.is_number() { Ok(()) } else { Err(err_not_type(v, "number")) } }
pub fn check_string(v: &Value) -> BResult<()> { if v.is_string() { Ok(()) } else { Err(err_not_type(v, "string")) } }
pub fn check_bool(v: &Value) -> BResult<()> { if v.is_boolean() { Ok(()) } else { Err(err_not_type(v, "boolean")) } }
pub fn check_array(v: &Value) -> BResult<()> { if v.is_array() { Ok(()) } else { Err(err_not_type(v, "array")) } }
pub fn check_object(v: &Value) -> BResult<()> { if v.is_object() { Ok(()) } else { Err(err_not_type(v, "object")) } }
pub fn int_keyword(v: &Value) -> BResult<Option<usize>> {
    if v.is_number() && num::num_is_integer(v) { Ok(num::as_usize(v)) } else { Err(err_not_type(v, "integer")) }
}
pub fn string_list(v: &Value) -> BResult<Vec<String>> {
    check_array(v)?;
    let mut out = Vec::new();
    for el in v.as_array().unwrap() {
        match el.as_str() { Some(s) => out.push(s.to_string()), None => return Err(err_not_type(el, "string")), }
    }
    Ok(out)
}

'''
s=s.replace(anchor, helpers+anchor)

# TYPE
old='''            if let Some(v) = get("type") {
                let mut types = Vec::new();
                match v {
                    Value::String(s) => types.push(s.clone()),
                    Value::Array(a) => { for it in a { if let Some(s) = it.as_str() { types.push(s.to_string()); } } }
                    _ => {}
                }
                types.sort(); types.dedup();'''
new='''            if let Some(v) = get("type").cloned() {
                let mut types = Vec::new();
                const SIMPLE: [&str; 7] = ["array", "boolean", "integer", "null", "number", "object", "string"];
                match &v {
                    Value::String(s) => {
                        if !SIMPLE.contains(&s.as_str()) { return Err(berr("Unexpected type".to_string())); }
                        types.push(s.clone());
                    }
                    Value::Array(a) => {
                        for it in a {
                            match it.as_str() {
                                Some(s) => {
                                    if !SIMPLE.contains(&s) { return Err(berr("Unexpected type".to_string())); }
                                    types.push(s.to_string());
                                }
                                None => return Err(err_not_type(it, "string")),
                            }
                        }
                    }
                    _ => return Err(err_not_types(&v, &["array", "string"])),
                }
                types.sort(); types.dedup();'''
assert old in s; s=s.replace(old,new)

# enum check
s=s.replace('if get("enum").is_some() { keywords.push(Keyword { name: "enum".into(), kind: KwKind::Enum }); compiled_names.insert("enum".into()); }',
 'if let Some(v) = get("enum") { check_array(v)?; keywords.push(Keyword { name: "enum".into(), kind: KwKind::Enum }); compiled_names.insert("enum".into()); }')

# numeric checks: add check_number in each creation (draft4 exclusive separate)
# Draft4 minimum/maximum
s=s.replace('if let Some(v) = get("minimum").cloned() {\n                    let ex =', 'if let Some(v) = get("minimum").cloned() { check_number(&v)?;\n                    let ex =')
s=s.replace('if let Some(v) = get("maximum").cloned() {\n                    let ex =', 'if let Some(v) = get("maximum").cloned() { check_number(&v)?;\n                    let ex =')
# Draft4 exclusive bool check: after compiled insert lines - insert check before if get
s=s.replace('if get("exclusiveMinimum").is_some() { compiled_names.insert("exclusiveMinimum".into()); }', 'if let Some(v) = get("exclusiveMinimum") { check_bool(v)?; compiled_names.insert("exclusiveMinimum".into()); }')
s=s.replace('if get("exclusiveMaximum").is_some() { compiled_names.insert("exclusiveMaximum".into()); }', 'if let Some(v) = get("exclusiveMaximum") { check_bool(v)?; compiled_names.insert("exclusiveMaximum".into()); }')
for kw in ["minimum","maximum","exclusiveMinimum","exclusiveMaximum","multipleOf"]:
    s=s.replace(f'if let Some(v) = get("{kw}").cloned() {{ keywords.push', f'if let Some(v) = get("{kw}").cloned() {{ check_number(&v)?; keywords.push')

# int keywords replacements
import re
for kw in ["minLength","maxLength","minItems","maxItems","minProperties","maxProperties"]:
    pat = f'if let Some(v) = get("{kw}") {{ if let Some(n) = num::as_usize(v)'
    repl = f'if let Some(v) = get("{kw}") {{ if let Some(n) = int_keyword(v)?'
    s=s.replace(pat,repl)

# uniqueItems bool check
s=s.replace('if let Some(v) = get("uniqueItems") { if v.as_bool() == Some(true)', 'if let Some(v) = get("uniqueItems") { check_bool(v)?; if v.as_bool() == Some(true)')

# required
old='''            if get("required").is_some() {
                if merged_required.is_none() && !drop_required {
                    keywords.push(Keyword { name: "required".into(), kind: KwKind::Required(req_list.clone()) });
                }
                compiled_names.insert("required".into());
            }'''
new='''            if get("required").is_some() {
                let req_list = string_list(get("required").unwrap())?;
                if merged_required.is_none() && !drop_required {
                    keywords.push(Keyword { name: "required".into(), kind: KwKind::Required(req_list.clone()) });
                }
                compiled_names.insert("required".into());
            }'''
assert old in s; s=s.replace(old,new)
# req_list first computation uses filter; keep for merged detection (len only) - but if required is not array, string_list later errors. If elements non-string, filter gives shorter len possibly affecting merged detection before error - meta main docs fine.

# dependentRequired
old='''            if let Some(v) = get("dependentRequired") {
                let mut entries = Vec::new();
                if let Some(m) = v.as_object() {
                    for (k, arr) in m {
                        let req: Vec<String> = arr.as_array().map(|a| a.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect()).unwrap_or_default();
                        entries.push((k.clone(), req));
