{"command":"python3 - << 'PY'
from fractions import Fraction
from decimal import Decimal
def show(ns):
  for nstr in ns:
    f=float(nstr)
    ex=Fraction(f)
    dec=Fraction(Decimal(repr(f)))
    exact=int(nstr) if set(nstr)<=set('0123456789') else None
    print(nstr, "f64", f)
    for m in [2,3,7,10,100]:
      print(" ",m, "binary", ex % m == 0, "decstr", dec % m == 0, "exact", (exact % m==0 if exact is not None else None))
show(['123456789012345678901234567890','999999999999999999999999','1000000000000000000000000'])
for nstr in ['3e100','1e100']:
  f=float(nstr); print(nstr, Fraction(f) % 3 == 0, Fraction(Decimal(repr(f)))%3==0)
PY"}

