// ----- BigUint helpers for rational multipleOf -----
fn big_mul(a: &[u32], b: &[u32]) -> Vec<u32> {
    if big_is_zero(a) || big_is_zero(b) { return vec![0]; }
    let mut r = vec![0u64; a.len() + b.len()];
    for i in 0..a.len() {
        let mut carry = 0u64;
        for j in 0..b.len() {
            let cur = r[i + j] + a[i] as u64 * b[j] as u64 + carry;
            r[i + j] = cur % 1_000_000_000;
            carry = cur / 1_000_000_000;
        }
        let mut k = i + b.len();
        while carry > 0 {
            let cur = r[k] + carry;
            r[k] = cur % 1_000_000_000;
            carry = cur / 1_000_000_000;
            k += 1;
        }
    }
    let mut v: Vec<u32> = r.into_iter().map(|x| x as u32).collect();
    while v.len() > 1 && *v.last().unwrap() == 0 { v.pop(); }
    v
}
fn big_from_u64(mut x: u64) -> Vec<u32> {
    let mut v = Vec::new();
    loop {
        v.push((x % 1_000_000_000) as u32);
        x /= 1_000_000_000;
        if x == 0 { break; }
    }
    v
}
// rational as (numerator, denominator) positive bigints (sign irrelevant for divisibility)
fn f64_to_rational(x: f64) -> (Vec<u32>, Vec<u32>) {
    if x == 0.0 { return (vec![0], vec![1]); }
    let bits = x.to_bits();
    let exp_bits = ((bits >> 52) & 0x7ff) as i64;
    let frac = bits & ((1u64 << 52) - 1);
    let (mantissa, e) = if exp_bits == 0 {
        (frac, -1074i64)
    } else {
        (frac | (1u64 << 52), exp_bits - 1023 - 52)
    };
    let mut num = big_from_u64(mantissa);
    let mut den = vec![1u32];
    if e >= 0 {
        for _ in 0..e { num = big_mul_small(&num, 2); }
    } else {
        for _ in 0..(-e) { den = big_mul_small(&den, 2); }
    }
    (num, den)
}
fn decimal_to_rational(d: &Decimal) -> (Vec<u32>, Vec<u32>) {
    if d.sign == 0 { return (vec![0], vec![1]); }
    if d.exp >= 0 {
        (digits_to_big(&d.digits, d.exp).unwrap_or_else(|| vec![0]), vec![1])
    } else {
        let den = digits_to_big("1", -d.exp).unwrap_or_else(|| vec![1]);
        (str_to_big(&d.digits), den)
    }
}
fn rational_is_multiple(a: &(Vec<u32>, Vec<u32>), b: &(Vec<u32>, Vec<u32>)) -> bool {
    // (a.num/a.den) / (b.num/b.den) integer <=> a.num*b.den divisible by a.den*b.num
    if big_is_zero(&b.0) { return false; }
    if big_is_zero(&a.0) { return true; }
    let lhs = big_mul(&a.0, &b.1);
    let rhs = big_mul(&a.1, &b.0);
    if rhs.len() == 1 { return big_mod_small(&lhs, rhs[0] as u64) == 0; }
    big_is_zero(&big_mod_big(&lhs, &rhs))
}
fn convert_for_int_divisor(v: &Value) -> (Vec<u32>, Vec<u32>) {
    let n = v.as_number().unwrap();
    if n.as_i64().is_some() || n.as_u64().is_some() {
        decimal_to_rational(&decimal_of(v).unwrap())
    } else if let Some(f) = n.as_f64() {
        if f.is_finite() { f64_to_rational(f) } else { decimal_to_rational(&decimal_of(v).unwrap()) }
    } else {
        decimal_to_rational(&decimal_of(v).unwrap())
    }
}

pub fn is_multiple_of_values(inst: &Value, div: &Value) -> bool {
    let (Some(da), Some(db)) = (decimal_of(inst), decimal_of(div)) else { return false };
    if db.sign == 0 { return false; }
    if da.sign == 0 { return true; }
    let div_is_float = {
        let s = div.as_number().map(|n| n.to_string()).unwrap_or_default();
        s.contains('.') || s.contains('e') || s.contains('E')
    };
    if div_is_float {
        return is_multiple_of(&da, &db);
    }
    // integer divisor: original promotes non-fitting / float values through f64
    let a = convert_for_int_divisor(inst);
    let b = convert_for_int_divisor(div);
    rational_is_multiple(&a, &b)
}
