    // (a.num/a.den) / (b.num/b.den) integer <=> a.num*b.den divisible by a.den*b.num
    if big_is_zero(&b.0) { return false; }
    if big_is_zero(&a.0) { return true; }
    let lhs = big_mul(&a.0, &b.1);
    let rhs = big_mul(&a.1, &b.0);
    if rhs.len() == 1 { return big_mod_small(&lhs, rhs[0] as u64) == 0; }
    big_is_zero(&big_mod_big(&lhs, &rhs))
}
fn convert_for_int_divisor(v: &Value) -> (Vec<u32>, Vec<u32>) {
    let n = v.as_number().unwrap();
    if n.as_i64().is_some() || n.as_u64().is_some() {
        decimal_to_rational(&decimal_of(v).unwrap())
    } else if let Some(f) = n.as_f64() {
        if f.is_finite() { f64_to_rational(f) } else { decimal_to_rational(&decimal_of(v).unwrap()) }
    } else {
        decimal_to_rational(&decimal_of(v).unwrap())
    }
}

pub fn is_multiple_of_values(inst: &Value, div: &Value) -> bool {
    let (Some(da), Some(db)) = (decimal_of(inst), decimal_of(div)) else { return false };
    if db.sign == 0 { return false; }
    if da.sign == 0 { return true; }
    let div_is_float = {
        let s = div.as_number().map(|n| n.to_string()).unwrap_or_default();
        s.contains('.') || s.contains('e') || s.contains('E')
    };
    if div_is_float {
        return is_multiple_of(&da, &db);
    }
    // integer divisor: original promotes non-fitting / float values through f64
    let a = convert_for_int_divisor(inst);
    let b = convert_for_int_divisor(div);
    rational_is_multiple(&a, &b)
}
