{"command":"python3 - << 'PY'
p='src/formats.rs'; s=open(p).read()
s=s.replace('"email" | "idn-email" => check_email(s),', '"email" => check_email(s, false),\n        "idn-email" => check_email(s, true),')
old_start=s.index('fn check_email')
old_end=s.index('fn check_hostname')
new=r'''fn check_email(s: &str, idn: bool) -> bool {
    // Split into local and domain respecting a quoted-string local part.
    let (local, domain) = if let Some(rest) = s.strip_prefix('"') {
        let mut idx = None;
        let mut chars = rest.char_indices();
        let mut closed = false;
        while let Some((i, c)) = chars.next() {
            if c == '\\' { chars.next(); continue; }
            if c == '"' { idx = Some(i); closed = true; break; }
            if c.is_control() { return false; }
        }
        if !closed { return false; }
        let close = idx.unwrap();
        let after = &rest[close + 1..];
        if !after.starts_with('@') { return false; }
        (s[..close + 2].to_string(), after[1..].to_string())
    } else {
        let parts: Vec<&str> = s.rsplitn(2, '@').collect();
        if parts.len() != 2 { return false; }
        (parts[1].to_string(), parts[0].to_string())
    };
    if domain.is_empty() { return false; }
    if !local.starts_with('"') {
        if local.is_empty() { return false; }
        if local.contains('@') { return false; }
        if local.starts_with('.') || local.ends_with('.') || local.contains("..") { return false; }
        if local.bytes().any(|c| c.is_ascii_control() || matches!(c, b' ' | b'"' | b'(' | b')' | b',' | b':' | b';' | b'<' | b'>' | b'[' | b']' | b'\\')) { return false; }
    }
    if domain.starts_with('[') && domain.ends_with(']') {
        let inside = &domain[1..domain.len()-1];
        return check_ipv4(inside) || inside.parse::<std::net::Ipv6Addr>().is_ok() || inside.to_lowercase().starts_with("ipv6:");
    }
    for label in domain.split('.') {
        if label.is_empty() { return false; }
        if label.starts_with('-') || label.ends_with('-') { return false; }
        if idn {
            if !label.chars().all(|c| c.is_alphanumeric() || c == '-') { return false; }
        } else {
            if !label.bytes().all(|c| c.is_ascii_alphanumeric() || c == b'-') { return false; }
        }
    }
    true
}

'''
