new=r'''pub fn is_valid_format_regex(pat: &str) -> bool {
    if has_escape(pat, &['K']) { return false; }
    if pat.contains("(?P=") { return false; }
    // Brace quantifiers must be well-formed {n} / {n,} / {n,m} with n<=m (outside classes & escapes).
    // Also transform constructs that are syntactically valid ECMAScript but rejected by the engines
    // used as a fallback (numeric backreferences, \p{...} properties, huge repeat counts).
    let mut transformed = String::new();
    let chars: Vec<char> = pat.chars().collect();
    let mut i = 0usize;
    let mut in_class = false;
    while i < chars.len() {
        let c = chars[i];
        if c == '\\' {
            if i + 1 >= chars.len() { transformed.push(c); i += 1; continue; }
            let n = chars[i + 1];
            if n == 'k' { return false; }
            if n.is_ascii_digit() && n != '0' {
                // numeric backreference / octal escape: standalone syntax is valid for the format checker
                transformed.push('a');
                i += 2;
                while i < chars.len() && chars[i].is_ascii_digit() { i += 1; }
                continue;
            }
            if (n == 'p' || n == 'P' || n == 'u') && i + 2 < chars.len() && chars[i + 2] == '{' {
                // copy through closing brace as a placeholder atom
                transformed.push('a');
                i += 2;
                while i < chars.len() && chars[i] != '}' { i += 1; }
                if i < chars.len() { i += 1; }
                continue;
            }
            transformed.push(c);
            transformed.push(n);
            i += 2;
            continue;
        }
        if c == '[' { in_class = true; }
        if c == ']' { in_class = false; }
        if c == '{' && !in_class {
            // parse quantifier
            let mut j = i + 1;
            let mut min_s = String::new();
            while j < chars.len() && chars[j].is_ascii_digit() { min_s.push(chars[j]); j += 1; }
            if min_s.is_empty() { return false; }
            let mut max_s: Option<String> = None;
            if j < chars.len() && chars[j] == ',' {
                j += 1;
                let mut ms = String::new();
                while j < chars.len() && chars[j].is_ascii_digit() { ms.push(chars[j]); j += 1; }
                max_s = Some(ms);
            }
            if j >= chars.len() || chars[j] != '}' { return false; }
            if let Some(ms) = &max_s {
                if !ms.is_empty() {
                    // compare numeric strings by (len, lexicographic) ignoring leading zeros
                    let a = min_s.trim_start_matches('0');
                    let b = ms.trim_start_matches('0');
                    if a.len() > b.len() || (a.len() == b.len() && a > b) { return false; }
                }
            }
            // cap huge counts for the engine check
            let cap = |x: &str| -> String { if x.len() > 5 { "1".to_string() } else { x.to_string() } };
            transformed.push('{');
            transformed.push_str(&cap(&min_s));
            if let Some(ms) = &max_s {
                transformed.push(',');
                if !ms.is_empty() { transformed.push_str(&cap(ms)); }
            }
            transformed.push('}');
            i = j + 1;
            continue;
        }
        transformed.push(c);
        i += 1;
    }
    let display = convert_pattern(&transformed);
    regex::Regex::new(&display).is_ok() || fancy_regex::Regex::new(&display).is_ok()
}'''
