{"command":"python3 - << 'PY'
p='src/uri.rs'; s=open(p).read()
# add normalization helpers and apply in resolve
s += r'''

fn normalize_pct(s: &str) -> String {
    let b = s.as_bytes();
    let mut out = Vec::new();
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'%' && i + 2 < b.len() && b[i+1].is_ascii_hexdigit() && b[i+2].is_ascii_hexdigit() {
            let h = |c: u8| -> u8 { match c { b'0'..=b'9' => c - b'0', b'a'..=b'f' => c - b'a' + 10, b'A'..=b'F' => c - b'A' + 10, _ => 0 } };
            let byte = h(b[i+1]) * 16 + h(b[i+2]);
            if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'.' | b'_' | b'~') {
                out.push(byte);
            } else {
                out.extend_from_slice(format!("%{:02X}", byte).as_bytes());
            }
            i += 3;
        } else {
            out.push(b[i]);
            i += 1;
        }
    }
    String::from_utf8_lossy(&out).to_string()
}
fn normalize_authority_pct(auth: &str) -> String {
    let (userinfo, hostport) = match auth.rfind('@') {
        Some(i) => (Some(auth[..i].to_string()), &auth[i+1..]),
        None => (None, auth),
    };
    let mut out = String::new();
    if let Some(u) = userinfo { out.push_str(&normalize_pct(&u)); out.push('@'); }
    if hostport.starts_with('[') {
        out.push_str(&normalize_pct(hostport).to_lowercase());
    } else if let Some(ci) = hostport.rfind(':') {
        // colon could be port separator only if suffix all digits; otherwise leave case handling simple
        out.push_str(&normalize_pct(&hostport[..ci]).to_lowercase());
        out.push_str(&hostport[ci..]);
    } else {
        out.push_str(&normalize_pct(hostport).to_lowercase());
    }
    out
}
pub fn normalize_parts(p: &UriParts) -> UriParts {
    UriParts {
        scheme: p.scheme.as_ref().map(|s| s.to_lowercase()),
        authority: p.authority.as_ref().map(|a| normalize_authority_pct(a)),
        path: normalize_pct(&p.path),
        query: p.query.as_ref().map(|q| normalize_pct(q)),
        fragment: p.fragment.clone(),
    }
}
'''
s=s.replace('''pub fn resolve(base: &str, reference: &str) -> String {
    let b = parse_uri_reference(base);
    let r = parse_uri_reference(reference);
    let t = resolve_parts(&b, &r);
    t.to_string()
}''','''pub fn resolve(base: &str, reference: &str) -> String {
    let b = parse_uri_reference(base);
    let r = parse_uri_reference(reference);
    let t = normalize_parts(&resolve_parts(&b, &r));
    t.to_string()
}''')
open(p,'w').write(s)

p='src/validator.rs'; s=open(p).read()
s=s.replace("let anchor = uri::percent_decode(f);", "let anchor = f.to_string();")
open(p,'w').write(s)

